1	/**
2	 * Input aggregation: keyboard, mouse (pointer-locked), and gamepad, exposed as
3	 * a stable per-frame snapshot so gameplay never touches raw DOM events.
4	 *
5	 * Edge queries (`pressed`, `released`) are valid only during the frame in which
6	 * the transition happened — read them in update(), not fixedUpdate().
7	 */
8	
9	export const ACTIONS = {
10	  forward: ['KeyW', 'ArrowUp'],
11	  back: ['KeyS', 'ArrowDown'],
12	  left: ['KeyA', 'ArrowLeft'],
13	  right: ['KeyD', 'ArrowRight'],
14	  jump: ['Space'],
15	  crouch: ['ControlLeft', 'KeyC'],
16	  prone: ['KeyZ'],
17	  sprint: ['ShiftLeft'],
18	  reload: ['KeyR'],
19	  use: ['KeyF'],
20	  melee: ['KeyV'],
21	  leanLeft: ['KeyQ'],
22	  leanRight: ['KeyE'],
23	  swapWeapon: ['Digit1', 'Digit2', 'Tab'],
24	  grenade: ['KeyG'],
25	  flashlight: ['KeyT'],
26	  pause: ['Escape'],
27	};
28	
29	// Only keys actually consumed by gameplay may suppress a browser default.
30	// F11, refresh/devtools shortcuts and keyboard navigation must stay native.
31	const GAMEPLAY_CODES = new Set([
32	  ...Object.values(ACTIONS).flat(),
33	  'KeyB',
34	  'KeyI',
35	  'Digit3',
36	]);
37	
38	export class Input {
39	  constructor(canvas, config) {
40	    this.canvas = canvas;
41	    this.config = config;
42	
43	    this.down = new Set(); // codes currently held
44	    this._pressed = new Set(); // went down this frame
45	    this._released = new Set(); // went up this frame
46	    this._pendingDown = new Set();
47	    this._pendingUp = new Set();
48	
49	    /** Accumulated pointer delta for this frame, in radians after sensitivity. */
50	    this.look = { x: 0, y: 0 };
51	    this._rawLook = { x: 0, y: 0 };
52	    this.wheel = 0;
53	    this._pendingWheel = 0;
54	
55	    this.pointerLocked = false;
56	    this.enabled = true;
57	    /** Optional synchronous Escape handler installed by the UI subsystem. */
58	    this.onPause = null;
59	    /** Set true by capture mode so scripted shots aren't fought by real input. */
60	    this.frozen = false;
61	
62	    this.gamepadIndex = null;
63	    this.stick = { moveX: 0, moveY: 0, lookX: 0, lookY: 0 };
64	
65	    this._bound = {
66	      keydown: this._onKeyDown.bind(this),
67	      keyup: this._onKeyUp.bind(this),
68	      mousedown: this._onMouseDown.bind(this),
69	      mouseup: this._onMouseUp.bind(this),
70	      mousemove: this._onMouseMove.bind(this),
71	      wheel: this._onWheel.bind(this),
72	      lockchange: this._onLockChange.bind(this),
73	      blur: this._onBlur.bind(this),
74	      contextmenu: (e) => e.preventDefault(),
75	    };
76	  }
77	
78	  attach() {
79	    addEventListener('keydown', this._bound.keydown);
80	    addEventListener('keyup', this._bound.keyup);
81	    addEventListener('mousedown', this._bound.mousedown);
82	    addEventListener('mouseup', this._bound.mouseup);
83	    addEventListener('mousemove', this._bound.mousemove);
84	    addEventListener('wheel', this._bound.wheel, { passive: true });
85	    addEventListener('blur', this._bound.blur);
86	    document.addEventListener('pointerlockchange', this._bound.lockchange);
87	    this.canvas.addEventListener('contextmenu', this._bound.contextmenu);
88	  }
89	
90	  detach() {
91	    removeEventListener('keydown', this._bound.keydown);
92	    removeEventListener('keyup', this._bound.keyup);
93	    removeEventListener('mousedown', this._bound.mousedown);
94	    removeEventListener('mouseup', this._bound.mouseup);
95	    removeEventListener('mousemove', this._bound.mousemove);
96	    removeEventListener('wheel', this._bound.wheel);
97	    removeEventListener('blur', this._bound.blur);
98	    document.removeEventListener('pointerlockchange', this._bound.lockchange);
99	    this.canvas.removeEventListener('contextmenu', this._bound.contextmenu);
100	  }
101	
102	  requestPointerLock() {
103	    if (document.pointerLockElement === this.canvas) return Promise.resolve(true);
104	    const request = this.canvas.requestPointerLock;
105	    if (typeof request !== 'function') return Promise.resolve(false);
106	
107	    // Modern Chrome returns a promise. Convert rejection into `false` so callers
108	    // can keep the pause menu open instead of producing an unhandled page error.
109	    try {
110	      const result = request.call(this.canvas);
111	      if (result && typeof result.then === 'function') {
112	        return result.then(() => true, () => false);
113	      }
114	      // Legacy browsers return void after accepting the request.
115	      return Promise.resolve(true);
116	    } catch {
117	      return Promise.resolve(false);
118	    }
119	  }
120	
121	  _onKeyDown(e) {
122	    if (!this.enabled || e.repeat) return;
123	
124	    // Run Escape synchronously inside the trusted key event. That gives Resume
125	    // a valid user activation for requestPointerLock(), while pointer-lock loss
126	    // remains a fallback for browsers that reserve Escape and send no key event.
127	    if (e.code === 'Escape' && typeof this.onPause === 'function') {
128	      try {
129	        if (this.onPause(e) !== false) return;
130	      } catch (err) {
131	        console.error('[input] pause handler failed', err);
132	      }
133	    }
134	
135	    if (!GAMEPLAY_CODES.has(e.code)) return;
136	    const fromControl = !!e.target?.closest?.('button, input, select, textarea, a[href], [contenteditable="true"]');
137	    const modifiedShortcut =
138	      (e.metaKey && !e.code.startsWith('Meta')) ||
139	      (e.ctrlKey && !e.code.startsWith('Control')) ||
140	      (e.altKey && !e.code.startsWith('Alt'));
141	
142	    // While unlocked, keyboard input belongs to the pause menu/browser. In
143	    // particular, Tab and Space must continue to operate focused controls.
144	    if (fromControl || modifiedShortcut || (!this.pointerLocked && e.code !== 'Escape')) return;
145	
146	    e.preventDefault();
147	    this._pendingDown.add(e.code);
148	  }
149	
150	  _onKeyUp(e) {
151	    if (!this.enabled || !GAMEPLAY_CODES.has(e.code)) return;
152	    this._pendingUp.add(e.code);
153	  }
154	
155	  _onMouseDown(e) {
156	    if (!this.enabled || (!this.pointerLocked && e.target !== this.canvas)) return;
157	    if (!this.pointerLocked && e.button === 0) this.requestPointerLock();
158	    this._pendingDown.add(`Mouse${e.button}`);
159	  }
160	
161	  _onMouseUp(e) {
162	    if (!this.enabled || (!this.pointerLocked && e.target !== this.canvas)) return;
163	    this._pendingUp.add(`Mouse${e.button}`);
164	  }
165	
166	  _onMouseMove(e) {
167	    if (!this.enabled || !this.pointerLocked || this.frozen) return;
168	    // movementX/Y is already relative and unaffected by cursor clamping.
169	    this._rawLook.x += e.movementX ?? 0;
170	    this._rawLook.y += e.movementY ?? 0;
171	  }
172	
173	  _onWheel(e) {
174	    if (!this.enabled || (!this.pointerLocked && e.target !== this.canvas)) return;
175	    this._pendingWheel += Math.sign(e.deltaY);
176	  }
177	
178	  _onLockChange() {
179	    this.pointerLocked = document.pointerLockElement === this.canvas;
180	    if (!this.pointerLocked) this._onBlur();
181	  }
182	
183	  /** Losing focus must release every held key, or the player runs forever. */
184	  _onBlur() {
185	    for (const code of this.down) this._pendingUp.add(code);
186	    this._rawLook.x = 0;
187	    this._rawLook.y = 0;
188	  }
189	
190	  beginFrame() {
191	    this._pressed.clear();
192	    this._released.clear();
193	
194	    for (const code of this._pendingDown) {
195	      if (!this.down.has(code)) {
196	        this.down.add(code);
197	        this._pressed.add(code);
198	      }
199	    }
200	    for (const code of this._pendingUp) {
201	      if (this.down.delete(code)) this._released.add(code);
202	    }
203	    this._pendingDown.clear();
204	    this._pendingUp.clear();
205	
206	    const s = this.config.sensitivity;
207	    this.look.x = this.frozen ? 0 : this._rawLook.x * s;
208	    this.look.y = this.frozen ? 0 : this._rawLook.y * s * (this.config.invertY ? -1 : 1);
209	    this._rawLook.x = 0;
210	    this._rawLook.y = 0;
211	
212	    this.wheel = this._pendingWheel;
213	    this._pendingWheel = 0;
214	
215	    this._pollGamepad();
216	  }
217	
218	  endFrame() {}
219	
220	  _pollGamepad() {
221	    const pads = navigator.getGamepads?.() ?? [];
222	    const pad = pads[this.gamepadIndex ?? 0] ?? pads.find(Boolean);
223	    if (!pad) {
224	      this.stick.moveX = this.stick.moveY = this.stick.lookX = this.stick.lookY = 0;
225	      return;
226	    }
227	    const dz = (v) => (Math.abs(v) < 0.16 ? 0 : (v - Math.sign(v) * 0.16) / 0.84);
228	    this.stick.moveX = dz(pad.axes[0] ?? 0);
229	    this.stick.moveY = dz(pad.axes[1] ?? 0);
230	    // Cubic response curve on the look stick — fine aim near centre, fast flicks at the edge.
231	    const curve = (v) => Math.sign(v) * Math.abs(v) ** 2.4;
232	    this.stick.lookX = curve(dz(pad.axes[2] ?? 0));
233	    this.stick.lookY = curve(dz(pad.axes[3] ?? 0));
234	  }
235	
236	  /** True while any key bound to `action` is held. */
237	  action(name) {
238	    const codes = ACTIONS[name];
239	    if (!codes) return false;
240	    for (const c of codes) if (this.down.has(c)) return true;
241	    return false;
242	  }
243	
244	  actionPressed(name) {
245	    const codes = ACTIONS[name];
246	    if (!codes) return false;
247	    for (const c of codes) if (this._pressed.has(c)) return true;
248	    return false;
249	  }
250	
251	  held(code) {
252	    return this.down.has(code);
253	  }
254	
255	  pressed(code) {
256	    return this._pressed.has(code);
257	  }
258	
259	  released(code) {
260	    return this._released.has(code);
261	  }
262	
263	  get fire() {
264	    return this.down.has('Mouse0');
265	  }
266	
267	  get firePressed() {
268	    return this._pressed.has('Mouse0');
269	  }
270	
271	  get ads() {
272	    return this.down.has('Mouse2');
273	  }
274	
275	  /** Normalised WASD + left-stick movement, clamped to the unit disc so
276	   *  diagonals aren't faster than cardinals. */
277	  moveVector(out = { x: 0, y: 0 }) {
278	    let x = (this.action('right') ? 1 : 0) - (this.action('left') ? 1 : 0);
279	    let y = (this.action('forward') ? 1 : 0) - (this.action('back') ? 1 : 0);
280	    x += this.stick.moveX;
281	    y -= this.stick.moveY;
282	    const len = Math.hypot(x, y);
283	    if (len > 1) {
284	      x /= len;
285	      y /= len;
286	    }
287	    out.x = x;
288	    out.y = y;
289	    return out;
290	  }
291	}
