1	/**
2	 * Health, regeneration, suppression and the damage-direction model.
3	 *
4	 * Behaviour matches the CoD contract: no health pickups, a delay after the last
5	 * hit, then a fast refill. Damage arriving from a direction produces an
6	 * indicator (angle in *view* space, so the HUD can draw it without knowing
7	 * anything about the player's transform) and a matching camera impulse, so a hit
8	 * is felt before it is read.
9	 *
10	 * Suppression is a separate 0..1 pool fed by near misses, hits and blasts. It
11	 * widens the breathing sway and adds a little shake — the same trick CoD uses to
12	 * make being shot at feel dangerous without taking control away.
13	 */
14	
15	import * as THREE from 'three';
16	import { HEALTH } from './tuning.js';
17	import { clamp01, approach, lerp, DEG } from './springs.js';
18	
19	export class Health {
20	  constructor(ctx, rig) {
21	    this.ctx = ctx;
22	    this.rig = rig;
23	    this.max = HEALTH.max;
24	    this.value = HEALTH.max;
25	    this.dead = false;
26	    this.regenerating = false;
27	    this.lastDamageTime = -100;
28	    this.suppression = 0;
29	    this.hitFlash = 0;
30	
31	    /** Direction indicators, oldest first. angle is radians, 0 = straight ahead. */
32	    this.indicators = [];
33	    for (let i = 0; i < HEALTH.indicatorMax; i++) {
34	      this.indicators.push({ active: false, angle: 0, amount: 0, life: 0, worldX: 0, worldY: 0, worldZ: 0 });
35	    }
36	
37	    // Heartbeat: phase 0..1 per beat, with a double-thump envelope.
38	    this.beatPhase = 0;
39	    this.pulse = 0;
40	    this.effect = 0; // 0..1 overall low-health treatment weight
41	
42	    this._payload = { amount: 0, from: new THREE.Vector3(), health: 0, direction: 0, critical: false };
43	    this._statePayload = {
44	      health: HEALTH.max, fraction: 1, low: false, critical: false,
45	      regenerating: false, suppression: 0, dead: false,
46	    };
47	    this._emitTimer = 0;
48	    this._lastEmitHealth = HEALTH.max;
49	    this._beat = { strength: 0, fraction: 1 };
50	  }
51	
52	  get fraction() {
53	    return clamp01(this.value / this.max);
54	  }
55	
56	  get low() {
57	    return this.fraction < HEALTH.lowThreshold;
58	  }
59	
60	  get critical() {
61	    return this.fraction < HEALTH.criticalThreshold;
62	  }
63	
64	  reset(full = true) {
65	    if (full) this.value = this.max;
66	    this.dead = false;
67	    this.suppression = 0;
68	    this.hitFlash = 0;
69	    this.lastDamageTime = -100;
70	    for (let k = 0; k < this.indicators.length; k++) this.indicators[k].active = false;
71	  }
72	
73	  /* ==================================================================== */
74	
75	  /**
76	   * @param {number} amount
77	   * @param {THREE.Vector3|null} from  world position of the attacker/blast
78	   * @param {object} opts { yaw, type, suppress }
79	   */
80	  damage(amount, from, opts = {}) {
81	    if (this.dead || amount <= 0) return 0;
82	    const before = this.value;
83	    this.value = Math.max(0, this.value - amount);
84	    this.lastDamageTime = this.ctx.time.elapsed;
85	    this.regenerating = false;
86	    const dealt = before - this.value;
87	
88	    // ---- direction in view space ---------------------------------------
89	    let angle = 0;
90	    if (from) {
91	      const yaw = opts.yaw ?? this.ctx.camera.rotation.y;
92	      const dx = from.x - this.ctx.camera.position.x;
93	      const dz = from.z - this.ctx.camera.position.z;
94	      // Forward at yaw is (-sin, -cos); right is (cos, -sin).
95	      const f = -Math.sin(yaw) * dx - Math.cos(yaw) * dz;
96	      const r = Math.cos(yaw) * dx - Math.sin(yaw) * dz;
97	      angle = Math.atan2(r, f);
98	      this._pushIndicator(angle, dealt, from);
99	    }
100	
101	    // ---- felt response --------------------------------------------------
102	    const severity = clamp01(dealt / 45);
103	    this.hitFlash = clamp01(this.hitFlash + HEALTH.effect.hitFlash * (0.4 + severity));
104	    this.addSuppression(HEALTH.suppression.perHit * (0.5 + severity));
105	    if (this.rig) {
106	      // Punch the camera away from the hit: pitch up, yaw and roll off-axis.
107	      const s = 0.6 + severity * 1.9;
108	      this.rig.addRecoil(
109	        (1.1 + severity) * DEG * s * 0.7,
110	        -Math.sin(angle) * (1.4 * DEG) * s,
111	        -Math.sin(angle) * (2.2 * DEG) * s,
112	        0.008 * s
113	      );
114	      this.rig.addTrauma(0.22 * s);
115	    }
116	
117	    const p = this._payload;
118	    p.amount = dealt;
119	    p.health = this.value;
120	    p.direction = angle;
121	    p.critical = this.critical;
122	    if (from) p.from.copy(from);
123	    else p.from.set(this.ctx.camera.position.x, this.ctx.camera.position.y, this.ctx.camera.position.z);
124	    this.ctx.events.emit('damage:taken', p);
125	
126	    if (this.value <= 0) {
127	      this.dead = true;
128	      this.ctx.events.emit('player:death', { position: this.ctx.camera.position });
129	      // (one allocation on death is fine — it happens once)
130	    }
131	    this._emitState(true);
132	    return dealt;
133	  }
134	
135	  heal(amount) {
136	    this.value = Math.min(this.max, this.value + amount);
137	  }
138	
139	  addSuppression(a) {
140	    this.suppression = clamp01(this.suppression + a);
141	  }
142	
143	  _pushIndicator(angle, amount, from) {
144	    // Reuse the slot pointing the most similar way, else the oldest.
145	    let slot = null;
146	    let oldest = null;
147	    for (let k = 0; k < this.indicators.length; k++) {
148	      const i = this.indicators[k];
149	      if (!i.active) { slot = i; break; }
150	      if (Math.abs(angle - i.angle) < 0.5) { slot = i; break; }
151	      if (!oldest || i.life > oldest.life) oldest = i;
152	    }
153	    slot = slot ?? oldest ?? this.indicators[0];
154	    slot.active = true;
155	    slot.angle = angle;
156	    slot.amount = Math.max(slot.active ? slot.amount * 0.5 : 0, amount);
157	    slot.life = 0;
158	    slot.worldX = from.x; slot.worldY = from.y; slot.worldZ = from.z;
159	  }
160	
161	  /* ==================================================================== */
162	
163	  update(dt) {
164	    const H = HEALTH;
165	
166	    // ---- regeneration ---------------------------------------------------
167	    const since = this.ctx.time.elapsed - this.lastDamageTime;
168	    if (!this.dead && this.value < this.max && since > H.regenDelay) {
169	      this.regenerating = true;
170	      // Ramp in so the recovery has a shape rather than a step.
171	      const ramp = clamp01((since - H.regenDelay) / H.regenRamp);
172	      this.value = Math.min(this.max, this.value + H.regenRate * ramp * dt);
173	    } else if (this.value >= this.max) {
174	      this.regenerating = false;
175	    }
176	
177	    // ---- pools ----------------------------------------------------------
178	    this.suppression = Math.max(0, this.suppression - H.suppression.decay * dt);
179	    this.hitFlash = approach(this.hitFlash, 0, H.effect.hitFlashTau, dt);
180	
181	    for (let k = 0; k < this.indicators.length; k++) {
182	      const i = this.indicators[k];
183	      if (!i.active) continue;
184	      i.life += dt;
185	      if (i.life > H.indicatorTime) i.active = false;
186	    }
187	
188	    // ---- low-health treatment weight ------------------------------------
189	    const f = this.fraction;
190	    const target = clamp01((H.lowThreshold - f) / H.lowThreshold);
191	    this.effect = approach(this.effect, target, 0.25, dt);
192	
193	    // ---- heartbeat ------------------------------------------------------
194	    if (this.effect > 0.02) {
195	      const freq = lerp(H.effect.heartbeatMin, H.effect.heartbeatMax, clamp01(1 - f / H.lowThreshold));
196	      this.beatPhase += dt * freq;
197	      if (this.beatPhase >= 1) {
198	        this.beatPhase -= Math.floor(this.beatPhase);
199	        this._beat.strength = this.effect;
200	        this._beat.fraction = f;
201	        this.ctx.events.emit('player:heartbeat', this._beat);
202	      }
203	      // lub-dub: two gaussian thumps 0.16 of a cycle apart
204	      const t = this.beatPhase;
205	      const thump = (c, w, g) => g * Math.exp(-((t - c) * (t - c)) / (2 * w * w));
206	      this.pulse = (thump(0.06, 0.035, 1) + thump(0.22, 0.045, 0.62)) * this.effect;
207	    } else {
208	      this.beatPhase = 0;
209	      this.pulse = 0;
210	    }
211	
212	    // ---- suppression feel ------------------------------------------------
213	    if (this.rig && this.suppression > 0.02) {
214	      this.rig.addTrauma(this.suppression * H.suppression.shakeScale * dt);
215	    }
216	
217	    this._emitTimer -= dt;
218	    if (this._emitTimer <= 0) {
219	      this._emitTimer = 0.1;
220	      if (Math.abs(this.value - this._lastEmitHealth) > 0.4) this._emitState(false);
221	    }
222	  }
223	
224	  _emitState(force) {
225	    const s = this._statePayload;
226	    const wasLow = s.low;
227	    s.health = this.value;
228	    s.fraction = this.fraction;
229	    s.low = this.low;
230	    s.critical = this.critical;
231	    s.regenerating = this.regenerating;
232	    s.suppression = this.suppression;
233	    s.dead = this.dead;
234	    this._lastEmitHealth = this.value;
235	    s.changedLowState = wasLow !== s.low;
236	    s.forced = !!force;
237	    this.ctx.events.emit('player:health', s);
238	  }
239	}
