cd "/Users/kentoky/Documents/React Projects/Claude-of-Duty" && cat > /tmp/s.mjs <<'EOF'
import fs from 'fs';
import path from 'path';
const [pattern, ...roots] = process.argv.slice(2);
const re = new RegExp(pattern, 'i');
const skip = new Set(['node_modules', '.git', 'dist', 'shared-docs', 'History', 'Notes']);
function walk(d) {
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    if (skip.has(e.name)) continue;
    const p = path.join(d, e.name);
    if (e.isDirectory()) walk(p);
    else if (/\.(m?js|jsx|ts|html|css|json|md)$/.test(e.name)) {
      let t; try { t = fs.readFileSync(p, 'utf8'); } catch { continue; }
      t.split('\n').forEach((l, i) => { if (re.test(l)) console.log(`${p}:${i + 1}: ${l.trim().slice(0, 200)}`); });
    }
  }
}
walk(roots[0] || '.');
EOF
node /tmp/s.mjs "player:death" .

