19	/**
20	 * ===========================================================================
21	 * HUD / UI subsystem
22	 * ===========================================================================
23	 *
24	 * A DOM+CSS overlay (see style.js for the design system) driven entirely from
25	 * `lateUpdate`, after the camera has reached its final transform for the frame.
26	 * Nothing animates on a CSS keyframe or transition: every value is integrated
27	 * from `dt` here, which is what makes the capture harness deterministic and
28	 * lets the whole HUD freeze correctly when the game is paused.
29	 *
30	 * ---------------------------------------------------------------------------
31	 * PUBLIC API — `const ui = ctx.get('ui')`
32	 * ---------------------------------------------------------------------------
33	 *   ui.hitmarker(kind)                  'hit' | 'armour' | 'head' | 'kill'
34	 *   ui.damageNumber(worldPos, n, kind)  'hit' | 'hs' | 'armour' | 'kill'
35	 *   ui.hurt(amount, dirX, dirZ)         directional arc + flash + flinch
36	 *   ui.killfeed.push({attacker,victim,headshot,mine,attackerFriendly})
37	 *   ui.banner.show(title, sub, life)    kill / objective confirmation
38	 *   ui.setPrompt({key,text,sub,progress}) / ui.clearPrompt()
39	 *   ui.setObjectives([{position,label,name}])
40	 *   ui.setBlips([{x,z,kind:'enemy'|'friend',heading}])
