156	/**
157	 * Hold a movement key down for the whole run, so the camera TRANSLATES.
158	 *
159	 * driveLook above turns the camera and nothing else, and that turned out to
160	 * flatter one measurement badly. A pure rotation moves every pixel by very
161	 * nearly the same screen delta whatever its depth, because parallax is a
162	 * function of translation alone. So a velocity buffer sampled under rotation is
163	 * almost constant across a silhouette -- and TAA's whole reason for dilating the
164	 * velocity to the closest-depth neighbour is that it is NOT constant across a
165	 * silhouette. Measured on a rotating-only camera, the nine-tap dilation
166	 * therefore scores as worth nothing at all, which is an artefact of the input,
167	 * not a property of the shader.
168	 *
169	 * The key is pushed through `_pendingDown`, the same set a real keydown writes,
170	 * so it passes through the input update, the player controller, the collision
171	 * response and the head bob rather than teleporting the camera. It is held from
172	 * frame zero because a walking player needs a few frames to reach speed.
173	 */
174	function driveMove(engine, code = 'KeyW') {
175	  if (!code || code === 'none') return () => {};
176	  const input = engine.input;
177	  input._pendingDown.add(code);
178	  return () => { input._pendingUp.add(code); };
179	}
