181	/**
182	 * Play a scripted input timeline: `[frame, code, 'down'|'up']` triples, plus an
183	 * optional constant yaw in degrees per frame.
184	 *
185	 * driveLook turns and driveMove walks, but the viewmodel's screen rectangle is
186	 * driven by neither. That rectangle moves when the WEAPON moves, and the weapon
187	 * moves on recoil, on the ADS transition, on a reload and on a swap — all of
188	 * them button EDGES rather than held state, so pricing them needs a timeline
189	 * rather than a switch. Firing is also the only way anything is added to
190	 * `viewScene` mid-frame: the muzzle flash is created by the weapon system when
191	 * the round leaves, so a run that never pulls the trigger never tests the case
192	 * the bound was written to survive.
193	 *
194	 * Codes go through `_pendingDown`/`_pendingUp`, the same sets a real keydown or
195	 * mousedown writes, so everything downstream — the recoil impulse, the ADS
196	 * blend, the animation state machine — happens for the ordinary reason instead
197	 * of being poked onto the viewmodel from outside.
198	 */
199	function driveScript(engine, events, degPerFrame = 0) {
200	  const input = engine.input;
201	  const px = degPerFrame
202	    ? (degPerFrame * Math.PI) / 180 / (input.config?.sensitivity || 0.0022)
203	    : 0;
204	  const at = new Map();
205	  for (const [f, code, kind] of events) {
206	    if (!at.has(f)) at.set(f, []);
207	    at.get(f).push([code, kind]);
208	  }
209	  const orig = engine.step.bind(engine);
210	  let i = 0;
211	  engine.step = (t) => {
212	    for (const [code, kind] of at.get(i) ?? []) {
213	      (kind === 'up' ? input._pendingUp : input._pendingDown).add(code);
214	    }
215	    if (px) input._rawLook.x += px;
216	    i++;
217	    return orig(t);
218	  };
219	  return () => {
220	    engine.step = orig;
221	    for (const code of input.down) input._pendingUp.add(code);
222	  };
223	}
