705	  _tryVault() {
706	    const phys = this.phys;
707	    const fwd = this._v.set(Math.sin(this.yaw), 0, Math.cos(this.yaw));
708	    const low = phys.raycast(
709	      this.position.x, this.position.y + 0.35, this.position.z,
710	      fwd.x, 0, fwd.z, 0.85, phys.MASK.WORLD
711	    );
712	    if (!low.hit) return;
713	    const high = phys.raycastAny(
714	      this.position.x, this.position.y + 1.25, this.position.z,
715	      fwd.x, 0, fwd.z, 1.1, phys.MASK.WORLD
716	    );
717	    if (high) return; // a wall, not a ledge
718	    // landing spot on the other side
719	    const lx = this.position.x + fwd.x * 1.5;
720	    const lz = this.position.z + fwd.z * 1.5;
721	    const y = this.ai.groundAt(lx, lz, this.position.y + 2.2);
722	    if (!Number.isFinite(y) || Math.abs(y - this.position.y) > 1.3) return;
723	    this.vaultCooldown = 2.5;
