734	  _shoot(dt) {
735	    // where the gun is pointing: lead toward the target with human error
736	    const t = this.hasTarget || this.lastKnownAge < 3 ? this.lastKnown : null;
737	    if (t) {
738	      // aim at the chest, not the feet
