773	  }
774	
775	  _fireRound() {
776	    const an = this.animator;
777	    const origin = an.muzzleWorld;
778	    const dir = this._muzzleDir.copy(an.muzzleDir);
779	    // cone of fire: worse when suppressed, better the longer we have been aiming
780	    const spread = this.spread * (1 + this.suppression * 1.5);
781	    dir.x += this.rng.gauss() * spread;
782	    dir.y += this.rng.gauss() * spread * 0.8;
783	    dir.z += this.rng.gauss() * spread;
784	    dir.normalize();
785	    an.fire(1);
786	    this.ai.onAgentFire(this, origin, dir);
787	  }
788	
789	  _throwGrenade(target) {
790	    this.grenadeCooldown = this.rng.range(16, 34);
791	    this.hasGrenade = false;
792	    const from = this._v.copy(this.animator.muzzleWorld);
