1	import * as THREE from 'three';
2	import { Registry, EventBus } from './registry.js';
3	import { FIXED_DT, MAX_SUBSTEPS } from './config.js';
4	import { Input } from './input.js';
5	import { Rng } from './rng.js';
6	
7	/**
8	 * The Engine owns the frame loop and the shared context handed to every
9	 * subsystem. It does NOT know what any subsystem does — it only sequences them.
10	 *
11	 * Frame order:
12	 *   1. input.beginFrame()
13	 *   2. fixedUpdate(FIXED_DT) xN   — physics, deterministic gameplay
14	 *   3. update(dt)                 — animation, cameras, AI decisions
15	 *   4. lateUpdate(dt)             — anything that must observe final transforms
16	 *   5. render subsystem draws
17	 *   6. input.endFrame()
18	 */
19	export class Engine {
20	  constructor({ canvas, config }) {
21	    this.canvas = canvas;
22	    this.config = config;
23	    this.registry = new Registry();
24	    this.events = new EventBus();
25	    this.input = new Input(canvas, config);
26	    this.rng = new Rng(config.deterministic ? 0x5eed1234 : (Math.random() * 2 ** 32) >>> 0);
27	
28	    this.scene = new THREE.Scene();
29	    this.camera = new THREE.PerspectiveCamera(config.fov, 1, 0.05, 1200);
30	    this.camera.rotation.order = 'YXZ';
31	
32	    /** Separate scene+camera for the first-person viewmodel, drawn with its own
33	     *  near plane so hands/weapon never clip into world geometry. */
34	    this.viewScene = new THREE.Scene();
35	    this.viewCamera = new THREE.PerspectiveCamera(60, 1, 0.005, 12);
36	
37	    this.time = {
38	      /** Seconds since start, scaled. */ elapsed: 0,
39	      /** Unscaled wall-clock seconds since start. */ raw: 0,
40	      /** Last frame delta, scaled and clamped. */ dt: 0,
41	      /** Fixed step. */ fixed: FIXED_DT,
42	      /** Interpolation alpha between the last two physics steps, 0..1. */ alpha: 0,
43	      scale: 1,
44	      frame: 0,
45	    };
46	
47	    this.ctx = {
48	      engine: this,
49	      scene: this.scene,
50	      camera: this.camera,
51	      viewScene: this.viewScene,
52	      viewCamera: this.viewCamera,
53	      canvas,
54	      config,
55	      events: this.events,
56	      input: this.input,
57	      time: this.time,
58	      rng: this.rng,
59	      get: (id) => this.registry.get(id),
60	      peek: (id) => this.registry.peek(id),
61	      has: (id) => this.registry.has(id),
62	    };
63	
64	    this._accum = 0;
65	    this._last = 0;
66	    this._running = false;
67	    this._onResize = () => this.resize();
68	  }
69	
70	  add(SystemClass, opts) {
71	    this.registry.add(new SystemClass(opts));
72	    return this;
73	  }
74	
75	  async init({ onProgress = null, yieldBetween = false } = {}) {
76	    const order = this.registry.resolve();
77	    const total = order.length;
78	    for (let index = 0; index < total; index++) {
79	      const sys = order[index];
80	      const id = sys.constructor.id;
81	      onProgress?.({ id, index, total, phase: 'start', progress: index / total });
82	      // Yield after publishing the next stage, not after it finished, so the
83	      // browser can actually paint "Weltgeometrie …" before that heavy stage.
84	      if (yieldBetween) await new Promise((resolve) => setTimeout(resolve, 0));
85	      const t0 = performance.now();
86	      await sys.init?.(this.ctx);
87	      const ms = performance.now() - t0;
88	      if (ms > 50) console.info(`[engine] ${id} init ${ms.toFixed(0)}ms`);
89	      onProgress?.({ id, index, total, phase: 'done', ms, progress: (index + 1) / total });
90	
91	    }
92	    this.input.attach();
93	    addEventListener('resize', this._onResize);
94	    this.resize();
95	    return this;
96	  }
97	
98	  resize() {
99	    const w = Math.max(1, this.canvas.clientWidth || innerWidth);
100	    const h = Math.max(1, this.canvas.clientHeight || innerHeight);
101	    this.camera.aspect = w / h;
102	    this.camera.updateProjectionMatrix();
103	    this.viewCamera.aspect = w / h;
104	    this.viewCamera.updateProjectionMatrix();
105	    for (const sys of this.registry.with('resize')) sys.resize(w, h, this.ctx);
106	    this.events.emit('resize', { width: w, height: h });
107	  }
108	
109	  start() {
110	    if (this._running) return;
111	    this._running = true;
112	    this._last = performance.now();
113	    this._loop = this._loop.bind(this);
114	    requestAnimationFrame(this._loop);
115	  }
116	
117	  stop() {
118	    this._running = false;
119	  }
120	
121	  _loop(now) {
122	    if (!this._running) return;
123	    requestAnimationFrame(this._loop);
124	    this.step(now);
125	  }
126	
127	  /** Advance one frame. Exposed so the capture harness can pump frames by hand. */
128	  step(now = performance.now()) {
129	    const t = this.time;
130	    // Clamp so a tab-switch or a breakpoint doesn't teleport the simulation.
131	    const rawDt = Math.min(0.1, Math.max(0, (now - this._last) / 1000));
132	    this._last = now;
133	    t.raw += rawDt;
134	    t.dt = rawDt * t.scale;
135	    t.elapsed += t.dt;
136	    t.frame++;
137	
138	    this.input.beginFrame();
139	
140	    this._accum += t.dt;
141	    let steps = 0;
142	    const fixedSystems = this.registry.with('fixedUpdate');
143	    while (this._accum >= FIXED_DT && steps < MAX_SUBSTEPS) {
144	      for (const sys of fixedSystems) sys.fixedUpdate(FIXED_DT, this.ctx);
145	      this._accum -= FIXED_DT;
146	      steps++;
147	    }
148	    if (steps === MAX_SUBSTEPS) this._accum = 0; // shed backlog rather than spiral
149	    t.alpha = this._accum / FIXED_DT;
150	
151	    for (const sys of this.registry.with('update')) sys.update(t.dt, this.ctx);
152	    for (const sys of this.registry.with('lateUpdate')) sys.lateUpdate(t.dt, this.ctx);
153	
154	    const renderSystem = this.registry.peek('render');
155	    if (typeof renderSystem?.render === 'function') renderSystem.render(this.ctx);
156	
157	    this.input.endFrame();
158	  }
159	
160	  dispose() {
161	    this.stop();
162	    removeEventListener('resize', this._onResize);
163	    this.input.detach();
164	    for (const sys of [...this.registry.ordered].reverse()) sys.dispose?.();
165	    this.events.clear();
166	  }
167	}
