356	  _setState(s) {
357	    if (this.state === s) return;
358	    this.state = s;
359	    this.stateTime = 0;
360	    if (s !== STATE.COMBAT && s !== STATE.SUPPRESSED) this.peeking = false;
361	  }
362	
363	  _think(dt) {
364	    const sq = this.squad;
365	    switch (this.state) {
366	      case STATE.IDLE:
367	        this.desiredSpeed = 0;
368	        this.crouch = false;
369	        if (this.hasTarget) this._enterCombat();
370	        else if (this.patrolPoints && this.stateTime > 2.5) this._setState(STATE.PATROL);
371	        break;
372	
373	      case STATE.PATROL: {
374	        this.crouch = false;
375	        this.desiredSpeed = 1.35;
376	        if (this.hasTarget) {
377	          this._enterCombat();
378	          break;
379	        }
380	        // a route point whose path is still queued is not a route point reached:
381	        // taking the next one here would walk the patrol index forward for free
382	        if (this.pathPending) break;
383	        if (!this.hasMoveTarget || this.position.distanceTo(this.moveTarget) < 1.1) {
384	          const p = this.patrolPoints?.[this.patrolIndex % this.patrolPoints.length];
385	          if (p) {
386	            this.patrolIndex++;
387	            this._goTo(p);
388	          } else this._setState(STATE.IDLE);
389	        }
390	        break;
391	      }
392	
393	      case STATE.ALERT: {
394	        this.crouch = false;
395	        this.desiredSpeed = 1.5;
396	        if (this.hasTarget) {
397	          this._enterCombat();
398	          break;
399	        }
400	        // move to the last known position, then look around
401	        if (this.lastKnownAge < 8 && !this.hasMoveTarget) this._goTo(this.lastKnown);
402	        if (this.stateTime > 12) this._setState(this.patrolPoints ? STATE.PATROL : STATE.IDLE);
403	        break;
404	      }
405	
406	      case STATE.COMBAT:
407	        this._combat(dt);
408	        break;
409	
410	      case STATE.SUPPRESSED:
411	        this.crouch = true;
412	        this.desiredSpeed = 0;
413	        this.wantFire = false;
414	        this.peeking = false;
415	        if (this.suppression < 0.45) this._setState(STATE.COMBAT);
416	        break;
417	
418	      case STATE.FLANK: {
419	        this.crouch = false;
420	        this.desiredSpeed = 4.4;
421	        this.wantFire = false;
422	        if (!this.hasMoveTarget || this.position.distanceTo(this.moveTarget) < 1.2 || this.stateTime > 7) {
423	          this._setState(STATE.COMBAT);
424	          this.cover = null;
425	        }
426	        if (this.suppression > 1.0) this._setState(STATE.COMBAT);
427	        break;
428	      }
429	
430	      case STATE.RETREAT: {
431	        this.crouch = false;
432	        this.desiredSpeed = 4.6;
433	        this.wantFire = false;
434	        if (!this.hasMoveTarget || this.position.distanceTo(this.moveTarget) < 1.2) {
435	          this._setState(STATE.COMBAT);
436	        }
437	        if (this.health > 45 && this.stateTime > 4) this._setState(STATE.COMBAT);
438	        break;
439	      }
