445	  }
446	
447	  _enterCombat() {
448	    this._setState(STATE.COMBAT);
449	    this.cover = null;
450	    this.repathTimer = 0;
451	  }
452	
453	  _combat(dt) {
454	    const target = this.hasTarget ? this.lastKnown : this.lastKnownAge < 5 ? this.lastKnown : null;
455	    if (!target) {
456	      this._setState(STATE.ALERT);
457	      return;
458	    }
459	    const sq = this.squad;
460	    const dist = this.position.distanceTo(target);
461	
462	    // wounded and outgunned: fall back
463	    if (this.health < 34 && this.stateTime > 1.5 && this.rng.float() < dt * 0.5) {
464	      const away = this._v
465	        .copy(this.position)
466	        .sub(target)
467	        .setY(0)
468	        .normalize()
469	        .multiplyScalar(9)
470	        .add(this.position);
471	      if (this._goTo(away)) {
472	        this._setState(STATE.RETREAT);
473	        return;
474	      }
475	    }
476	
477	    // no cover yet, or the current one no longer protects: find one
478	    if (!this.cover || this.repathTimer <= 0) {
479	      const pick = this.ai.cover?.pick(this.position, target, {
480	        id: this.id,
481	        squad: sq?.members,
482	        minRange: 7,
483	        maxRange: 30,
484	        maxTravel: this.cover ? 12 : 26,
485	      });
