487	      if (pick && pick !== this.cover) {
488	        this.cover = pick;
489	        this.coverPos.set(pick.x, pick.y, pick.z);
490	        this._goTo(this.coverPos);
491	      }
492	    }
493	
494	    // A cover point we cannot actually reach must not mute the agent for ever.
495	    // `_goTo` fails outright when A* finds no route (which happens for a cover
496	    // point across an unwalkable seam), and a path can also run out short of the
497	    // point. The branch below reads "has cover, not standing in it" as "walk,
498	    // weapon down, hold fire", so without this the agent stands in the open with
499	    // the player in plain sight and never pulls the trigger.
500	    if (
501	      this.cover &&
502	      !this.hasMoveTarget &&
503	      !this.pathPending && // still queued behind the frame's A* budget
504	      this.position.distanceTo(this.coverPos) > 0.85
505	    ) {
506	      this.cover = null;
507	      this.ai.cover?.release(this.id);
508	      this.repathTimer = Math.min(this.repathTimer, 0.6);
509	    }
510	
511	    const atCover = this.cover
512	      ? this.position.distanceTo(this.coverPos) < 0.85
513	      : false;
514	
515	    if (this.cover && !atCover) {
516	      // moving into position: run, weapon down, no shooting
517	      this.desiredSpeed = 4.3;
518	      this.crouch = false;
519	      this.wantFire = false;
520	      this.aimWeight = 0.35;
521	    } else {
522	      this.desiredSpeed = 0;
523	      this.hasMoveTarget = false;
524	      // peek-and-shoot, gated by the squad so they alternate
525	      const allowed = !sq || sq.requestPeek(this, dt);
526	      if (this.peekTimer <= 0) {
527	        this.peeking = allowed && this.targetVisible !== false;
528	        this.peekTimer = this.peeking ? this.rng.range(1.1, 2.4) : this.rng.range(0.7, 1.8);
529	        if (this.peeking && this.cover) {
530	          this.peekSide = this.ai.cover.peekOffset(this.cover, target, this.eyeHeight, this._v2);
531	          this.coverPos.copy(this._v2);
532	        }
533	      }
534	      this.crouch = this.cover ? !this.cover.high || !this.peeking : false;
535	      this.aimWeight = this.peeking ? 1 : 0.55;
536	      this.wantFire = this.peeking && this.targetVisible && this.hasTarget && dist < this.weaponRange;
537	      // suppressing fire at the last known spot even without a clean shot
538	      if (!this.wantFire && this.hasTarget && this.lastKnownAge < 2.2 && this.peeking) {
539	        this.wantFire = this.rng.float() < 0.35;
540	      }
541	    }
542	
543	    // flank when the player has been static and we have friends shooting
544	    if (
545	      sq &&
546	      this.stateTime > 4 &&
547	      this.grenadeCooldown < 0 === false &&
548	      sq.canFlank(this) &&
549	      this.rng.float() < dt * 0.25
550	    ) {
551	      const side = this.rng.float() < 0.5 ? 1 : -1;
552	      const perp = this._v.copy(target).sub(this.position).setY(0).normalize();
553	      const flank = this._v2
554	        .set(-perp.z * side, 0, perp.x * side)
555	        .multiplyScalar(this.rng.range(8, 15))
556	        .add(this.position)
557	        .addScaledVector(perp, 4);
558	      if (this._goTo(flank)) {
559	        this.cover = null;
560	        this.ai.cover?.release(this.id);
561	        this._setState(STATE.FLANK);
562	        sq.claimFlank(this);
563	        return;
564	      }
565	    }
566	
567	    // grenade when the player is pinned and we have line of fire
568	    if (
569	      this.hasGrenade &&
570	      this.grenadeCooldown <= 0 &&
571	      dist > 8 &&
572	      dist < 26 &&
573	      this.lastKnownAge < 1.5 &&
574	      (!sq || sq.requestGrenade(this))
575	    ) {
576	      this._throwGrenade(target);
577	    }
578	  }
