580	  /* ================================================================== */
581	  /* movement                                                           */
582	  /* ================================================================== */
583	
584	  _goTo(dest) {
585	    const grid = this.ai.grid;
586	    if (!grid) {
587	      this.moveTarget.copy(dest);
588	      this.hasMoveTarget = true;
589	      return true;
590	    }
591	    const n = this.ai.requestPath(this.position, dest, this.path);
592	    if (n < 0) {
593	      // The frame's A* budget is spent. Hold the destination and retry on the
594	      // next frame instead of failing outright: `_combat` reads a failed _goTo as
595	      // "that cover point is unreachable" and drops it.
596	      this._pendingDest.copy(dest);
597	      this.pathPending = true;
598	      return false;
599	    }
600	    this.pathPending = false;
601	    if (n === 0) {
602	      this.hasMoveTarget = false;
603	      return false;
604	    }
605	    this.pathLen = n;
606	    this.pathIndex = 0;
607	    this.moveTarget.copy(this.path[n - 1]);
608	    this.hasMoveTarget = true;
609	    return true;
610	  }
611	
612	  _move(dt) {
613	    const wp = this.hasMoveTarget && this.pathIndex < this.pathLen ? this.path[this.pathIndex] : null;
614	    this._steer.set(0, 0, 0);
615	    let want = 0;
616	
617	    if (wp) {
618	      const to = this._v.copy(wp).sub(this.position);
619	      to.y = 0;
620	      const d = to.length();
621	      if (d < (this.pathIndex === this.pathLen - 1 ? 0.45 : 0.75)) {
622	        this.pathIndex++;
623	        if (this.pathIndex >= this.pathLen) this.hasMoveTarget = false;
624	      } else {
625	        to.multiplyScalar(1 / d);
626	        this._steer.copy(to);
627	        want = this.desiredSpeed;
628	      }
629	    }
630	
631	    // local avoidance: push off squadmates and steer around them
632	    const others = this.ai.agents;
633	    for (let i = 0; i < others.length; i++) {
634	      const o = others[i];
635	      if (o === this || !o.alive) continue;
636	      const dx = this.position.x - o.position.x;
637	      const dz = this.position.z - o.position.z;
638	      const d2 = dx * dx + dz * dz;
639	      const rr = (this.radius + o.radius + 0.42) ** 2;
640	      if (d2 > rr || d2 < 1e-6) continue;
641	      const d = Math.sqrt(d2);
642	      const push = (1 - d / Math.sqrt(rr)) * 1.5;
643	      this._steer.x += (dx / d) * push;
644	      this._steer.z += (dz / d) * push;
645	      // tangential bias breaks head-on deadlocks deterministically
646	      this._steer.x += (-dz / d) * push * 0.35 * (this.id % 2 ? 1 : -1);
647	      this._steer.z += (dx / d) * push * 0.35 * (this.id % 2 ? 1 : -1);
648	      if (want === 0) want = this.desiredSpeed * 0.35;
649	    }
650	
651	    if (this._steer.lengthSq() > 1e-6) this._steer.normalize();
652	
653	    // speed: ease toward the request so starts and stops have weight
654	    const targetSpeed = want * (this.crouch ? 0.42 : 1) * (1 - this.suppression * 0.25);
655	    this.speed += (targetSpeed - this.speed) * Math.min(1, dt * 7);
656	    if (this.speed < 0.05) this.speed = 0;
657	
658	    // facing: look where we are going, or at the threat when engaged
659	    const engaged =
660	      this.state === STATE.COMBAT || this.state === STATE.SUPPRESSED || this.hasTarget;
661	    if (engaged && this.lastKnownAge < 8) {
662	      this.targetYaw = Math.atan2(this.lastKnown.x - this.position.x, this.lastKnown.z - this.position.z);
663	    } else if (this.speed > 0.2) {
664	      this.targetYaw = Math.atan2(this._steer.x, this._steer.z);
665	    }
666	    let dy = this.targetYaw - this.yaw;
667	    while (dy > Math.PI) dy -= Math.PI * 2;
668	    while (dy < -Math.PI) dy += Math.PI * 2;
669	    // a big turn while standing still becomes a real turn-in-place step
670	    if (Math.abs(dy) > 0.9 && this.speed < 0.3) this.animator.turn(dy > 0 ? 1 : -1);
