672	    this.yaw += Math.max(-turnRate * dt, Math.min(turnRate * dt, dy));
673	
674	    /* integrate through the character controller */
675	    const c = this.controller;
676	    if (c) {
677	      const g = this.phys.gravity;
678	      this.velocity.y += g * dt;
679	      const vx = this._steer.x * this.speed;
680	      const vz = this._steer.z * this.speed;
681	      c.setHeight?.(this.crouch ? 1.16 * this.scale : this.height);
682	      c.move(vx * dt, this.velocity.y * dt, vz * dt);
683	      this.position.copy(c.position);
684	      this.grounded = c.grounded;
685	      if (c.grounded && this.velocity.y < 0) this.velocity.y = 0;
686	
687	      // blocked by something low: vault it
688	      if (c.lastMoveBlocked && this.speed > 1.5 && this.vaultCooldown <= 0 && this.grounded) {
689	        this._tryVault();
690	      }
691	      if (c.lastMoveBlocked && this.speed > 0.5) {
692	        this.stuckTimer += dt;
693	        if (this.stuckTimer > 1.1) {
694	          this.stuckTimer = 0;
695	          this.repathTimer = 0;
696	          if (this.hasMoveTarget) this._goTo(this.moveTarget);
697	        }
698	      } else this.stuckTimer = 0;
699	    } else {
700	      this.position.x += this._steer.x * this.speed * dt;
701	      this.position.z += this._steer.z * this.speed * dt;
702	    }
703	  }
704	
705	  _tryVault() {
706	    const phys = this.phys;
707	    const fwd = this._v.set(Math.sin(this.yaw), 0, Math.cos(this.yaw));
708	    const low = phys.raycast(
709	      this.position.x, this.position.y + 0.35, this.position.z,
710	      fwd.x, 0, fwd.z, 0.85, phys.MASK.WORLD
711	    );
712	    if (!low.hit) return;
713	    const high = phys.raycastAny(
714	      this.position.x, this.position.y + 1.25, this.position.z,
715	      fwd.x, 0, fwd.z, 1.1, phys.MASK.WORLD
716	    );
717	    if (high) return; // a wall, not a ledge
718	    // landing spot on the other side
719	    const lx = this.position.x + fwd.x * 1.5;
720	    const lz = this.position.z + fwd.z * 1.5;
721	    const y = this.ai.groundAt(lx, lz, this.position.y + 2.2);
722	    if (!Number.isFinite(y) || Math.abs(y - this.position.y) > 1.3) return;
