724	    this.animator.vault(0.8);
725	    this.vaultFrom = (this.vaultFrom ?? new THREE.Vector3()).copy(this.position);
726	    this.vaultTo = (this.vaultTo ?? new THREE.Vector3()).set(lx, y, lz);
727	    this.vaultT = 0;
728	  }
