731	  /* shooting                                                           */
732	  /* ================================================================== */
733	
734	  _shoot(dt) {
735	    // where the gun is pointing: lead toward the target with human error
736	    const t = this.hasTarget || this.lastKnownAge < 3 ? this.lastKnown : null;
737	    if (t) {
738	      // aim at the chest, not the feet
739	      this._v.set(t.x, t.y + 0.05, t.z);
740	      const dist = this.position.distanceTo(this._v);
741	      const wobbleT = this.ctx.time.elapsed * 1.7 + this.id;
742	      const wob = 0.012 + this.suppression * 0.05;
