831	      part === 'head' ? 'head'
832	        : part === 'arm' ? (this._sideOf(point) < 0 ? 'armR' : 'armL')
833	          : part === 'leg' ? (this._sideOf(point) < 0 ? 'legR' : 'legL')
834	            : 'torso';
835	    this.animator.hit(region, side, Math.min(1.4, 0.5 + amount / 45));
