839	  /** Which side of the body a world point is on: <0 right, >0 left. */
840	  _sideOf(p) {
841	    const dx = p.x - this.position.x;
842	    const dz = p.z - this.position.z;
843	    return dx * Math.cos(this.yaw) - dz * Math.sin(this.yaw);
844	  }
