885	  /**
886	   * Hand the live pose to the ragdoll solver. `physics` derives the capsule
887	   * chain from the skeleton itself, so the doll starts exactly in the pose the
888	   * animator left — the death has no pop. `radiusRatio` fattens the capsules
889	   * (its default is thin enough that a settled body reads as a pancake).
890	   */
891	  _makeRagdoll(impulse, point) {
892	    const phys = this.phys;
893	    if (!phys) return null;
894	    // Fat capsules that start half-buried in the floor tunnel straight through
895	    // it: the contact normal flips once a bone's axis is on the far side. Lift
896	    // the pose clear of the ground for the one frame it takes to build the doll,
897	    // then put the group back — the body drops the 15 cm invisibly.
898	    const lift = 0.15 * this.scale;
899	    this.group.position.y += lift;
900	    this.group.updateMatrixWorld(true);
901	    const rd = phys.createRagdollFromSkeleton(this.mesh, {
902	      actor: this,
903	      mass: this.mass,
904	      radiusRatio: 0.42,
905	      cone: 74,
906	      twist: 38,
907	      iterations: 8,
908	      velocity: { x: this.velocity.x * 0.6, y: 0, z: this.velocity.z * 0.6 },
909	    });
910	    this.group.position.y -= lift;
911	    this.group.updateMatrixWorld(true);
912	    if (!rd) return null;
913	    if (impulse && point) {
914	      // wide radius: a tight one dumps all of it into whichever light bone is
915	      // nearest and whips the limb across the street
916	      rd.applyImpulse(point.x, point.y, point.z, impulse.x, impulse.y, impulse.z, 0.85);
917	    }
918	    if (this.ai.debugLog) {
919	      console.info(
920	        `[ai] ragdoll ${rd.boneCount} bones / ${rd.particleCount} particles, ` +
921	          `mask=${rd.mask} tris=${rd.world?.triCount}`
922	      );
923	    }
924	    return rd;
925	  }
