931	  _drive(dt) {
932	    // root motion for a vault
933	    if (this.vaultT !== undefined && this.animator.vaulting && this.vaultFrom) {
934	      this.vaultT += dt / 0.8;
935	      const t = Math.min(1, this.vaultT);
936	      this.position.lerpVectors(this.vaultFrom, this.vaultTo, t);
937	      this.position.y += Math.sin(t * Math.PI) * 0.42;
938	      this.controller?.teleport(this.position.x, this.position.y, this.position.z);
939	    }
940	
941	    this.group.position.copy(this.position);
942	    this.group.rotation.y = this.yaw;
943	    this.group.updateMatrixWorld(true);
944	
945	    const moving = this.speed > 0.25;
946	    let clip;
947	    if (this.crouch) clip = moving ? 'crouchWalk' : 'crouchIdle';
948	    else if (this.speed > 2.6) clip = 'run';
949	    else if (moving) clip = 'walk';
950	    else clip = this.health < 35 ? 'hurtIdle' : 'idle';
951	    this.clip = clip;
952	
953	    const an = this.animator;
954	    an.setState({
955	      clip,
956	      speed: this.speed,
957	      crouch: this.crouch,
958	      aimTarget: this.aimTarget,
959	      lookTarget: this.hasTarget || this.lastKnownAge < 4 ? this.lastKnown : this.aimTarget,
960	      aimWeight: this.aimWeight,
961	      suppress: Math.min(1, this.suppression * 0.8),
962	    });
