975	        this._animSkip--;
976	        return;
977	      }
978	      this._animSkip = 2; // one evaluation in three while nothing can see it
979	    } else {
980	      this._animSkip = 0;
981	    }
982	    an.update(this._animAccum, this.ctx.time.elapsed);
983	    this._animAccum = 0;
984	  }
