986	  /** Push the hit capsules onto the animated skeleton. */
987	  syncHitboxes() {
988	    if (!this.alive) return;
989	    const an = this.animator;
990	    for (let i = 0; i < this.colliders.length; i++) {
991	      const c = this.colliders[i];
992	      const { a, b } = c.userData;
993	      an.bonePos(a, this._boneA);
994	      an.bonePos(b, this._boneB);
995	      c.setSegment(
996	        this._boneA.x, this._boneA.y, this._boneA.z,
997	        this._boneB.x, this._boneB.y, this._boneB.z
998	      );
999	    }
1000	  }
