1004	    for (const c of this.colliders) this.phys?.removeCollider(c);
1005	    this.colliders.length = 0;
1006	    if (this.ragdoll) this.phys?.removeRagdoll(this.ragdoll);
1007	    this.group.parent?.remove(this.group);
