358	    const p = this.playerPosition(this._v2);
359	    if (!p) return 1;
360	    const d = p.distanceTo(point);
361	    // full damage inside 22 m, tapering to 45 % by 70 m
362	    return d < 22 ? 1 : Math.max(0.45, 1 - (d - 22) * 0.0125);
