367	    const py = point.y + eyeH * 0.7 - origin.y;
368	    const pz = point.z - origin.z;
369	    const t = Math.max(0, px * dir.x + py * dir.y + pz * dir.z);
370	    return Math.hypot(px - dir.x * t, py - dir.y * t, pz - dir.z * t);
371	  }
