411	  _buildNav() {
412	    const phys = this.phys;
413	    const world = this.ctx.peek('world');
414	    if (!phys) return;
415	    if (phys.staticWorld.dirty) phys.rebuildStatic();
416	    if (phys.triangleCount <= 0) return; // level not registered yet — retry next frame
417	    const bounds =
418	      world?.bounds?.clone?.() ??
419	      new THREE.Box3(new THREE.Vector3(-70, -4, -70), new THREE.Vector3(70, 24, 70));
420	    bounds.expandByScalar(2);
421	    const t0 = performance.now();
422	    this.grid = new NavGrid(phys, { bounds, cell: 0.8, radius: 0.36, height: 1.78 });
423	    this.grid.build();
