427	    this.stats.coverPts = this.cover.points.length;
428	    this.stats.walkable = this.grid.walkableCount;
429	    this._navPending = false;
430	    console.info(
431	      `[ai] nav ${this.grid.nx}x${this.grid.nz} cells · ${this.grid.walkableCount} walkable · ` +
432	        `${this.cover.points.length} cover points · ${this.stats.navMs.toFixed(0)}ms`
433	    );
434	  }
