481	  /**
482	   * Garrison the level: two squads on patrol routes drawn from the world's own
483	   * spawn points, far enough from the player to be found rather than spawned on
484	   * top of. This is what the behaviour tree, navigation and perception actually
485	   * run against in play.
486	   */
487	  populate(opts = {}) {
488	    const world = this.ctx.peek('world');
489	    const spawns = world?.spawnPoints ?? [];
490	    if (!spawns.length || !this.grid) return 0;
491	    const player = this.playerPosition(this._v3).clone();
492	    // rank the spawn points by distance from the player, take the far half
493	    const ranked = spawns
494	      .map((s, i) => ({ s, i, d: s.position.distanceTo(player) }))
495	      .sort((a, b) => b.d - a.d)
496	      .filter((e) => e.d > 18);
497	    if (!ranked.length) return 0;
498	
499	    const variants = ['vanguard', 'irregular', 'breacher'];
500	    const squads = opts.squads ?? 2;
501	    const per = opts.perSquad ?? 3;
502	    let made = 0;
503	    for (let q = 0; q < squads && q < ranked.length; q++) {
504	      const squad = this.createSquad();
505	      const anchor = ranked[q % ranked.length].s;
506	      // patrol route: this spawn point and the two next-nearest ones
507	      const route = [anchor.position.clone()];
508	      const others = ranked
509	        .filter((e) => e.s !== anchor)
510	        .sort(
511	          (a, b) =>
512	            a.s.position.distanceTo(anchor.position) - b.s.position.distanceTo(anchor.position)
513	        )
514	        .slice(0, 2);
515	      for (const o of others) route.push(o.s.position.clone());
516	
517	      for (let m = 0; m < per; m++) {
518	        const jitterA = this.rng.range(0, Math.PI * 2);
519	        const jitterR = this.rng.range(0.8, 3.2);
520	        const p = anchor.position
521	          .clone()
522	          .add(new THREE.Vector3(Math.cos(jitterA) * jitterR, 0, Math.sin(jitterA) * jitterR));
523	        const ci = this.grid.nearest(p.x, p.z, anchor.position.y, 6, 1.4);
524	        if (ci >= 0) {
525	          p.set(
526	            this.grid.worldX(ci % this.grid.nx),
527	            this.grid.floor[ci],
528	            this.grid.worldZ((ci / this.grid.nx) | 0)
529	          );
530	        } else {
531	          p.y = this.groundAt(p.x, p.z, anchor.position.y + 4);
532	        }
533	        const a = this.spawn(variants[(q * per + m) % variants.length], p, anchor.yaw + this.rng.signed() * 0.7, {
534	          patrol: route,
535	        });
536	        squad.add(a);
537	        made++;
538	      }
539	    }
540	    console.info(`[ai] garrison: ${made} enemies in ${squads} squads`);
541	    return made;
542	  }
