554	  /** 0 at night, 1 in full daylight. Drives both flash gains below. */
555	  _daylight() {
556	    const sky = this._sky ?? (this._sky = this.ctx.peek('sky'));
557	    const alt = sky?.sunAltitude ?? 0.6; // radians above the horizon
558	    return Math.min(1, Math.max(0, Math.sin(Math.max(0, alt)) * 4));
559	  }
560	
561	  /**
562	   * SPRITE gain. The flash itself has to be *visible* — a firefight with no fire
563	   * in it is not a firefight — so this stays high enough to read as burning gas
564	   * at 10-25 m and is only trimmed in daylight, where the sun is competing.
565	   */
566	  _flashGain() {
567	    return 0.12 + 0.5 * (1 - this._daylight());
568	  }
569	
570	  /**
571	   * LIGHT gain, deliberately separate and two orders of magnitude smaller.
572	   *
573	   * The crown sits 0.6 m from the shooter's own chest, so a player-strength
574	   * 90 cd flash puts 90/0.36 = 250 W/m^2 on him against 4 W/m^2 of sun. That is
575	   * the whole reason the soldiers used to render BRIGHTER than the sunlit stucco
576	   * behind them: they were being lit, on the frame the shutter fell, by their own
577	   * muzzle flash. A real flash is ~1 ms inside a 16 ms frame, so the honest
578	   * time-averaged contribution in daylight is a highlight on the receiver and
579	   * nothing more; after dark it is the only light there is and gets to earn its
580	   * keep. Measured: torso 0.44 -> 0.13 linear, i.e. from 1.9x the sunlit wall to
581	   * 0.55x, which is what an 0.19-albedo uniform in shade should be.
582	   */
583	  _flashLight() {
584	    const day = this._daylight();
585	    return 0.006 + 0.05 * (1 - day);
586	  }
587	
588	  onAgentFire(agent, origin, dir) {
589	    const ctx = this.ctx;
590	    const phys = this.phys;
591	
592	    // muzzle flash, light and smoke come from fx via the canonical event
593	    const fe = this._fireEvent;
594	    fe.origin.copy(origin);
595	    fe.dir.copy(dir);
596	    fe.intensity = this._flashGain();
597	    fe.light = this._flashLight();
598	    fe.flashScale = 0.8;
599	    fe.seed = (agent.id * 2654435761 + ctx.time.frame) >>> 0;
600	    ctx.events.emit('weapon:fire', fe);
601	
602	    // ejected case
603	    const se = this._shellEvent;
604	    se.position.copy(agent.animator.ejectWorld);
605	    se.velocity.set(dir.z, 0.55, -dir.x).multiplyScalar(2.1).addScaledVector(dir, -0.6);
606	    ctx.events.emit('weapon:shell', se);
607	
608	    // the round itself
609	    let end = null;
610	    if (phys) {
611	      const impacts = phys.fireBullet({
612	        origin,
613	        dir,
614	        damage: agent.weaponDamage,
615	        penetration: 0.9,
616	        maxDist: 200,
617	        mask: phys.MASK.BULLET,
618	      });
619	      if (impacts.length) end = impacts[0].point;
620	    }
621	    // physics has no player collider, so test the player capsule ourselves.
622	    // Staged agents shoot for the camera, not for blood: a capture must not be
623	    // graded through the player's low-health filter.
624	    if (!agent.staged?.noDamage) this._testPlayerHit(agent, origin, dir, end);
625	
626	    this._tracerFrom.copy(origin);
627	    if (end) this._tracerTo.copy(end);
628	    else this._tracerTo.copy(origin).addScaledVector(dir, 120);
629	    if ((agent.id + agent.ammo) % 3 === 0) ctx.events.emit('bullet:tracer', this._tracerEvent);
630	  }
631	
632	  _testPlayerHit(agent, origin, dir, end) {
633	    const p = this.playerPosition(this._v);
634	    if (!p) return;
635	    const maxT = end ? origin.distanceTo(end) : 200;
636	    const px = p.x - origin.x, py = p.y - origin.y, pz = p.z - origin.z;
637	    const t = px * dir.x + py * dir.y + pz * dir.z;
638	    if (t < 0.5 || t > maxT) return;
639	    const miss = Math.hypot(px - dir.x * t, py - dir.y * t, pz - dir.z * t);
640	    const player = this.ctx.peek('player');
641	    if (miss > 0.42) {
642	      if (miss < 1.6) player?.onNearMiss?.(miss); // whip-crack past the ear
643	      return;
644	    }
645	    const amount = agent.weaponDamage * (miss < 0.16 ? 1.25 : 1);
646	    this._v2.copy(origin);
647	    // Damage is applied *only* through the event below. `player` listens for
648	    // `damage:dealt` with itself as the target, so calling applyDamage() here as
649	    // well wounded the player twice for every round that connected.
650	    this.ctx.events.emit('damage:dealt', {
651	      target: player ?? 'player',
652	      amount,
653	      headshot: false,
654	      killed: false,
655	      point: p,
656	      from: this._v2,
657	      source: agent,
658	    });
659	  }
