665	  /** Grenade geometry + material. Built at prewarm, not on the first throw. */
666	  _ensureGrenade() {
667	    if (this._grenadeGeo) return;
668	    this._grenadeGeo = new THREE.IcosahedronGeometry(0.045, 1);
669	    this._grenadeMat = new THREE.MeshStandardMaterial({
670	      color: 0x2c3226,
671	      roughness: 0.62,
672	      metalness: 0.85,
673	    });
674	  }
675	
676	  throwGrenade(agent, from, target) {
677	    const phys = this.phys;
678	    if (!phys) return;
679	    this._ensureGrenade();
680	    const mesh = new THREE.Mesh(this._grenadeGeo, this._grenadeMat);
681	    this.root.add(mesh);
682	    // lobbed ballistic solve
683	    const dx = target.x - from.x, dz = target.z - from.z;
684	    const dist = Math.max(0.5, Math.hypot(dx, dz));
685	    const g = Math.abs(phys.gravity);
686	    const speed = Math.min(18, Math.sqrt(Math.max(4, (dist * g) / 0.95)));
687	    const vy = speed * 0.62;
688	    const vh = Math.min(speed, dist / Math.max(0.35, (2 * vy) / g));
689	    const body = phys.addRigidBody({
690	      shape: 'sphere',
691	      radius: 0.05,
692	      mass: 0.42,
693	      position: from,
694	      velocity: { x: (dx / dist) * vh, y: vy, z: (dz / dist) * vh },
695	      restitution: 0.28,
696	      friction: 0.7,
697	      lifetime: 9,
698	      object3D: mesh,
699	      surfaceType: 'metal',
700	    });
701	    this._grenades.push({ body, mesh, fuse: 2.35, agent });
702	    agent.animator.fire(0.35);
703	  }
704	
705	  _updateGrenades(dt) {
706	    for (let i = this._grenades.length - 1; i >= 0; i--) {
707	      const g = this._grenades[i];
708	      g.fuse -= dt;
709	      if (g.fuse > 0) continue;
710	      const p = g.body?.position ?? g.mesh.position;
711	      this.ctx.events.emit('explosion', {
712	        position: new THREE.Vector3(p.x, p.y, p.z),
713	        radius: 6.5,
714	        damage: 120,
715	        source: g.agent,
716	      });
717	      this.phys?.removeRigidBody(g.body);
718	      this.root.remove(g.mesh);
719	      this._grenades.splice(i, 1);
720	    }
721	  }
