727	  update(dt, ctx) {
728	    if (this._navPending) {
729	      this._buildNav();
730	      // Populate the level for normal play. Capture runs stay empty unless a
731	      // shot asks for a tableau, so nobody's screenshot gets a stray patrol
732	      // wandering through it.
733	      if (!this._navPending && (!ctx.config.deterministic || this.forcePopulate)) this.populate();
734	    }
