756	              `${(b.maxy - b.miny).toFixed(2)} x ${(b.maxz - b.minz).toFixed(2)} m ` +
757	              `at y=${b.miny.toFixed(2)} sleeping=${a.ragdoll.sleeping}`
758	          );
