783	  /**
784	   * A* on the shared grid, rationed. Returns the waypoint count, or -1 when this
785	   * frame's budget is spent — the caller keeps its old path and asks again next
786	   * frame, which is invisible at 60 Hz and turns a squad-wide repath (six solves,
787	   * ~5 ms, on the frame the player opens fire) into two solves per frame.
788	   */
789	  requestPath(from, dest, out) {
790	    if (!this.grid) return 0;
791	    if (this._pathBudget <= 0) {
792	      this.stats.pathsDeferred++;
793	      return -1;
794	    }
795	    this._pathBudget--;
796	    return this.grid.findPath(from, dest, out);
797	  }
798	
799	  /** Unit vector pointing AT the sun, however the sky exposes itself. */
800	  _sunDirection() {
801	    const sky = this._sky ?? (this._sky = this.ctx.peek('sky'));
802	    const d = sky?.sunDirection;
803	    if (d && Number.isFinite(d.x)) this._sun.copy(d);
804	    else this._sun.set(0.3, 0.8, 0.4);
805	    if (this._sun.lengthSq() < 1e-8) this._sun.set(0, 1, 0);
806	    return this._sun.normalize();
807	  }
808	
809	  /**
810	   * Decide, per actor, whether anything it does this frame can reach a pixel.
811	   *
812	   * An actor is IRRELEVANT only when both of these hold:
813	   *   1. its (already 1.45x inflated) bounding sphere, grown by a further 4 m,
814	   *      misses the camera frustum — so it is not drawn, and no screen-space
815	   *      effect can sample it either, because it is not in the depth buffer;
816	   *   2. the volume its sun shadow could possibly darken misses the frustum too.
817	   *      For a directional light that volume is exactly the actor's sphere swept
818	   *      along -sunDir: a visible surface can only be shadowed by this actor if
819	   *      the ray from that surface toward the sun passes through it. Sweeping to
820	   *      where the ray leaves the level below the floor covers every receiver,
821	   *      ground or wall, and the 4 m of slack absorbs both the soft-shadow filter
822	   *      radius (up to ~1 m of cascade texels) and a frame of camera motion.
823	   *
824	   * Irrelevant actors animate at a third of the rate and are dropped from the
825	   * shadow cascades (`userData.owNoShadow`, which render honours per frame). They
826	   * are still simulated, still shootable, still make noise — only the parts that
827	   * can exclusively affect pixels are skipped.
828	   */
829	  _updateRelevance(ctx) {
830	    const cam = ctx.camera;
831	    this._mvp.multiplyMatrices(cam.projectionMatrix, cam.matrixWorldInverse);
832	    this._frustum.setFromProjectionMatrix(this._mvp);
833	    const sun = this._sunDirection();
834	    // how far a shadow ray can travel before it is under the level
835	    const floorY = (this.grid ? -6 : -20);
836	    const sunY = Math.max(0.06, sun.y);
837	    let irrelevant = 0;
838	
839	    for (let i = 0; i < this.agents.length; i++) {
840	      const a = this.agents[i];
841	      const geo = a.mesh.geometry;
842	      const bs = geo.boundingSphere;
843	      if (!bs) { a.lodIrrelevant = false; continue; }
844	      const s = this._sphere.copy(bs).applyMatrix4(a.mesh.matrixWorld);
845	      s.radius += 4;
846	      let visible = this._frustum.intersectsSphere(s);
847	      if (!visible) {
848	        const sweep = this._sweep;
849	        const tMax = Math.min(320, (s.center.y - floorY) / sunY);
850	        const step = Math.max(2, s.radius * 0.9);
851	        sweep.radius = s.radius;
852	        for (let t = step; t <= tMax; t += step) {
853	          sweep.center.copy(s.center).addScaledVector(sun, -t);
854	          if (this._frustum.intersectsSphere(sweep)) { visible = true; break; }
855	        }
856	      }
857	      a.lodIrrelevant = !visible;
858	      if (!visible) irrelevant++;
859	      a.mesh.userData.owNoShadow = !visible;
860	    }
861	    this._lodStats.irrelevant = irrelevant;
862	    this.stats.lodIrrelevant = irrelevant;
863	  }
