865	  /* ================================================================== */
866	  /* staged tableau for the capture harness                             */
867	  /* ================================================================== */
868	
869	  /**
870	   * Pin an agent into a photogenic combat beat: it still animates, aims and
871	   * fires for real, it just does not get to decide where to stand.
872	   */
873	  _updateStaged(a, dt) {
874	    const s = a.staged;
875	    const p = this.playerPosition(this._v3);
876	    a.stateTime += dt;
877	    a.fireCooldown -= dt;
878	    a.burstCooldown -= dt;
879	    a.state = STATE.COMBAT;
880	    a.hasTarget = true;
881	    a.targetVisible = true;
882	    a.alertness = 1;
883	    a.lastKnown.copy(p);
884	    a.lastKnownAge = 0;
885	    a.crouch = !!s.crouch;
886	    a.aimWeight = s.aimWeight ?? 1;
887	    a.suppression = s.suppression ?? 0;
888	    a.desiredSpeed = s.speed ?? 0;
889	    a.wantFire = s.fire !== false;
890	    if (s.speed) {
891	      a.hasMoveTarget = true;
892	      if (!a.path[0]) a.path[0] = new THREE.Vector3();
893	      a.path[0].copy(a.position).addScaledVector(s.heading, 6);
894	      a.pathLen = 1;
895	      a.pathIndex = 0;
896	    } else {
897	      a.hasMoveTarget = false;
898	    }
899	    if (s.reloadEvery && a.stateTime > s.reloadEvery && !a.animator.reloading) {
900	      a.stateTime = 0;
901	      a.animator.reload(2.4);
902	    }
903	    a._move(dt);
904	    a._shoot(dt);
905	    a._drive(dt);
906	  }
907	
908	  /**
909	   * Compose a staged enemy into the frame: find the walkable spot whose
910	   * projected screen position and depth best match the requested composition,
911	   * that the camera can actually see, that is not on top of another actor, and
912	   * that has cover nearby. Occlusion is checked at chest and head height, which
913	   * is what stops a soldier being placed behind a market stall.
914	   */
915	  _stageSlot(cam, ndcX, wantDepth, placed) {
916	    const g = this.grid;
917	    const F = this._v.set(0, 0, -1).applyQuaternion(cam.quaternion);
918	    F.y = 0;
919	    F.normalize();
920	    const rx = F.z, rz = -F.x; // camera right, flattened
921	    const tanH = Math.tan((cam.fov * Math.PI) / 360) * cam.aspect;
922	    const ideal = new THREE.Vector3()
923	      .copy(cam.position)
924	      .addScaledVector(F, wantDepth)
925	      .add(this._v2.set(rx, 0, rz).multiplyScalar(ndcX * tanH * wantDepth));
926	    const yRef = cam.position.y - 1.7;
927	    const out = new THREE.Vector3(ideal.x, yRef, ideal.z);
928	    if (!g) {
929	      out.y = this.groundAt(out.x, out.z, cam.position.y + 3);
930	      return out;
931	    }
932	    const chest = this._v3;
933	    const cx = g.cellX(ideal.x), cz = g.cellZ(ideal.z);
934	    const span = Math.ceil(7 / g.cell);
935	    let best = -1, bestScore = Infinity, bestX = 0, bestZ = 0;
936	    for (let dz = -span; dz <= span; dz++) {
937	      for (let dx = -span; dx <= span; dx++) {
938	        const ix = cx + dx, iz = cz + dz;
939	        if (!g.walkable(ix, iz)) continue;
940	        const i = g.index(ix, iz);
941	        const fy = g.floor[i];
942	        if (Math.abs(fy - yRef) > 1.0) continue;
943	        const x = g.worldX(ix), z = g.worldZ(iz);
944	        // spacing from the men already placed
945	        let tooClose = false;
946	        for (const q of placed) {
947	          if (Math.hypot(q.x - x, q.z - z) < 2.4) { tooClose = true; break; }
948	        }
949	        if (tooClose) continue;
950	        // project
951	        const ex = x - cam.position.x, ez = z - cam.position.z;
952	        const depth = ex * F.x + ez * F.z;
953	        if (depth < 3) continue;
954	        const lateral = ex * rx + ez * rz;
955	        const ndc = lateral / (depth * tanH);
956	        // must be visible: chest and head
957	        if (this.phys) {
958	          chest.set(x, fy + 1.25, z);
959	          if (!this.phys.lineOfSight(cam.position, chest, this.phys.MASK.SIGHT)) continue;
960	          chest.set(x, fy + 1.62, z);
961	          if (!this.phys.lineOfSight(cam.position, chest, this.phys.MASK.SIGHT)) continue;
962	        }
963	        let score = Math.abs(ndc - ndcX) * 9 + Math.abs(depth - wantDepth) * 0.5;
964	        // prefer standing next to something solid
965	        score -= g.enclosure[i] * 0.35;
966	        if (score < bestScore) {
967	          bestScore = score;
968	          best = i;
969	          bestX = x;
970	          bestZ = z;
971	        }
972	      }
973	    }
974	    if (best >= 0) out.set(bestX, g.floor[best], bestZ);
975	    else out.y = this.groundAt(out.x, out.z, cam.position.y + 3);
976	    return out;
977	  }
978	
979	  /**
980	   * `debugStage('firefight')` — a staged firefight in front of the shot camera:
981	   * one man up and firing from behind hard cover, one crouched and peeking, one
982	   * moving between positions, one reloading further back.
983	   */
984	  debugStage(name) {
985	    if (name !== 'firefight') return this.stats;
986	    if (this.inspect) return this._stageInspect();
987	    if (this._navPending) this._buildNav();
988	
989	    const cam = this.ctx.camera;
990	    // A firefight the critic can actually see: drop the sun low enough to rake
991	    // down the street so the characters are lit, not silhouetted. This shot is
992	    // ours to compose; every other shot keeps its own time of day.
993	    this.ctx.peek('sky')?.setTimeOfDay?.(17.9);
994	    const F = new THREE.Vector3(0, 0, -1).applyQuaternion(cam.quaternion);
995	    F.y = 0;
996	    F.normalize();
997	    const right = new THREE.Vector3(F.z, 0, -F.x);
998	    const squad = this.createSquad();
999	
1000	    /** [variant, ndcX, depth, crouch, speed, fire, reloadEvery] */
1001	    const LAYOUT = [
1002	      // hero: up and firing, left of frame, close enough to read the kit
1003	      ['vanguard', -0.44, 8.0, false, 0, true, 0],
1004	      // second man crouched in cover, right of frame
1005	      ['breacher', 0.30, 12.0, true, 0, true, 0],
1006	      // one caught mid-stride between positions
1007	      ['irregular', -0.14, 16.0, false, 4.1, false, 0],
1008	      // one reloading behind cover on the far right
1009	      ['vanguard', 0.60, 9.5, true, 0, true, 3.4],
1010	      // depth: a fifth man well down the street
1011	      ['irregular', -0.26, 22.0, false, 0, true, 0],
1012	    ];
1013	
1014	    const placedPositions = [];
1015	    for (const [variant, ndcX, d, crouch, speed, fire, reload] of LAYOUT) {
1016	      const pos = this._stageSlot(cam, ndcX, d, placedPositions);
1017	      const yaw = Math.atan2(cam.position.x - pos.x, cam.position.z - pos.z);
1018	      const a = this.spawn(variant, pos, yaw);
1019	      squad.add(a);
1020	      a.staged = {
1021	        crouch,
1022	        speed,
1023	        fire,
1024	        noDamage: true,
1025	        heading: right.clone().multiplyScalar(-1),
1026	        aimWeight: 1,
1027	        reloadEvery: reload || 0,
1028	        suppression: crouch ? 0.15 : 0,
1029	      };
1030	      // stagger the burst timers so the frame catches muzzle flashes
1031	      a.burstCooldown = this.rng.range(0, 0.3);
1032	      a.burstLeft = this.rng.int(2, 6);
1033	      a.peeking = true;
1034	      a.aimTarget.copy(this.playerPosition(this._v3));
1035	      a.animator.update(0.016, 0);
1036	      placedPositions.push(pos.clone());
1037	      this._stagedAgents = (this._stagedAgents ?? []);
1038	      this._stagedAgents.push(a);
1039	      if (this.debugLog) {
1040	        console.info(
1041	          `[ai] staged ${variant} at ${pos.x.toFixed(1)},${pos.y.toFixed(2)},${pos.z.toFixed(1)} ` +
1042	            `d=${cam.position.distanceTo(pos).toFixed(1)}m`
1043	        );
1044	      }
1045	    }
1046	
1047	    // One man already down, handed to the ragdoll solver with the round's
1048	    // impulse — it dresses the tableau and it exercises the death path.
1049	    const dPos = this._stageSlot(cam, -0.58, 9.4, placedPositions);
1050	    const casualty = this.spawn('breacher', dPos, Math.atan2(cam.position.x - dPos.x, cam.position.z - dPos.z));
1051	    squad.add(casualty);
1052	    casualty.animator.update(0.016, 0);
1053	    const hit = new THREE.Vector3(dPos.x, dPos.y + 1.35, dPos.z);
1054	    const inc = new THREE.Vector3().subVectors(hit, cam.position).normalize();
1055	    casualty.applyDamage(260, 'torso', hit, inc);
1056	
1057	    return this.stats;
1058	  }
1059	
1060	  /** Model inspection line-up (dev only). */
1061	  _stageInspect() {
1062	    const cam = this.ctx.camera;
1063	    const F = new THREE.Vector3(0, 0, -1).applyQuaternion(cam.quaternion);
1064	    F.y = 0;
1065	    F.normalize();
1066	    const right = new THREE.Vector3(F.z, 0, -F.x);
1067	    this.ctx.peek('sky')?.setTimeOfDay?.(11.5);
