105	/* ====================================================================== */
106	/* 2. strafe                                                              */
107	/* ====================================================================== */
108	
109	export async function scenarioStrafe() {
110	  const { engine, rec } = await bootPlay();
111	  const holds = [
112	    hold('KeyD', sec(0.2), sec(2.0)),
113	    hold('KeyA', sec(2.4), sec(4.2)),
114	    hold(['ShiftLeft', 'KeyW', 'KeyD'], sec(4.6), sec(6.4)),
115	  ];
116	  const { samples } = play(engine, rec, { frames: sec(7.0), timeline: timelineOf(holds) });
117	
118	  const p = engine.ctx.peek('player');
119	  const yaw = p.movement.yaw;
120	  const rightX = Math.cos(yaw);
121	  const rightZ = -Math.sin(yaw);
122	  const disp = (a, b) => {
123	    const s0 = samples[sec(a)];
124	    const s1 = samples[sec(b)];
125	    return {
126	      right: +((s1.x - s0.x) * rightX + (s1.z - s0.z) * rightZ).toFixed(2),
127	      dist: +Math.hypot(s1.x - s0.x, s1.z - s0.z).toFixed(2),
128	    };
129	  };
130	  const rightLeg = disp(0.4, 1.9);
131	  const leftLeg = disp(2.6, 4.1);
132	  const peakStrafeSpeed = Math.max(...samples.slice(sec(0.6), sec(1.9)).map((s) => s.speed));
133	  const diagonal = disp(4.8, 6.3);
134	
135	  const pass =
136	    rightLeg.right > 3.5 &&
137	    leftLeg.right < -3.5 &&
138	    peakStrafeSpeed > 3.6 &&
139	    diagonal.dist > 6;
140	
141	  engine.dispose();
142	  return {
143	    name: 'strafe', pass,
144	    strafeRightM: rightLeg.right, strafeLeftM: leftLeg.right,
145	    peakStrafeSpeed: +peakStrafeSpeed.toFixed(2),
146	    sprintDiagonalM: diagonal.dist,
147	  };
148	}
