151	/* 3. slide                                                               */
152	/* ====================================================================== */
153	
154	export async function scenarioSlide() {
155	  const { engine, rec } = await bootPlay();
156	  const holds = [
157	    hold(['KeyW', 'ShiftLeft'], sec(0.2), sec(4.5)),
158	    hold('ControlLeft', sec(1.6), sec(1.7)),   // slide from a forward sprint
159	    hold('ControlLeft', sec(3.2), sec(3.3)),   // and again
160	    hold('Space', sec(3.55), sec(3.62)),       // slide-cancel into a jump
161	  ];
162	  const { samples } = play(engine, rec, { frames: sec(5.0), timeline: timelineOf(holds) });
163	
164	  const slideFrames = samples.filter((s) => s.sliding).length;
165	  const firstSlide = samples.findIndex((s) => s.sliding);
166	  const sprintPeak = Math.max(...samples.slice(sec(0.6), sec(1.5)).map((s) => s.speed));
167	  const slidePeak = Math.max(...samples.filter((s) => s.sliding).map((s) => s.speed), 0);
168	  const crouchedDuringSlide = samples.filter((s) => s.sliding).every((s) => s.stance === 'crouch');
169	  const jumpedOut = samples.slice(sec(3.5), sec(4.0)).some((s) => !s.grounded);
170	  const recovered = samples.slice(sec(4.2), sec(4.9)).some((s) => s.speed > 3);
171	
172	  const pass =
173	    slideFrames > 30 &&
174	    firstSlide > 0 && firstSlide < sec(2.1) &&
175	    slidePeak > sprintPeak * 1.05 &&
176	    crouchedDuringSlide &&
177	    jumpedOut &&
178	    recovered;
179	
180	  engine.dispose();
181	  return {
182	    name: 'slide', pass,
183	    slideFrames, firstSlideFrame: firstSlide,
184	    sprintPeak: +sprintPeak.toFixed(2), slidePeak: +slidePeak.toFixed(2),
185	    crouchedDuringSlide, slideCancelJumped: jumpedOut, recoveredAfter: recovered,
186	  };
187	}
