367	export async function scenarioAiDeath() {
368	  const { engine, rec } = await bootPlay({ populate: true });
369	  const ai = engine.ctx.peek('ai');
370	  if (!ai?.agents.length) {
371	    engine.dispose();
372	    return { name: 'ai-death', pass: false, reason: 'no enemies spawned' };
373	  }
374	  const victim = ai.agents[0];
375	  const startY = victim.position.y;
376	  const deaths = [];
377	  engine.events.on('actor:death', (e) => deaths.push(engine.time.frame));
378	
379	  const timeline = (drv, eng, i) => {
380	    if (i === sec(1.0)) {
381	      const p = victim.position;
382	      victim.applyDamage(500, 'torso', { x: p.x, y: p.y + 1.3, z: p.z }, { x: 0, y: 0, z: 1 });
383	    }
384	  };
385	  const { aiSamples } = play(engine, rec, { frames: sec(14), timeline, trackAi: true });
386	
387	  const rec0 = aiSamples.map((f) => f.find((a) => a.id === victim.id)).filter(Boolean);
388	  const diedAt = rec0.findIndex((a) => !a.alive);
389	  const fadeSeen = rec0.some((a) => a.opacity !== undefined && a.opacity < 0.99 && a.opacity > 0);
390	  const removed = rec0[rec0.length - 1] === undefined || !ai.agents.includes(victim);
391	  const ragdoll = !!victim.ragdoll;
392	  const fellY = ragdoll && victim.ragdoll.aabb
393	    ? +(startY + 1.7 - victim.ragdoll.aabb.maxy).toFixed(2)
394	    : null;
395	
396	  const pass = diedAt > 0 && deaths.length === 1 && ragdoll && fadeSeen && removed;
397	
398	  engine.dispose();
399	  return {
400	    name: 'ai-death', pass,
401	    diedAtSample: diedAt, deathEvents: deaths.length,
402	    ragdollCreated: ragdoll, bodyDroppedM: fellY,
403	    fadeOutObserved: fadeSeen, corpseCleanedUp: removed,
404	    remainingAgents: ai.agents.length,
405	  };
406	}
