412	/**
413	 * For every browser shortcut we can collide with, press it the way a player
414	 * would and record two things: did the game get the key, and did anything stop
415	 * the browser acting on it. A key that is bound to gameplay and leaves
416	 * `defaultPrevented === false` is a page that bookmarks itself mid-firefight.
417	 */
418	export async function scenarioKeys() {
419	  const { engine, rec } = await bootPlay();
420	  const bound = new Set(Object.values(ACTIONS).flat());
421	  const drv = makeDriver(engine);
422	  engine.input.pointerLocked = true;
423	
424	  const rows = [];
425	  for (const [mod, code, what, reserved] of BROWSER_SHORTCUTS) {
426	    if (mod === 'ctrl') drv.down('ControlLeft');
427	    if (mod === 'shift') drv.down('ShiftLeft');
428	    const extra = mod === 'alt' ? { alt: true } : {};
429	    const r = drv.down(code, extra);
430	    drv.up(code, extra);
431	    if (mod === 'ctrl') drv.up('ControlLeft');
432	    if (mod === 'shift') drv.up('ShiftLeft');
433	
434	    const isBound = bound.has(code);
435	    rows.push({
436	      combo: mod === 'none' ? code : `${mod}+${code}`,
437	      browserAction: what,
438	      boundInGame: isBound,
439	      gameReceived: r.registered,
440	      browserDefaultPrevented: r.prevented,
441	      reservedByBrowser: reserved,
442	      // A reserved shortcut (Ctrl+W) cannot be cancelled by preventDefault at
443	      // all; only the Keyboard Lock API in fullscreen stops it reaching Chrome.
444	      ok: reserved ? true : (!isBound || r.prevented),
445	      needsKeyboardLock: reserved && isBound,
446	    });
447	  }
448	
449	  // Keys the game claims must actually arrive while playing.
450	  const lost = rows.filter((r) => r.boundInGame && !r.gameReceived);
451	  const leaks = rows.filter((r) => !r.ok);
452	  const locks = rows.filter((r) => r.needsKeyboardLock);
453	
454	  engine.dispose();
455	  return {
456	    name: 'browser-keys',
457	    pass: leaks.length === 0 && lost.length === 0,
458	    leakingCombos: leaks.map((r) => `${r.combo} (${r.browserAction})`),
459	    swallowedGameKeys: lost.map((r) => r.combo),
460	    needKeyboardLock: locks.map((r) => r.combo),
461	    rows,
462	  };
463	}
