111	/** Put the engine into a playable state: input live, pointer locked, control on. */
112	export function engagePlay(engine, { populate = false } = {}) {
113	  engine.input.enabled = true;
114	  engine.input.frozen = false;
115	  engine.input.pointerLocked = true;
116	  engine.ctx.peek('player')?.setControlEnabled?.(true);
117	  const ai = engine.ctx.peek('ai');
118	  if (populate && ai && ai.agents.length === 0) {
119	    ai.forcePopulate = true;
120	    try { ai.populate(); } catch (err) { console.warn('[play] populate failed', err?.message ?? err); }
121	  }
122	  return ai;
123	}
