125	/** One frame's worth of everything the gameplay tests care about. */
126	export function sample(engine) {
127	  const p = engine.ctx.peek('player');
128	  const m = p?.movement;
129	  const h = p?.health;
130	  return {
131	    frame: engine.time.frame,
132	    t: +engine.time.elapsed.toFixed(3),
133	    state: m?.state ?? null,
134	    stance: m?.stance ?? null,
135	    stanceWant: m?.stanceWant ?? null,
136	    sliding: !!m?.sliding,
137	    sprinting: !!m?.sprinting,
138	    grounded: !!m?.grounded,
139	    speed: +(m?.horizontalSpeed ?? 0).toFixed(3),
140	    eye: +(m ? m.eyeHeight : 0).toFixed(3),
141	    x: +(m?.position.x ?? 0).toFixed(3),
142	    y: +(m?.position.y ?? 0).toFixed(3),
143	    z: +(m?.position.z ?? 0).toFixed(3),
144	    health: h ? +h.value.toFixed(2) : null,
145	    dead: !!h?.dead,
146	    regen: !!h?.regenerating,
147	    control: !!p?.controlEnabled,
148	  };
149	}
