26	/* ------------------------------------------------------------------ */
27	/* Binary heap for A*                                                  */
28	/* ------------------------------------------------------------------ */
29	
30	class Heap {
31	  constructor(cap) {
32	    this.idx = new Int32Array(cap);
33	    this.key = new Float32Array(cap);
34	    this.n = 0;
35	  }
36	
37	  clear() {
38	    this.n = 0;
39	  }
40	
41	  push(i, k) {
42	    if (this.n >= this.idx.length) return;
43	    let c = this.n++;
44	    this.idx[c] = i;
45	    this.key[c] = k;
46	    while (c > 0) {
47	      const p = (c - 1) >> 1;
48	      if (this.key[p] <= this.key[c]) break;
49	      const ti = this.idx[p], tk = this.key[p];
50	      this.idx[p] = this.idx[c]; this.key[p] = this.key[c];
51	      this.idx[c] = ti; this.key[c] = tk;
52	      c = p;
53	    }
54	  }
55	
56	  pop() {
57	    const top = this.idx[0];
58	    this.n--;
59	    if (this.n > 0) {
60	      this.idx[0] = this.idx[this.n];
61	      this.key[0] = this.key[this.n];
62	      let c = 0;
63	      for (;;) {
64	        const l = c * 2 + 1, r = l + 1;
65	        let m = c;
66	        if (l < this.n && this.key[l] < this.key[m]) m = l;
67	        if (r < this.n && this.key[r] < this.key[m]) m = r;
68	        if (m === c) break;
69	        const ti = this.idx[m], tk = this.key[m];
70	        this.idx[m] = this.idx[c]; this.key[m] = this.key[c];
71	        this.idx[c] = ti; this.key[c] = tk;
72	        c = m;
73	      }
74	    }
75	    return top;
76	  }
77	}
