86	    this.cell = opts.cell ?? 0.8;
87	    this.radius = opts.radius ?? 0.36;
88	    this.height = opts.height ?? 1.78;
89	    this.crouchHeight = opts.crouchHeight ?? 1.15;
90	    this.maxStep = opts.maxStep ?? 0.45;
91	    this.maxSlope = Math.cos((opts.maxSlopeDeg ?? 46) * Math.PI / 180);
