93	    const b = opts.bounds;
94	    this.minX = Math.floor(b.min.x / this.cell) * this.cell;
95	    this.minZ = Math.floor(b.min.z / this.cell) * this.cell;
96	    this.nx = Math.max(1, Math.ceil((b.max.x - this.minX) / this.cell));
97	    this.nz = Math.max(1, Math.ceil((b.max.z - this.minZ) / this.cell));
98	    this.topY = b.max.y + 4;
