100	    const n = this.nx * this.nz;
101	    /** 0 = blocked, 1 = walkable standing, 2 = walkable crouched only */
102	    this.flags = new Uint8Array(n);
103	    this.floor = new Float32Array(n);
104	    this.floor.fill(-Infinity);
105	    /** how enclosed a cell is: 0 open, 1 hemmed in — used for cover scoring */
106	    this.enclosure = new Uint8Array(n);
107	
108	    // A* working set
109	    this.gScore = new Float32Array(n);
110	    this.came = new Int32Array(n);
111	    this.visitStamp = new Int32Array(n);
112	    this.stamp = 0;
113	    this.open = new Heap(Math.min(n, 1 << 16));
114	
115	    this._v = new THREE.Vector3();
116	    this._v2 = new THREE.Vector3();
117	    this._p0 = new THREE.Vector3();
118	    this._p1 = new THREE.Vector3();
119	    this.buildMs = 0;
120	    this.walkableCount = 0;
121	  }
122	
123	  index(ix, iz) {
124	    return iz * this.nx + ix;
125	  }
126	
127	  cellX(x) {
128	    return Math.round((x - this.minX) / this.cell);
129	  }
130	
131	  cellZ(z) {
132	    return Math.round((z - this.minZ) / this.cell);
133	  }
134	
135	  worldX(ix) {
136	    return this.minX + ix * this.cell;
137	  }
138	
139	  worldZ(iz) {
