147	  /** Sample the physics world. ~2 rays per cell; logged so the cost is visible. */
148	  build() {
149	    const t0 = performance.now();
150	    const phys = this.physics;
151	    const MASK = phys.MASK.WORLD;
152	    const r = this.radius;
153	    let walk = 0;
154	    for (let iz = 0; iz < this.nz; iz++) {
155	      for (let ix = 0; ix < this.nx; ix++) {
156	        const i = this.index(ix, iz);
157	        const x = this.worldX(ix), z = this.worldZ(iz);
158	        const down = phys.raycast(x, this.topY, z, 0, -1, 0, this.topY + 30, MASK);
159	        if (!down.hit) continue;
