import { boot } from '../tools/cli/harness.mjs';
import { play, engagePlay } from '../tools/cli/play.mjs';

const { engine, rec } = await boot({ quality: 'low', deterministic: true, width: 960, height: 600, dpr: 1 });
engagePlay(engine, { populate: true });
const ai = engine.ctx.peek('ai');

// who asks, how often, and what comes back
const per = new Map();
const bump = (id, k) => {
  let r = per.get(id);
  if (!r) per.set(id, (r = { req: 0, deferred: 0, empty: 0, ok: 0, startBad: 0, goalBad: 0, noRoute: 0 }));
  r[k]++;
};
let current = null;
const origUpdate = ai.agents[0].constructor.prototype.update;
ai.agents[0].constructor.prototype.update = function (dt, ctx) {
  current = this.id;
  return origUpdate.call(this, dt, ctx);
};
const origReq = ai.requestPath.bind(ai);
ai.requestPath = (from, dest, out) => {
  bump(current, 'req');
  const g = ai.grid;
  const n = origReq(from, dest, out);
  if (n < 0) bump(current, 'deferred');
  else if (n === 0) {
    bump(current, 'empty');
    const s = g.nearest(from.x, from.z, from.y);
    const t = g.nearest(dest.x, dest.z, dest.y);
    if (s < 0) bump(current, 'startBad');
    else if (t < 0) bump(current, 'goalBad');
    else bump(current, 'noRoute');
  } else bump(current, 'ok');
  return n;
};

play(engine, rec, { frames: 1200 });
for (const [id, r] of [...per].sort((a, b) => a[0] - b[0])) {
  console.error(`agent ${id}`, JSON.stringify(r));
}
console.error('stats', JSON.stringify(ai.stats));
for (const a of ai.agents) {
  console.error(`  a${a.id} ${a.state} sp=${a.speed.toFixed(2)} pos=${a.position.x.toFixed(1)},${a.position.z.toFixed(1)}`);
}

