import { boot } from '../tools/cli/harness.mjs';
import { engagePlay } from '../tools/cli/play.mjs';

const { engine } = await boot({ quality: 'low', deterministic: true, width: 960, height: 600, dpr: 1 });
engagePlay(engine, { populate: true });
const ai = engine.ctx.peek('ai');
const g = ai.grid;

// connected components over the 8-neighbourhood, same rules findPath uses
const DX = [1, -1, 0, 0, 1, 1, -1, -1];
const DZ = [0, 0, 1, -1, 1, -1, 1, -1];
const comp = new Int32Array(g.nx * g.nz).fill(-1);
const sizes = [];
const stack = [];
for (let iz = 0; iz < g.nz; iz++) {
  for (let ix = 0; ix < g.nx; ix++) {
    const i = g.index(ix, iz);
    if (!g.walkable(ix, iz) || comp[i] >= 0) continue;
    const id = sizes.length;
    let n = 0;
    stack.length = 0;
    stack.push(i);
    comp[i] = id;
    while (stack.length) {
      const cur = stack.pop();
      n++;
      const cx = cur % g.nx, cz = (cur / g.nx) | 0;
      const cy = g.floor[cur];
      for (let d = 0; d < 8; d++) {
        const jx = cx + DX[d], jz = cz + DZ[d];
        if (!g.walkable(jx, jz)) continue;
        if (DX[d] && DZ[d] && (!g.walkable(cx + DX[d], cz) || !g.walkable(cx, cz + DZ[d]))) continue;
        const j = g.index(jx, jz);
        if (comp[j] >= 0) continue;
        if (Math.abs(g.floor[j] - cy) > g.maxStep) continue;
        comp[j] = id;
        stack.push(j);
      }
    }
    sizes.push(n);
  }
}
const ranked = sizes.map((n, i) => ({ i, n })).sort((a, b) => b.n - a.n);
console.error(`components: ${sizes.length}  walkable: ${g.walkableCount}`);
console.error('largest 8:', ranked.slice(0, 8).map((r) => `#${r.i}=${r.n}`).join(' '));
