const where = (x, z, y) => {
  const i = g.nearest(x, z, y);
  return i < 0 ? 'none' : `#${comp[i]}(${sizes[comp[i]]})`;
};
for (const a of ai.agents) {
  const pts = (a.patrolPoints ?? []).map((p) => where(p.x, p.z, p.y)).join(' ');
  console.error(`agent ${a.id} at ${where(a.position.x, a.position.z, a.position.y)}  patrol: ${pts}`);
}
const pc = {};
for (const p of ai.cover.points) {
  const k = where(p.x, p.z, p.y);
  pc[k] = (pc[k] ?? 0) + 1;
}
console.error('cover points by component:', JSON.stringify(pc));
const pp = engine.ctx.peek('player').position;
console.error('player at', where(pp.x, pp.z, pp.y));

