import { boot } from '../tools/cli/harness.mjs';

const { engine, rec } = await boot({ quality: 'low', deterministic: true, width: 640, height: 400, dpr: 1 });
const ai = engine.ctx.peek('ai');
ai.debugStage('firefight');

const Agent = ai.agents[0].constructor;
let held = 0, fired = 0;
const origLine = Agent.prototype._friendlyInLine;
Agent.prototype._friendlyInLine = function () {
  const r = origLine.call(this);
  if (r) held++;
  return r;
};
const origRound = Agent.prototype._fireRound;
Agent.prototype._fireRound = function () { fired++; return origRound.call(this); };

let now = 1000;
for (let i = 0; i < 90; i++) { rec?.beginFrame(); now += 1000 / 60; engine.step(now); }
console.error(`staged: ${ai.agents.length} agents, ${ai.agents.filter((a) => a.alive).length} alive`);
console.error(`rounds fired ${fired}, held for a squadmate ${held}`);
for (const a of ai.agents) {
  console.error(`  a${a.id} ${a.variantName} alive=${a.alive} hp=${a.health.toFixed(0)} clip=${a.clip} fade=${a.fadeOpacity}`);
}

