1	/**
2	 * AI — squad coordination.
3	 *
4	 * The squad exists to stop four individually-sensible soldiers from behaving
5	 * like one four-headed idiot: it hands out permission to peek so they alternate
6	 * instead of all leaning out together, shares contact reports so one man
7	 * spotting you alerts the rest (after a believable call-out delay), rations
8	 * grenades, and allows only one flanker at a time.
9	 */
10	
11	import * as THREE from 'three';
12	
13	let _nextSquad = 1;
14	
15	export class Squad {
16	  constructor(rng) {
17	    this.id = _nextSquad++;
18	    this.members = [];
19	    this.rng = rng;
20	    this.peekTokens = 1;
21	    this.peekHolders = new Set();
22	    this.peekTimer = 0;
23	    this.grenadeCooldown = 6;
24	    this.flanker = null;
25	    this.contact = new THREE.Vector3();
26	    this.hasContact = false;
27	    this.contactAge = Infinity;
28	    this._pending = [];
29	  }
30	
31	  add(agent) {
32	    agent.squad = this;
33	    this.members.push(agent);
34	    this.peekTokens = Math.max(1, Math.round(this.members.length * 0.5));
35	    return agent;
36	  }
37	
38	  get alive() {
39	    let n = 0;
40	    for (const m of this.members) if (m.alive) n++;
41	    return n;
42	  }
43	
44	  /** Called once per frame by the AI system. */
45	  update(dt) {
46	    this.grenadeCooldown -= dt;
47	    this.contactAge += dt;
48	    if (this.flanker && (!this.flanker.alive || this.flanker.state !== 'flank')) this.flanker = null;
49	
50	    // contact sharing: whoever can see the player broadcasts, with a delay
51	    for (const m of this.members) {
52	      if (!m.alive) continue;
53	      if (m.hasTarget && m.targetVisible) {
54	        this.contact.copy(m.lastKnown);
55	        this.hasContact = true;
56	        this.contactAge = 0;
57	        break;
58	      }
59	    }
60	    if (this.hasContact && this.contactAge < 4) {
61	      for (const m of this.members) {
62	        if (!m.alive || m.hasTarget) continue;
63	        // a call-out only gives a direction to check, never a free kill
64	        if (m.lastKnownAge > 1.5) {
65	          m.lastKnown.copy(this.contact);
66	          m.lastKnownAge = 0.9 + this.rng.float() * 0.8;
67	          m.alertness = 1;
68	          if (m.state === 'idle' || m.state === 'patrol') m._setState('alert');
69	        }
70	      }
71	    }
72	
73	    // rotate the peek tokens so the same man is not always exposed
74	    this.peekTimer -= dt;
75	    if (this.peekTimer <= 0) {
76	      this.peekTimer = 1.1 + this.rng.float() * 1.2;
77	      this.peekHolders.clear();
78	    }
79	  }
80	
81	  /** Ask to lean out of cover. Only `peekTokens` members may at once. */
82	  requestPeek(agent, dt) {
83	    if (this.peekHolders.has(agent.id)) return true;
84	    if (this.peekHolders.size >= this.peekTokens) return false;
85	    this.peekHolders.add(agent.id);
86	    return true;
87	  }
88	
89	  releasePeek(agent) {
90	    this.peekHolders.delete(agent.id);
91	  }
92	
93	  /** One flanker at a time, and only if someone else is holding attention. */
94	  canFlank(agent) {
95	    if (this.flanker) return false;
96	    let shooting = 0;
97	    for (const m of this.members) {
98	      if (m !== agent && m.alive && (m.state === 'combat' || m.state === 'suppressed')) shooting++;
99	    }
100	    return shooting >= 1;
101	  }
102	
103	  claimFlank(agent) {
104	    this.flanker = agent;
105	  }
106	
107	  requestGrenade() {
108	    if (this.grenadeCooldown > 0) return false;
109	    this.grenadeCooldown = 14 + this.rng.float() * 12;
110	    return true;
111	  }
112	}
