30	/** Build a timeline function from a list of hold() specs. */
31	function timelineOf(holds) {
32	  return (drv, engine, i) => {
33	    for (const h of holds) {
34	      if (i === h.from) for (const c of h.codes) drv.down(c);
35	      if (i === h.to) for (const c of h.codes) drv.up(c);
