50	/**
51	 * Ducking has to work while you are moving, on both bound keys, and it has to
52	 * let go again. The interesting half is Ctrl: it is a browser modifier, so a
53	 * crouch-and-strafe sends `ctrlKey: true` on the D keydown.
54	 */
55	export async function scenarioCrouch() {
56	  const { engine, rec } = await bootPlay();
57	  const holds = [
58	    hold('KeyW', sec(0.2), sec(6.0)),        // walk the whole time
59	    hold('ControlLeft', sec(1.0), sec(2.5)), // hold-crouch
60	    hold('KeyD', sec(1.4), sec(2.2)),        // strafe WHILE crouched (Ctrl+D = bookmark)
61	    hold('KeyC', sec(3.5), sec(3.6)),        // tap-toggle crouch on
62	    hold('KeyC', sec(5.0), sec(5.1)),        // tap-toggle crouch off
63	  ];
64	  const { samples, keyLog } = play(engine, rec, { frames: sec(6.5), timeline: timelineOf(holds) });
65	
66	  const win = (a, b) => samples.slice(sec(a), sec(b));
67	  const crouchedWhileHeld = win(1.3, 2.4).filter((s) => s.stance === 'crouch').length;
68	  const heldWindow = win(1.3, 2.4).length;
69	  const standAfterRelease = win(3.0, 3.4).every((s) => s.stance === 'stand');
70	  const toggledOn = win(4.0, 4.8).filter((s) => s.stance === 'crouch').length;
71	  const toggledOff = win(5.6, 6.4).every((s) => s.stance === 'stand');
72	
73	  // Did the player keep moving while crouched with Ctrl held?
74	  const a = samples[sec(1.5)];
75	  const b = samples[sec(2.2)];
76	  const movedWhileCrouched = +Math.hypot(b.x - a.x, b.z - a.z).toFixed(3);
77	
78	  const dKeys = keyLog.filter((k) => k.code === 'KeyD');
79	  const ctrlDLost = dKeys.filter((k) => k.ctrl && !k.registered).length;
80	  const ctrlDUnprevented = dKeys.filter((k) => k.ctrl && !k.prevented).length;
81	
82	  const pass =
83	    crouchedWhileHeld > heldWindow * 0.8 &&
84	    standAfterRelease &&
85	    toggledOn > 20 &&
86	    toggledOff &&
87	    movedWhileCrouched > 0.6 &&
88	    ctrlDLost === 0 &&
89	    ctrlDUnprevented === 0;
90	
91	  engine.dispose();
92	  return {
93	    name: 'crouch', pass,
94	    holdCrouchFrames: `${crouchedWhileHeld}/${heldWindow}`,
95	    standsUpOnRelease: standAfterRelease,
96	    tapToggleOnFrames: toggledOn,
97	    tapToggleOffClean: toggledOff,
98	    movedWhileCrouchedM: movedWhileCrouched,
99	    ctrlDKeysLost: ctrlDLost,
100	    ctrlDBrowserDefaultsNotPrevented: ctrlDUnprevented,
101	    eyeHeights: [samples[sec(0.9)].eye, samples[sec(2.0)].eye, samples[sec(3.2)].eye],
102	  };
103	}
