189	/**
190	 * The slide entry people actually use and the old code refused: a DIAGONAL
191	 * sprint. `sprinting` needs the stick within ~56 degrees of dead ahead, so
192	 * W+D+Shift never set the flag and the crouch key just crouched. The gate is
193	 * speed now, so this has to produce a slide — and a walk still must not.
194	 */
195	export async function scenarioSlideStrafe() {
196	  const { engine, rec } = await bootPlay();
197	  const holds = [
198	    hold(['KeyW', 'KeyD', 'ShiftLeft'], sec(0.2), sec(3.0)),
199	    hold('ControlLeft', sec(2.0), sec(2.1)),
200	    // …and a plain walk with the same crouch tap must NOT slide.
201	    hold('KeyW', sec(4.2), sec(7.0)),
202	    hold('ControlLeft', sec(6.0), sec(6.1)),
203	  ];
204	  const { samples } = play(engine, rec, { frames: sec(7.2), timeline: timelineOf(holds) });
205	
206	  const diagonalSlide = samples.slice(sec(2.0), sec(3.0)).filter((s) => s.sliding).length;
207	  const walkSlide = samples.slice(sec(6.0), sec(7.0)).filter((s) => s.sliding).length;
208	  const walkCrouched = samples.slice(sec(6.3), sec(6.9)).every((s) => s.stance === 'crouch');
209	  const peak = Math.max(...samples.slice(sec(2.0), sec(3.0)).map((s) => s.speed));
210	
211	  const pass = diagonalSlide > 25 && walkSlide === 0 && walkCrouched;
212	
213	  engine.dispose();
214	  return {
215	    name: 'slide-strafe', pass,
216	    diagonalSprintSlideFrames: diagonalSlide,
217	    diagonalSlidePeak: +peak.toFixed(2),
218	    walkSlideFrames: walkSlide,
219	    walkCrouchedInstead: walkCrouched,
220	  };
221	}
