282	/* ====================================================================== */
283	/* 5. regeneration                                                        */
284	/* ====================================================================== */
285	
286	export async function scenarioRegen() {
287	  const { engine, rec } = await bootPlay();
288	  const player = engine.ctx.peek('player');
289	
290	  const timeline = (drv, eng, i) => {
291	    if (i === sec(0.5)) player.applyDamage(24, null, { type: 'bullet' });
292	    if (i === sec(1.0)) player.applyDamage(24, null, { type: 'bullet' });
293	    if (i === sec(1.5)) player.applyDamage(22, null, { type: 'bullet' });
294	    // still under fire at 3.0 s: the regen clock must restart
295	    if (i === sec(3.0)) player.applyDamage(6, null, { type: 'bullet' });
296	    // 7.6 s would be the earliest legal restart. Sustained fire cracking past
297	    // from 7.4 to 8.6 s means we are still in contact and must still not heal.
298	    // 20 Hz of near misses is one enemy holding us down, not a stray round.
299	    if (i >= sec(7.4) && i <= sec(8.6) && i % 3 === 0) player.addSuppression(0.28);
300	  };
301	  const { samples } = play(engine, rec, { frames: sec(16), timeline });
302	
303	  const low = Math.min(...samples.map((s) => s.health));
304	  const startedAt = samples.findIndex((s) => s.regen);
305	  // The last hit lands at 3.0 s, so nothing may regenerate before ~7.6 s: the
306	  // delay is measured from the LAST hit, not the first.
307	  const restarted = samples.slice(sec(3.05), sec(7.4)).every((s) => !s.regen);
308	  // While rounds are still cracking past (7.4 – 8.6 s) nothing may heal.
309	  const heldUnderFire = samples.slice(sec(7.5), sec(8.7)).every((s) => !s.regen);
310	  const full = samples[samples.length - 1].health;
311	  const fullAt = samples.findIndex((s, i) => i > sec(3) && s.health >= 99.9);
312	
313	  const pass =
314	    low <= 30 &&
315	    startedAt > sec(7.0) &&
316	    restarted &&
317	    heldUnderFire &&
318	    full >= 99.9 &&
319	    fullAt > sec(8) && fullAt < sec(15);
320	
321	  engine.dispose();
322	  return {
323	    name: 'regen', pass,
324	    lowestHealth: +low.toFixed(1),
325	    firstRegenFrame: startedAt,
326	    regenClockRestartedAfterHit: restarted,
327	    heldWhileUnderFire: heldUnderFire,
328	    fullAgainAtFrame: fullAt,
329	    finalHealth: +full.toFixed(1),
330	  };
331	}
