1	/**
2	 * Boots the REAL engine -- same Engine, same systems, same config, same world
3	 * generation -- inside Node, against the recording GL mock. No browser.
4	 *
5	 * Frames are pumped by hand through engine.step(t) with synthetic timestamps,
6	 * so the simulation is deterministic and two runs are directly comparable. The
7	 * wall-clock cost of each step is still measured for real, because that is
8	 * genuine JS work: culling, physics, AI, animation, scene-graph traversal and
9	 * every per-frame allocation.
10	 */
11	import { performance } from 'node:perf_hooks';
12	
13	const FIXED_STEP_MS = 1000 / 60;
14	
15	/** Systems in the same registration order main.js uses. */
16	async function loadSystems() {
17	  const [
18	    { Engine }, { createConfig },
19	    { RenderSystem }, { MaterialSystem }, { SkySystem }, { WorldSystem },
20	    { PhysicsSystem }, { PlayerSystem }, { WeaponSystem }, { FxSystem },
21	    { AiSystem }, { UiSystem }, { AudioSystem },
22	  ] = await Promise.all([
23	    import('../../src/core/engine.js'), import('../../src/core/config.js'),
24	    import('../../src/render/index.js'), import('../../src/materials/index.js'),
25	    import('../../src/sky/index.js'), import('../../src/world/index.js'),
26	    import('../../src/physics/index.js'), import('../../src/player/index.js'),
27	    import('../../src/weapons/index.js'), import('../../src/fx/index.js'),
28	    import('../../src/ai/index.js'), import('../../src/ui/index.js'),
29	    import('../../src/audio/index.js'),
30	  ]);
31	  return { Engine, createConfig, systems: [RenderSystem, MaterialSystem, SkySystem, WorldSystem, PhysicsSystem, PlayerSystem, WeaponSystem, FxSystem, AiSystem, UiSystem, AudioSystem] };
32	}
33	
34	/**
35	 * @param quality  'low' | 'medium' | 'high' | 'ultra'
36	 * @param width/height/dpr  logical size; the render target ends up w*dpr x h*dpr
37	 * @param qset  ablation overrides merged into cfg.q, e.g. { prepassDepthReuse: false }.
38	 *              Re-applied after any setQuality() call so the adaptive scaler cannot
39	 *              silently restore the preset value mid-run and invalidate an A/B.
40	 */
41	export async function boot({ quality = 'ultra', width = 1512, height = 982, dpr = 2, deterministic = true, onProgress = null, qset = null } = {}) {
42	  const { installDom } = await import('./dom-shim.mjs');
43	  const { createGLMock } = await import('./gl-mock.mjs');
44	
45	  const dom = installDom({ width, height, dpr });
46	  const { gl, rec } = createGLMock({ width: width * dpr, height: height * dpr });
47	  dom.canvas._gl = gl;
48	  dom.canvas.width = width * dpr;
49	  dom.canvas.height = height * dpr;
50	
51	  const { Engine, createConfig, systems } = await loadSystems();
52	  const config = createConfig({ quality, deterministic });
53	
54	  if (qset && Object.keys(qset).length) {
55	    for (const k of Object.keys(qset)) {
56	      if (!(k in config.q)) throw new Error(`qset: "${k}" is not a quality key -- typo would silently measure nothing`);
57	    }
58	    Object.assign(config.q, qset);
59	    const setQuality = config.setQuality;
60	    config.setQuality = (name) => { setQuality(name); Object.assign(config.q, qset); };
61	  }
62	
63	  const engine = new Engine({ canvas: dom.canvas, config });
64	  for (const S of systems) engine.add(S);
65	
66	  const t0 = performance.now();
67	  await engine.init({ yieldBetween: false, onProgress });
68	  const bootMs = performance.now() - t0;
69	
70	  // The engine sizes itself off the canvas/window; make sure it has done so.
71	  engine.resize?.(width, height);
72	
73	  return { engine, config, gl, rec, dom, bootMs };
74	}
75	
76	/**
77	 * Pump `frames` frames and return per-frame CPU timings plus GL stream stats.
78	 *
79	 * `warm` frames run first and are discarded: the first frames after boot pay
80	 * for lazy material compiles, pool growth and first-touch allocation, which are
81	 * real costs but not steady-state ones.
82	 */
83	export function run(engine, rec, { frames = 300, warm = 60, stepMs = FIXED_STEP_MS, onFrame = null } = {}) {
84	  const dom = globalThis.__COD_DOM__;
85	  const cpuMs = [];
86	  const drawCalls = [];
87	  const triangles = [];
88	  const programSwitches = [];
89	
90	  let now = 1000;
91	  const total = frames + warm;
92	
93	  for (let i = 0; i < total; i++) {
94	    rec.beginFrame();
95	    now += stepMs;
96	
97	    const a = performance.now();
98	    engine.step(now);
99	    // Anything the engine scheduled for "next frame" runs here, inside the
100	    // frame it belongs to, so its cost is attributed rather than lost.
101	    dom.pumpRaf(now);
102	    const ms = performance.now() - a;
103	
104	    if (i >= warm) {
105	      cpuMs.push(ms);
106	      drawCalls.push(rec.drawCalls);
107	      triangles.push(rec.triangles);
108	      programSwitches.push(rec.programSwitches);
109	      onFrame?.(i - warm, rec, ms);
110	    }
111	  }
112	
113	  return { cpuMs, drawCalls, triangles, programSwitches };
114	}
115	
116	export function stats(a) {
117	  if (!a?.length) return null;
118	  const s = [...a].sort((x, y) => x - y);
119	  const q1 = s[Math.floor((s.length - 1) * 0.25)];
120	  const q3 = s[Math.floor((s.length - 1) * 0.75)];
121	  const mean = s.reduce((p, c) => p + c, 0) / s.length;
122	  return {
123	    n: s.length,
124	    mean: +mean.toFixed(3),
125	    median: +s[s.length >> 1].toFixed(3),
126	    p05: +s[Math.floor(s.length * 0.05)].toFixed(3),
127	    p95: +s[Math.floor(s.length * 0.95)].toFixed(3),
128	    max: +s[s.length - 1].toFixed(3),
129	    iqr: +(q3 - q1).toFixed(3),
130	  };
131	}
132	
133	export { FIXED_STEP_MS };
134

