/** THROWAWAY diagnostic: what a squad does around a casualty. Delete when done. */
import { boot } from './harness.mjs';
import { play, engagePlay } from './play.mjs';

const FPS = 60;
const sec = (s) => Math.round(s * FPS);

const { engine, rec } = await boot({ quality: 'low', deterministic: true, width: 960, height: 600, dpr: 1 });
engagePlay(engine, { populate: true });
const ai = engine.ctx.peek('ai');
console.info('squads', ai.squads.map((s) => ({ id: s.id, members: s.members.map((m) => m.id) })));

const sq = ai.squads[0];
const victim = sq.members[0];
const rows = [];
const KILL = sec(4.0);
const KILL2 = sec(8.0);

const timeline = (drv, eng, i) => {
  if (i === KILL) {
    const p = victim.position;
    victim.applyDamage(500, 'torso', { x: p.x, y: p.y + 1.3, z: p.z }, { x: 0, y: 0, z: 1 });
    console.info(`[kill] agent ${victim.id} at ${p.x.toFixed(1)},${p.z.toFixed(1)}`);
  }
  if (i === KILL2) {
    const v2 = sq.members.find((m) => m.alive);
    if (v2) {
      const p = v2.position;
      v2.applyDamage(500, 'torso', { x: p.x, y: p.y + 1.3, z: p.z }, { x: 0, y: 0, z: 1 });
      console.info(`[kill] agent ${v2.id} at ${p.x.toFixed(1)},${p.z.toFixed(1)}`);
    }
  }
};

const onFrame = (i) => {
  if (i % 30) return;
  const player = ai.playerPosition({ x: 0, y: 0, z: 0, set() {}, copy() {} });
  rows.push({
    f: i,
    a: ai.agents.map((a) => ({
      id: a.id,
      sq: a.squad?.id ?? 0,
      st: a.state,
      hp: Math.round(a.health),
      sup: +a.suppression.toFixed(2),
      cov: a.cover ? +a.position.distanceTo(a.coverPos).toFixed(1) : null,
      tgt: a.hasTarget ? 1 : 0,
      lka: a.lastKnownAge > 100 ? 'inf' : +a.lastKnownAge.toFixed(1),
      dBody: +a.position.distanceTo(victim.position).toFixed(1),
    })),
  });
};

play(engine, rec, { frames: sec(12), timeline, onFrame });

for (const r of rows) {
  console.info(
    `f${String(r.f).padStart(4)} ` +
      r.a
        .map((a) => `${a.id}/s${a.sq}:${a.st.padEnd(5)}hp${a.hp} sup${a.sup} cov${a.cov ?? '-'} t${a.tgt} lka${a.lka} d${a.dBody}`)
        .join(' | ')
  );
}
engine.dispose();

