/** THROWAWAY diagnostic: what a squad IN COVER does around a casualty. Delete when done. */
import { boot } from './harness.mjs';
import { play, engagePlay } from './play.mjs';

const FPS = 60;
const sec = (s) => Math.round(s * FPS);

const { engine, rec } = await boot({ quality: 'low', deterministic: true, width: 960, height: 600, dpr: 1 });
engagePlay(engine, { populate: true });
const ai = engine.ctx.peek('ai');

const sq = ai.squads[1]; // the squad that engages: agents 4,5,6
const victim = sq.members[1];
const mates = sq.members.filter((m) => m !== victim);
const KILL = sec(6.0);

const timeline = (drv, eng, i) => {
  if (i === KILL) {
    const p = victim.position;
    victim.applyDamage(500, 'torso', { x: p.x, y: p.y + 1.3, z: p.z }, { x: 0, y: 0, z: 1 });
    console.info(`[kill] agent ${victim.id}; mate dists ` +
      mates.map((m) => `${m.id}:${m.position.distanceTo(p).toFixed(1)}m cover@${m.cover ? m.coverPos.distanceTo(p).toFixed(1) : '-'}`).join(' '));
  }
};

const rows = [];
const onFrame = (i) => {
  if (i < KILL - 60 || i > KILL + 180 || i % 10) return;
  rows.push(
    `f${String(i).padStart(4)} ` +
      mates
        .map((a) =>
          `${a.id}:${a.state.padEnd(10)}sup${a.suppression.toFixed(2)} md${Math.max(0, a.manDownTimer).toFixed(2)} ` +
          `cov${a.cover ? `${a.cover.x.toFixed(0)},${a.cover.z.toFixed(0)}` : '----'} ` +
          `atCov${a.cover ? a.position.distanceTo(a.coverPos).toFixed(1) : '-'} ` +
          `dBody${a.position.distanceTo(victim.position).toFixed(1)} fire${a.wantFire ? 1 : 0} pk${a.peeking ? 1 : 0}`
        )
        .join(' | ')
  );
};

play(engine, rec, { frames: sec(14), timeline, onFrame });
for (const r of rows) console.info(r);
console.info('squad strength', sq.strength, 'casualties', sq.casualties);
engine.dispose();

