/** THROWAWAY diagnostic: mirrors the ai-squad scenario, explains cover holders. Delete when done. */
import { boot } from './harness.mjs';
import { play, engagePlay } from './play.mjs';

const FPS = 60;
const sec = (s) => Math.round(s * FPS);

const { engine, rec } = await boot({ quality: 'low', deterministic: true, width: 960, height: 600, dpr: 1 });
engagePlay(engine, { populate: true });
const ai = engine.ctx.peek('ai');
const squads = ai.squads.filter((s) => s.members.length >= 3);

const KILL1 = sec(4.0);
const KILL2 = sec(6.0);
const kill = (a) => {
  const p = a.position;
  a.applyDamage(500, 'torso', { x: p.x, y: p.y + 1.3, z: p.z }, { x: 0, y: 0, z: 1 });
};
let body2 = null;
let holders = [];

const timeline = (drv, eng, i) => {
  if (i === KILL1) kill(squads[0].members[0]);
  if (i === KILL2) {
    const v = squads[1].members[1];
    body2 = { x: v.position.x, z: v.position.z };
    holders = squads[1].members.filter(
      (m) => m.alive && m !== v && m.cover && Math.hypot(m.coverPos.x - body2.x, m.coverPos.z - body2.z) < 5
    );
    console.info(`[kill2] victim ${v.id}; holders ${holders.map((h) => `${h.id}@${Math.hypot(h.coverPos.x - body2.x, h.coverPos.z - body2.z).toFixed(1)}m state=${h.state}`).join(' ')}`);
    kill(v);
  }
};

const rows = [];
const onFrame = (i) => {
  if (!body2 || i < KILL2 - 2 || i > KILL2 + 90) return;
  rows.push(
    `f${String(i).padStart(4)} ` +
      holders
        .map((a) =>
          `${a.id}:${a.state.padEnd(8)}sup${a.suppression.toFixed(2)} md${Math.max(0, a.manDownTimer).toFixed(2)} ` +
          `cov${a.cover ? `${a.cover.x.toFixed(0)},${a.cover.z.toFixed(0)}` : '----'}@${a.cover ? Math.hypot(a.coverPos.x - body2.x, a.coverPos.z - body2.z).toFixed(1) : '-'} ` +
          `rp${a.repathTimer.toFixed(1)} pf${a.pathFailTimer.toFixed(1)} pend${a.pathPending ? 1 : 0} hold${a.coverHold.toFixed(1)}/${a.coverHoldMax.toFixed(1)}`
        )
        .join(' | ')
  );
};

play(engine, rec, { frames: sec(9), timeline, onFrame });
for (const r of rows) console.info(r);
engine.dispose();

