1: /**
2:  * AI — squad coordination.
3:  *
4:  * The squad exists to stop four individually-sensible soldiers from behaving
5:  * like one four-headed idiot: it hands out permission to peek so they alternate
6:  * instead of all leaning out together, shares contact reports so one man
7:  * spotting you alerts the rest (after a believable call-out delay), rations
8:  * grenades, and allows only one flanker at a time.
9:  *
10:  * It also reports its own dead. A casualty is the loudest thing that happens in
11:  * a firefight and it used to be the only thing the squad ignored — MEASURED on
12:  * the garrison: agent 1 was shot dead 1.1 m from agent 3, and agents 2 and 3
13:  * kept walking their patrol route with `lastKnownAge` still at infinity for the
14:  * next four seconds. `reportDown()` is what turns a body hitting the floor into
15:  * information the survivors act on: see Agent.squadmateDown().
16:  */
17: 
18: import * as THREE from 'three';
19: 
20: let _nextSquad = 1;
21: 
22: export class Squad {
23:   constructor(rng) {
24:     this.id = _nextSquad++;
25:     this.members = [];
26:     this.rng = rng;
27:     this.peekTokens = 1;
28:     this.peekHolders = new Set();
29:     this.peekTimer = 0;
30:     this.grenadeCooldown = 6;
31:     this.flanker = null;
32:     this.contact = new THREE.Vector3();
33:     this.hasContact = false;
34:     this.contactAge = Infinity;
35:     this._pending = [];
36: 
37:     /* ---------------- casualties ---------------- */
38:     /** how many of us are down, and where the last one fell */
39:     this.casualties = 0;
40:     this.lastCasualty = new THREE.Vector3();
41:     this.casualtyAge = Infinity;
42:     /** best guess at where the killing round came from */
43:     this.threat = new THREE.Vector3();
44:     this.hasThreat = false;
45:     /** fraction of the original squad still standing, refreshed each frame */
46:     this.strength = 1;
47:   }
48: 
49:   add(agent) {
50:     agent.squad = this;
51:     this.members.push(agent);
52:     this.peekTokens = Math.max(1, Math.round(this.members.length * 0.5));
53:     return agent;
54:   }
55: 
56:   get alive() {
57:     let n = 0;
58:     for (const m of this.members) if (m.alive) n++;
59:     return n;
60:   }
61: 
62:   /** Called once per frame by the AI system. */
63:   update(dt) {
64:     this.grenadeCooldown -= dt;
65:     this.contactAge += dt;
66:     this.casualtyAge += dt;
67:     // Cached rather than a getter: _combat reads it every frame per man, and it
68:     // can only change when somebody dies.
69:     this.strength = this.members.length ? this.alive / this.members.length : 0;
70:     if (this.flanker && (!this.flanker.alive || this.flanker.state !== 'flank')) this.flanker = null;
71: 
72:     // contact sharing: whoever can see the player broadcasts, with a delay
73:     for (const m of this.members) {
74:       if (!m.alive) continue;
75:       if (m.hasTarget && m.targetVisible) {
76:         this.contact.copy(m.lastKnown);
77:         this.hasContact = true;
78:         this.contactAge = 0;
79:         break;
80:       }
81:     }
82:     if (this.hasContact && this.contactAge < 4) {
83:       for (const m of this.members) {
84:         if (!m.alive || m.hasTarget) continue;
85:         // a call-out only gives a direction to check, never a free kill
86:         if (m.lastKnownAge > 1.5) {
87:           m.lastKnown.copy(this.contact);
88:           m.lastKnownAge = 0.9 + this.rng.float() * 0.8;
89:           m.alertness = 1;
90:           if (m.state === 'idle' || m.state === 'patrol') m._setState('alert');
91:         }
92:       }
93:     }
94: 
95:     // rotate the peek tokens so the same man is not always exposed
96:     this.peekTimer -= dt;
97:     if (this.peekTimer <= 0) {
98:       this.peekTimer = 1.1 + this.rng.float() * 1.2;
99:       this.peekHolders.clear();
100:     }
101:   }
102: 
103:   /**
104:    * One of ours is down. Called from Agent.die() while the body is still where
105:    * it fell, so every survivor gets the position first-hand.
106:    *
107:    * @param victim  the man who just died
108:    * @param threat  world point the killing round is estimated to have come
109:    *                from, or null when there is nothing to go on
110:    */
111:   reportDown(victim, threat) {
112:     this.casualties++;
113:     this.lastCasualty.copy(victim.position);
114:     this.casualtyAge = 0;
115:     if (threat) {
116:       this.threat.copy(threat);
117:       this.hasThreat = true;
118:     }
119:     // whatever he was holding, he is not holding it any more
120:     this.peekHolders.delete(victim.id);
121:     if (this.flanker === victim) this.flanker = null;
122: 
123:     this.strength = this.members.length ? this.alive / this.members.length : 0;
124:     for (const m of this.members) {
125:       if (m === victim || !m.alive) continue;
126:       m.squadmateDown(this.lastCasualty, this.hasThreat ? this.threat : null, this.strength);
127:     }
128:   }
129: 
130:   /** Ask to lean out of cover. Only `peekTokens` members may at once. */
131:   requestPeek(agent, dt) {
132:     if (this.peekHolders.has(agent.id)) return true;
133:     if (this.peekHolders.size >= this.peekTokens) return false;
134:     this.peekHolders.add(agent.id);
135:     return true;
136:   }
137: 
138:   releasePeek(agent) {
139:     this.peekHolders.delete(agent.id);
140:   }
141: 
142:   /** One flanker at a time, and only if someone else is holding attention. */
143:   canFlank(agent) {
144:     if (this.flanker) return false;
145:     let shooting = 0;
146:     for (const m of this.members) {
147:       if (m !== agent && m.alive && (m.state === 'combat' || m.state === 'suppressed')) shooting++;
148:     }
149:     return shooting >= 1;
150:   }
151: 
152:   claimFlank(agent) {
153:     this.flanker = agent;
154:   }
155: 
156:   requestGrenade() {
157:     if (this.grenadeCooldown > 0) return false;
158:     this.grenadeCooldown = 14 + this.rng.float() * 12;
159:     return true;
160:   }
161: }
