/**
 * THROWAWAY: does the grenade term in the flank gate ever pay for itself?
 *
 * The flank gate refuses to manoeuvre a man who has a grenade ready, on the
 * theory that he will throw it instead. This probe counts, per 10 s window:
 * how often that refusal actually fires, and how often the throw it is waiting
 * for is even possible. Delete when the question is answered.
 */
import { boot } from './harness.mjs';
import { play, engagePlay } from './play.mjs';

const FPS = 60;
const sec = (s) => Math.round(s * FPS);
const BINS = 6;

const { engine, rec } = await boot({ quality: 'low', deterministic: true, width: 960, height: 600, dpr: 1 });
engagePlay(engine, { populate: true });
const ai = engine.ctx.peek('ai');

/** actual throws, counted at the source rather than inferred from hasGrenade */
let throws = 0;
const throwsPerBin = new Array(BINS).fill(0);
const realThrow = ai.throwGrenade.bind(ai);
let bin = 0;
ai.throwGrenade = (...args) => {
  throws++;
  throwsPerBin[bin]++;
  return realThrow(...args);
};

const prev = new Map();
const z = () => new Array(BINS).fill(0);
const flankEntries = z();
// frames where every flank condition but the grenade term is met
const eligible = z();
// ... of those, the ones the grenade term actually blocks
const blocked = z();
// frames where every throw condition but the squad ration is met
const throwWindow = z();
// ... and how often the squad ration was the thing that said no
const rationedOut = z();
// men sitting on a ready grenade at all, whatever else is true
const holdingFrames = z();

const onFrame = (i) => {
  bin = Math.min(BINS - 1, Math.floor(i / sec(10)));
  for (const a of ai.agents) {
    if (!a.alive) continue;
    if (a.state === 'flank' && prev.get(a.id) !== 'flank') flankEntries[bin]++;
    prev.set(a.id, a.state);

    const holding = a.hasGrenade && a.grenadeCooldown <= 0;
    if (holding) holdingFrames[bin]++;
    if (a.state !== 'combat') continue;

    const sq = a.squad;
    if (sq && a.stateTime > 4 && sq.canFlank(a)) {
      eligible[bin]++;
      if (holding) blocked[bin]++;
    }

    // mirror _combat's own target choice, then its throw gate
    const target = a.hasTarget || a.lastKnownAge < 5 ? a.lastKnown : null;
    if (!target) continue;
    const dist = a.position.distanceTo(target);
    if (holding && dist > 8 && dist < 26 && a.lastKnownAge < 1.5) {
      throwWindow[bin]++;
      if (sq && sq.grenadeCooldown > 0) rationedOut[bin]++;
    }
  }
};

play(engine, rec, { frames: sec(10 * BINS), onFrame });

const row = (label, arr) => console.info(label.padEnd(28), arr.join(' ').padEnd(24), '| total', arr.reduce((a, b) => a + b, 0));
console.info(`--- per ${BINS} x 10 s window ---`);
row('flank entries', flankEntries);
row('flank-eligible frames', eligible);
row('  ... blocked by grenade', blocked);
row('holding-ready-grenade frames', holdingFrames);
row('throw-window frames', throwWindow);
row('  ... refused by squad ration', rationedOut);
row('grenades actually thrown', throwsPerBin);
console.info('total throws:', throws);
console.info(
  'grenadeCooldown / hasGrenade at the end:',
  ai.agents.filter((a) => a.alive).map((a) => `${a.id}:${a.grenadeCooldown.toFixed(1)}/${a.hasGrenade}`).join(' '),
);
engine.dispose();

