/**
 * THROWAWAY: "the enemies just stand there" — measured rather than argued.
 *
 * Per man over a 60 s firefight: where his time goes by state, how much of it
 * he spends motionless, and the single longest stretch he holds still. The last
 * number is the one the player actually perceives. Delete when done.
 */
import { boot } from './harness.mjs';
import { play, engagePlay } from './play.mjs';

const FPS = 60;
const sec = (s) => Math.round(s * FPS);
const RUN = sec(60);

const { engine, rec } = await boot({ quality: 'low', deterministic: true, width: 960, height: 600, dpr: 1 });
engagePlay(engine, { populate: true });
const ai = engine.ctx.peek('ai');

const stats = new Map();
const get = (a) => {
  let s = stats.get(a.id);
  if (!s) stats.set(a.id, (s = { states: {}, still: 0, streak: 0, longest: 0, frames: 0, longestState: '' }));
  return s;
};

play(engine, rec, {
  frames: RUN,
  onFrame: () => {
    for (const a of ai.agents) {
      if (!a.alive) continue;
      const s = get(a);
      s.frames++;
      s.states[a.state] = (s.states[a.state] ?? 0) + 1;
      if (a.speed < 0.2) {
        s.still++;
        s.streak++;
        if (s.streak > s.longest) {
          s.longest = s.streak;
          s.longestState = a.state;
        }
      } else s.streak = 0;
    }
  },
});

console.info('--- 60 s, per man ---');
for (const [id, s] of stats) {
  const mix = Object.entries(s.states)
    .sort((a, b) => b[1] - a[1])
    .map(([k, v]) => `${k} ${Math.round((v / s.frames) * 100)}%`)
    .join('  ');
  console.info(
    `agent ${id}`.padEnd(9),
    `still ${String(Math.round((s.still / s.frames) * 100)).padStart(3)}%`,
    `longest ${(s.longest / FPS).toFixed(1).padStart(5)} s in ${s.longestState.padEnd(10)}`,
    mix,
  );
}
const all = [...stats.values()];
console.info(
  'worst single stand-still:', (Math.max(...all.map((s) => s.longest)) / FPS).toFixed(1), 's',
  '| mean still:', Math.round((all.reduce((n, s) => n + s.still / s.frames, 0) / all.length) * 100) + '%',
);
engine.dispose();

