rawInput.content:
/**
 * THROWAWAY: WHY a man stands still, not just how long.
 *
 * `_probe-idle.mjs` says agent 6 held one spot for 43 s. This one records, for
 * every still-streak, what the agent's cover machinery was doing while it ran:
 * did it ask the CoverMap at all, what did the map answer, was it peeking, was
 * the path budget or a failed path holding it. Delete when the answer is in a
 * gate.
 */
import { boot } from './harness.mjs';
import { play, engagePlay } from './play.mjs';

const FPS = 60;
const sec = (s) => Math.round(s * FPS);
const RUN = sec(60);

const { engine, rec } = await boot({ quality: 'low', deterministic: true, width: 960, height: 600, dpr: 1 });
engagePlay(engine, { populate: true });
const ai = engine.ctx.peek('ai');

/** picks made this frame, by agent id: 'null' | 'same' | 'new' */
const picks = new Map();
const cover = ai.cover;
const realPick = cover.pick.bind(cover);
cover.pick = (pos, threat, opts = {}) => {
  const r = realPick(pos, threat, opts);
  const a = ai.agents.find((x) => x.id === opts.id);
  picks.set(opts.id, !r ? 'null' : r === a?.cover ? 'same' : 'new');
  return r;
};

const blank = () => ({
  frames: 0, atCover: 0, noCover: 0, peeking: 0, shuffling: 0, wantMove: 0,
  pickNull: 0, pickSame: 0, pickNew: 0, pathFail: 0, pending: 0,
  coverKeys: new Set(), states: {}, holdMax: 0, first: null,
});
const stats = new Map();
const get = (a) => {
  let s = stats.get(a.id);
  if (!s) stats.set(a.id, (s = { still: 0, frames: 0, cur: blank(), best: blank(), streak: 0, longest: 0 }));
  return s;
};

play(engine, rec, {
  frames: RUN,
  onFrame: (i) => {
    for (const a of ai.agents) {
      if (!a.alive) continue;
      const s = get(a);
      s.frames++;
      if (a.speed >= 0.2) {
        if (s.streak > s.longest) { s.longest = s.streak; s.best = s.cur; }
        s.streak = 0;
        s.cur = blank();
        picks.delete(a.id);
        continue;
      }
      s.still++;
      s.streak++;
      const c = s.cur;
      if (c.first === null) c.first = i;
      c.frames++;
      c.states[a.state] = (c.states[a.state] ?? 0) + 1;
      if (a.cover) {
        c.atCover += a.position.distanceTo(a.coverPos) < 0.85 ? 1 : 0;
        c.coverKeys.add(`${a.cover.x.toFixed(1)},${a.cover.z.toFixed(1)}`);
      } else c.noCover++;
      c.holdMax = Math.max(c.holdMax, a.coverHold);
      if (a.peeking) c.peeking++;
      if (a.cover && a.position.distanceTo(a.stancePos) > 0.12) c.shuffling++;
      if (a.hasMoveTarget) c.wantMove++;
      if (a.pathFailTimer > 0) c.pathFail++;
      if (a.pathPending) c.pending++;
      const p = picks.get(a.id);
      if (p === 'null') c.pickNull++;
      else if (p === 'same') c.pickSame++;
      else if (p === 'new') c.pickNew++;
      picks.delete(a.id);
    }
  },
});

console.info('--- longest still-streak per man, and what held him there ---');
for (const [id, s] of stats) {
  if (s.streak > s.longest) { s.longest = s.streak; s.best = s.cur; }
  const b = s.best;
  const mix = Object.entries(b.states).sort((x, y) => y[1] - x[1]).map(([k, v]) => `${k} ${v}f`).join(' ');
  console.info(
    `agent ${id}`.padEnd(9),
    `still ${String(Math.round((s.still / s.frames) * 100)).padStart(3)}%`,
    `longest ${(s.longest / FPS).toFixed(1).padStart(5)} s @f${b.first}`,
    `| atCover ${b.atCover} noCover ${b.noCover} spots ${b.coverKeys.size}`,
    `| holdMax ${b.holdMax.toFixed(1)}s`,
    `| picks null/same/new ${b.pickNull}/${b.pickSame}/${b.pickNew}`,
    `| peek ${b.peeking}f shuffle ${b.shuffling}f wantMove ${b.wantMove}f`,
    `| pathFail ${b.pathFail}f pending ${b.pending}f`,
    `| ${mix}`,
  );
}
const all = [...stats.values()];
console.info(
  'worst single stand-still:', (Math.max(...all.map((s) => s.longest)) / FPS).toFixed(1), 's',
  '| mean still:', Math.round((all.reduce((n, s) => n + s.still / s.frames, 0) / all.length) * 100) + '%',
);
engine.dispose();

/**
 * THROWAWAY: why CoverMap.pick returns null for the man who never moves.
 *
 * Re-runs pick()'s own filter chain over all 1349 points and counts which
 * `continue` each point died on, for the agent that is coverless right now.
 * Delete once the behaviour is fixed and gated.
 */
import { boot } from './harness.mjs';
import { play, engagePlay } from './play.mjs';

const FPS = 60;
const RUN = 60 * FPS;

const { engine, rec } = await boot({ quality: 'low', deterministic: true, width: 960, height: 600, dpr: 1 });
engagePlay(engine, { populate: true });
const ai = engine.ctx.peek('ai');
const cover = ai.cover;

function why(a, pos, threat, opts) {
  const wantMax = opts.maxTravel ?? 22;
  const region = opts.region ?? -1;
  const r = { total: cover.points.length, region: 0, claimed: 0, dT: 0, travel: 0, prot: 0, ok: 0 };
  let minTravel = Infinity, minTravelOk = Infinity;
  for (const p of cover.points) {
    if (region >= 0 && p.region !== region) { r.region++; continue; }
    if (p.claimed >= 0 && p.claimed !== opts.id) { r.claimed++; continue; }
    const tx = threat.x - p.x, tz = threat.z - p.z;
    const dT = Math.hypot(tx, tz);
    const travel = Math.hypot(p.x - pos.x, p.z - pos.z);
    minTravel = Math.min(minTravel, travel);
    if (dT < 2.5 || dT > 40) { r.dT++; continue; }
    if (travel > wantMax) { r.travel++; continue; }
    const prot = (tx / dT) * p.dx + (tz / dT) * p.dz;
    if (prot < 0.25) { r.prot++; continue; }
    r.ok++;
    minTravelOk = Math.min(minTravelOk, travel);
  }
  r.minTravel = minTravel;
  r.minTravelOk = minTravelOk;
  r.myRegion = region;
  r.distToThreat = pos.distanceTo(threat);
  return r;
}

const seen = new Map();
const realPick = cover.pick.bind(cover);
let frame = 0;
cover.pick = (pos, threat, opts = {}) => {
  const r = realPick(pos, threat, opts);
  if (!r) {
    const n = (seen.get(opts.id) ?? 0) + 1;
    seen.set(opts.id, n);
    if (n === 1 || n % 900 === 0) {
      const a = ai.agents.find((x) => x.id === opts.id);
      const d = why(a, pos, threat, opts);
      console.info(
        `f${frame} agent ${opts.id} nullpick#${n} region=${d.myRegion} distToThreat=${d.distToThreat.toFixed(1)}`,
        `| of ${d.total}: wrongRegion ${d.region}, claimed ${d.claimed}, badRange ${d.dT}, tooFar ${d.travel}, noProt ${d.prot}, OK ${d.ok}`,
        `| nearest point ${d.minTravel.toFixed(1)}m, nearest usable ${Number.isFinite(d.minTravelOk) ? d.minTravelOk.toFixed(1) + 'm' : '-'}`,
      );
    }
  }
  return r;
};

play(engine, rec, { frames: RUN, onFrame: (i) => { frame = i; } });
console.info('--- null picks by agent ---', [...seen].map(([id, n]) => `${id}:${n}`).join(' '));
// how many agents ended without cover, and how far the nearest region point is
for (const a of ai.agents) {
  if (!a.alive) continue;
  console.info(`agent ${a.id} state=${a.state} cover=${a.cover ? 'yes' : 'NO'} region=${a.navRegion} pos=${a.position.x.toFixed(1)},${a.position.z.toFixed(1)}`);
}
engine.dispose();

