/**
 * THROWAWAY: how big is the island a man is standing on?
 *
 * `regionAt` labels an agent with the component of the nearest walkable cell.
 * If that cell is a marooned 1-cell island, every region-filtered query the
 * agent makes — cover, flank goal, retreat goal — can only answer "nothing".
 * This prints the size of each agent's component and how far the main network
 * is. Delete once the fix is gated.
 */
import { boot } from './harness.mjs';
import { play, engagePlay } from './play.mjs';

const FPS = 60;
const { engine, rec } = await boot({ quality: 'low', deterministic: true, width: 960, height: 600, dpr: 1 });
engagePlay(engine, { populate: true });
const ai = engine.ctx.peek('ai');
const g = ai.grid;

console.info(`grid ${g.nx}x${g.nz} · walkable ${g.walkableCount} · regions ${g.regionSize.length} · main ${g.mainRegion} (${g.regionSize[g.mainRegion]} cells)`);
const hist = {};
for (const n of g.regionSize) {
  const b = n === 1 ? '1' : n < 10 ? '2-9' : n < 100 ? '10-99' : n < 1000 ? '100-999' : '1000+';
  hist[b] = (hist[b] ?? 0) + 1;
}
console.info('region sizes:', JSON.stringify(hist));

// cover points per region
const perRegion = new Map();
for (const p of ai.cover.points) perRegion.set(p.region, (perRegion.get(p.region) ?? 0) + 1);
console.info('regions holding cover points:', perRegion.size, '· biggest:',
  [...perRegion].sort((a, b) => b[1] - a[1]).slice(0, 5).map(([r, n]) => `${r}:${n}`).join(' '));

function report(tag) {
  for (const a of ai.agents) {
    if (!a.alive) continue;
    const size = a.navRegion >= 0 ? g.regionSize[a.navRegion] : -1;
    const covers = perRegion.get(a.navRegion) ?? 0;
    // nearest cell of the main region, in cells
    let best = Infinity;
    const cx = g.cellX(a.position.x), cz = g.cellZ(a.position.z);
    for (let dz = -12; dz <= 12; dz++) {
      for (let dx = -12; dx <= 12; dx++) {
        const ix = cx + dx, iz = cz + dz;
        if (!g.walkable(ix, iz)) continue;
        const i = g.index(ix, iz);
        if (g.region[i] !== g.mainRegion) continue;
        best = Math.min(best, Math.hypot(dx, dz));
      }
    }
    console.info(
      `${tag} agent ${a.id}`.padEnd(18),
      `pos ${a.position.x.toFixed(1)},${a.position.y.toFixed(2)},${a.position.z.toFixed(1)}`,
      `region ${String(a.navRegion).padStart(4)} size ${String(size).padStart(6)} coverPts ${String(covers).padStart(4)}`,
      `mainRegionCellsAway ${Number.isFinite(best) ? best.toFixed(1) : '>12'}`,
      `state ${a.state}`,
    );
  }
}

report('spawn');
play(engine, rec, { frames: 20 * FPS });
report('20s');
engine.dispose();

