326	  findPath(from, to, out, opts = {}) {
327	    let start = this.nearest(from.x, from.z, from.y);
328	    const goal = this.nearest(to.x, to.z, to.y);
329	    if (start < 0 || goal < 0) return 0;
330	    // Different components: no route exists, and proving that the long way costs
331	    // a full 6000-node flood every time it is asked. An agent standing one cell
332	    // onto a kerb or a doorstep is the common false negative, so re-anchor the
333	    // START inside the goal's component before giving up — the DESTINATION is
334	    // the caller's to choose and is never quietly moved.
335	    if (this.region[start] !== this.region[goal]) {
336	      start = this.nearest(from.x, from.z, from.y, 3, Infinity, this.region[goal]);
337	      if (start < 0) return 0;
338	    }
339	    if (start === goal) {
340	      this._emit(out, 0, to);
341	      return 1;
342	    }
343	    const nx = this.nx;
344	    const gx = goal % nx, gz = (goal / nx) | 0;
345	    const cell = this.cell;
346	    const maxNodes = opts.maxNodes ?? 6000;
