348	    this.stamp++;
349	    const stamp = this.stamp;
350	    this.open.clear();
351	    this.gScore[start] = 0;
352	    this.came[start] = -1;
353	    this.visitStamp[start] = stamp;
354	    this.open.push(start, 0);
355	
356	    let expanded = 0;
357	    let found = false;
358	    while (this.open.n > 0 && expanded < maxNodes) {
359	      const cur = this.open.pop();
360	      if (cur === goal) {
361	        found = true;
362	        break;
363	      }
364	      expanded++;
365	      const cxi = cur % nx, czi = (cur / nx) | 0;
366	      const cg = this.gScore[cur];
367	      const cy = this.floor[cur];
368	      for (let d = 0; d < 8; d++) {
369	        const dx = DX[d], dz = DZ[d];
370	        const ix = cxi + dx, iz = czi + dz;
371	        if (!this.walkable(ix, iz)) continue;
372	        if (dx && dz) {
373	          // no corner cutting
374	          if (!this.walkable(cxi + dx, czi) || !this.walkable(cxi, czi + dz)) continue;
375	        }
376	        const ni = this.index(ix, iz);
377	        const dy = this.floor[ni] - cy;
378	        if (Math.abs(dy) > this.maxStep) continue;
