/**
 * THROWAWAY: the one manoeuvre in the ai-flank gate that finds no route.
 *
 * Rebuilds the gate's hook, and on every dead end prints who, where, which
 * branch asked (a real flank swing or the no-cover bound), and what the grid
 * said about the start and goal cells. Delete once the gate is green.
 */
import { boot } from './harness.mjs';
import { play, engagePlay } from './play.mjs';

const FPS = 60;
const RUN = 40 * FPS;

const { engine, rec } = await boot({ quality: 'low', deterministic: true, width: 960, height: 600, dpr: 1 });
engagePlay(engine, { populate: true });
const ai = engine.ctx.peek('ai');
const g = ai.grid;

let frame = 0;
let attempts = 0, deadEnds = 0, deferred = 0;

// which branch of _combat is asking: the flank swing sets `reach` from the dice
// (8-15), the no-cover bound always passes exactly 7
for (const a of ai.agents) {
  const point = a._flankPoint.bind(a);
  a._flankPoint = (target, side, reach) => {
    a.__flanking = true;
    a.__reach = reach;
    return point(target, side, reach);
  };
  const goTo = a._goTo.bind(a);
  a._goTo = (dest) => {
    const mine = a.__flanking;
    a.__flanking = false;
    const ok = goTo(dest);
    if (mine) {
      attempts++;
      if (!ok) {
        if (a.pathPending) deferred++;
        else {
          deadEnds++;
          const si = g.nearest(a.position.x, a.position.z, a.position.y);
          const gi = g.nearest(dest.x, dest.z, dest.y);
          const sr = si >= 0 ? g.region[si] : -1;
          const gr = gi >= 0 ? g.region[gi] : -1;
          const reanchor = sr !== gr ? g.nearest(a.position.x, a.position.z, a.position.y, 3, Infinity, gr) : si;
          console.info(
            `f${frame} DEADEND agent ${a.id} branch=${a.__reach === 7 ? 'bound' : 'swing'} reach=${a.__reach}`,
            `state=${a.state} navRegion=${a.navRegion} (size ${g.regionSize[a.navRegion] ?? '-'})`,
            `| pos ${a.position.x.toFixed(1)},${a.position.y.toFixed(2)},${a.position.z.toFixed(1)} startCellRegion=${sr}`,
            `| dest ${dest.x.toFixed(1)},${dest.y.toFixed(2)},${dest.z.toFixed(1)} goalCellRegion=${gr} (size ${g.regionSize[gr] ?? '-'})`,
            `| reanchoredStart=${reanchor >= 0 ? 'yes' : 'NO'} travel=${a.position.distanceTo(dest).toFixed(1)}m`,
          );
        }
      }
    }
    return ok;
  };
}

play(engine, rec, {
  frames: RUN,
  onFrame: (i) => {
    frame = i;
    for (const a of ai.agents) a.__flanking = false;
  },
});
console.info(`attempts ${attempts} deadEnds ${deadEnds} deferred ${deferred}`);
engine.dispose();

