/**
 * THROWAWAY: every _goTo that comes back "no route", with the reason.
 *
 * Hooks all agents (not just the flank branch) and, on each failure, reports
 * where he stands, where he was sent, what the grid says about both cells, and
 * whether a bigger node budget would have found the route. Delete once the
 * behaviour is gated.
 */
import { boot } from './harness.mjs';
import { play, engagePlay } from './play.mjs';

const FPS = 60;
const RUN = 60 * FPS;

const { engine, rec } = await boot({ quality: 'low', deterministic: true, width: 960, height: 600, dpr: 1 });
engagePlay(engine, { populate: true });
const ai = engine.ctx.peek('ai');
const g = ai.grid;

let frame = 0;
const fails = new Map();
const out = [];

for (const a of ai.agents) {
  const goTo = a._goTo.bind(a);
  a._goTo = (dest) => {
    const ok = goTo(dest);
    if (!ok && !a.pathPending) {
      const n = (fails.get(a.id) ?? 0) + 1;
      fails.set(a.id, n);
      if (n <= 3 || n % 10 === 0) {
        const si = g.nearest(a.position.x, a.position.z, a.position.y);
        const gi = g.nearest(dest.x, dest.z, dest.y);
        const sr = si >= 0 ? g.region[si] : -1;
        const gr = gi >= 0 ? g.region[gi] : -1;
        const anchored = sr !== gr ? g.nearest(a.position.x, a.position.z, a.position.y, 3, Infinity, gr) : si;
        let big = 0;
        for (const cap of [12000, 40000]) {
          big = g.findPath(a.position, dest, out, { maxNodes: cap });
          if (big > 0) { big = `${big}@${cap}`; break; }
        }
        console.info(
          `f${String(frame).padStart(4)} NOROUTE agent ${a.id} #${n} state=${a.state} navRegion=${a.navRegion}`,
          `| pos ${a.position.x.toFixed(1)},${a.position.y.toFixed(2)},${a.position.z.toFixed(1)} cellRegion=${sr} (size ${g.regionSize[sr] ?? '-'})`,
          `| dest ${dest.x.toFixed(1)},${dest.y.toFixed(2)},${dest.z.toFixed(1)} cellRegion=${gr} (size ${g.regionSize[gr] ?? '-'})`,
          `| straight=${a.position.distanceTo(dest).toFixed(1)}m anchored=${anchored >= 0 ? 'yes' : 'NO'} biggerBudget=${big || 'still 0'}`,
        );
      }
    }
    return ok;
  };
}

play(engine, rec, { frames: RUN, onFrame: (i) => { frame = i; } });
console.info('--- no-route failures by agent ---', [...fails].map(([id, n]) => `${id}:${n}`).join(' ') || 'none');
engine.dispose();

