/**
 * THROWAWAY: what the partial paths actually buy.
 *
 * A partial path that ends half a metre from where the man already stands is
 * not a walk, it is a re-solve treadmill: `_goTo` reports success, `_move`
 * arrives inside `arriveEps` on the next frame, `_combat` reads "has cover, not
 * standing in it" and hands the point back. This measures the distribution.
 * Delete once the behaviour is gated.
 */
import { boot } from './harness.mjs';
import { play, engagePlay } from './play.mjs';

const FPS = 60;
const RUN = 60 * FPS;

const { engine, rec } = await boot({ quality: 'low', deterministic: true, width: 960, height: 600, dpr: 1 });
engagePlay(engine, { populate: true });
const ai = engine.ctx.peek('ai');
const g = ai.grid;

let solves = 0, partial = 0, failed = 0;
const gains = [];
const fp = g.findPath.bind(g);
g.findPath = (from, to, out, opts) => {
  const n = fp(from, to, out, opts);
  solves++;
  if (n === 0) { failed++; return n; }
  const end = out[n - 1];
  // reached the goal, or stopped short of it?
  if (end.distanceTo(to) > g.cell) {
    partial++;
    gains.push(+(from.distanceTo(to) - end.distanceTo(to)).toFixed(2));
  }
  return n;
};

play(engine, rec, { frames: RUN, onFrame: () => {} });
gains.sort((a, b) => a - b);
const q = (p) => (gains.length ? gains[Math.min(gains.length - 1, Math.floor(gains.length * p))] : 0);
console.info(`solves ${solves} · reachedGoal ${solves - partial - failed} · partial ${partial} · noRoute ${failed}`);
console.info(`partial gain toward the goal (m): min ${gains[0] ?? '-'} p25 ${q(0.25)} median ${q(0.5)} p75 ${q(0.75)} max ${gains[gains.length - 1] ?? '-'}`);
console.info(`partials under 1 m of gain: ${gains.filter((x) => x < 1).length} · under 2 m: ${gains.filter((x) => x < 2).length}`);
engine.dispose();

