1	/**
2	 * playtests — the gameplay scenarios `cod play` runs.
3	 *
4	 * Each scenario boots the real engine, plays a scripted input timeline through
5	 * the real Input handlers and returns `{ name, pass, ... }` with the evidence
6	 * that decided it. A scenario never prints; the command formats.
7	 *
8	 * These are assertions about FEEL, not about pixels: a crouch that reports the
9	 * stance but stops the player moving is a failure here even though every frame
10	 * still renders. That is exactly the class of bug this file exists to catch.
11	 */
12	
13	import { boot } from './harness.mjs';
14	import { play, engagePlay, BROWSER_SHORTCUTS, makeDriver, travelled } from './play.mjs';
15	import { ACTIONS } from '../../src/core/input.js';
16	
17	const FPS = 60;
18	const sec = (s) => Math.round(s * FPS);
19	
20	/** Hold `codes` from frame `from` to frame `to`. */
21	function hold(codes, from, to) {
22	  const t = {};
23	  for (const c of [].concat(codes)) {
24	    t[from] = t[from] ?? [];
25	    t[to] = t[to] ?? [];
26	  }
27	  return { codes: [].concat(codes), from, to };
28	}
29	
30	/** Build a timeline function from a list of hold() specs. */
31	function timelineOf(holds) {
32	  return (drv, engine, i) => {
33	    for (const h of holds) {
34	      if (i === h.from) for (const c of h.codes) drv.down(c);
35	      if (i === h.to) for (const c of h.codes) drv.up(c);
36	    }
37	  };
38	}
39	
40	async function bootPlay(opts = {}) {
41	  const { engine, rec } = await boot({ quality: 'low', deterministic: true, width: 960, height: 600, dpr: 1 });
42	  engagePlay(engine, opts);
43	  return { engine, rec };
44	}
45	
46	/* ====================================================================== */
47	/* 1. crouch                                                              */
48	/* ====================================================================== */
49	
50	/**
51	 * Ducking has to work while you are moving, on both bound keys, and it has to
52	 * let go again. The interesting half is Ctrl: it is a browser modifier, so a
53	 * crouch-and-strafe sends `ctrlKey: true` on the D keydown.
54	 */
55	export async function scenarioCrouch() {
56	  const { engine, rec } = await bootPlay();
57	  const holds = [
58	    hold('KeyW', sec(0.2), sec(6.0)),        // walk the whole time
59	    hold('ControlLeft', sec(1.0), sec(2.5)), // hold-crouch
60	    hold('KeyD', sec(1.4), sec(2.2)),        // strafe WHILE crouched (Ctrl+D = bookmark)
61	    hold('KeyC', sec(3.5), sec(3.6)),        // tap-toggle crouch on
62	    hold('KeyC', sec(5.0), sec(5.1)),        // tap-toggle crouch off
63	  ];
64	  const { samples, keyLog } = play(engine, rec, { frames: sec(6.5), timeline: timelineOf(holds) });
65	
66	  const win = (a, b) => samples.slice(sec(a), sec(b));
67	  const crouchedWhileHeld = win(1.3, 2.4).filter((s) => s.stance === 'crouch').length;
68	  const heldWindow = win(1.3, 2.4).length;
69	  const standAfterRelease = win(3.0, 3.4).every((s) => s.stance === 'stand');
70	  const toggledOn = win(4.0, 4.8).filter((s) => s.stance === 'crouch').length;
71	  const toggledOff = win(5.6, 6.4).every((s) => s.stance === 'stand');
72	
73	  // Did the player keep moving while crouched with Ctrl held?
74	  const a = samples[sec(1.5)];
75	  const b = samples[sec(2.2)];
76	  const movedWhileCrouched = +Math.hypot(b.x - a.x, b.z - a.z).toFixed(3);
77	
78	  const dKeys = keyLog.filter((k) => k.code === 'KeyD');
79	  const ctrlDLost = dKeys.filter((k) => k.ctrl && !k.registered).length;
80	  const ctrlDUnprevented = dKeys.filter((k) => k.ctrl && !k.prevented).length;
81	
82	  const pass =
83	    crouchedWhileHeld > heldWindow * 0.8 &&
84	    standAfterRelease &&
85	    toggledOn > 20 &&
86	    toggledOff &&
87	    movedWhileCrouched > 0.6 &&
88	    ctrlDLost === 0 &&
89	    ctrlDUnprevented === 0;
90	
91	  engine.dispose();
92	  return {
93	    name: 'crouch', pass,
94	    holdCrouchFrames: `${crouchedWhileHeld}/${heldWindow}`,
95	    standsUpOnRelease: standAfterRelease,
96	    tapToggleOnFrames: toggledOn,
97	    tapToggleOffClean: toggledOff,
98	    movedWhileCrouchedM: movedWhileCrouched,
99	    ctrlDKeysLost: ctrlDLost,
100	    ctrlDBrowserDefaultsNotPrevented: ctrlDUnprevented,
101	    eyeHeights: [samples[sec(0.9)].eye, samples[sec(2.0)].eye, samples[sec(3.2)].eye],
102	  };
103	}
104	
105	/* ====================================================================== */
106	/* 2. strafe                                                              */
107	/* ====================================================================== */
108	
109	export async function scenarioStrafe() {
110	  const { engine, rec } = await bootPlay();
111	  const holds = [
112	    hold('KeyD', sec(0.2), sec(2.0)),
113	    hold('KeyA', sec(2.4), sec(4.2)),
114	    hold(['ShiftLeft', 'KeyW', 'KeyD'], sec(4.6), sec(6.4)),
115	  ];
116	  const { samples } = play(engine, rec, { frames: sec(7.0), timeline: timelineOf(holds) });
117	
118	  const p = engine.ctx.peek('player');
119	  const yaw = p.movement.yaw;
120	  const rightX = Math.cos(yaw);
121	  const rightZ = -Math.sin(yaw);
122	  const disp = (a, b) => {
123	    const s0 = samples[sec(a)];
124	    const s1 = samples[sec(b)];
125	    return {
126	      right: +((s1.x - s0.x) * rightX + (s1.z - s0.z) * rightZ).toFixed(2),
127	      dist: +Math.hypot(s1.x - s0.x, s1.z - s0.z).toFixed(2),
128	    };
129	  };
130	  const rightLeg = disp(0.4, 1.9);
131	  const leftLeg = disp(2.6, 4.1);
132	  const peakStrafeSpeed = Math.max(...samples.slice(sec(0.6), sec(1.9)).map((s) => s.speed));
133	  const diagonal = disp(4.8, 6.3);
134	
135	  const pass =
136	    rightLeg.right > 3.5 &&
137	    leftLeg.right < -3.5 &&
138	    peakStrafeSpeed > 3.6 &&
139	    diagonal.dist > 6;
140	
141	  engine.dispose();
142	  return {
143	    name: 'strafe', pass,
144	    strafeRightM: rightLeg.right, strafeLeftM: leftLeg.right,
145	    peakStrafeSpeed: +peakStrafeSpeed.toFixed(2),
146	    sprintDiagonalM: diagonal.dist,
147	  };
148	}
