223	/* ====================================================================== */
224	/* 4. death at 0 HP                                                       */
225	/* ====================================================================== */
226	
227	export async function scenarioDeath() {
228	  const { engine, rec } = await bootPlay();
229	  const player = engine.ctx.peek('player');
230	  const deaths = [];
231	  engine.events.on('player:death', (e) => deaths.push({ frame: engine.time.frame, e }));
232	
233	  let healthAtDeath = null;
234	  const holds = [hold(['KeyW', 'ShiftLeft'], sec(0.2), sec(9.0))];
235	  const script = timelineOf(holds);
236	  const timeline = (drv, eng, i) => {
237	    script(drv, eng, i);
238	    // four hits: 30 / 30 / 30 / 30 -> the fourth crosses zero
239	    if (i === sec(1.0) || i === sec(1.4) || i === sec(1.8) || i === sec(2.2)) {
240	      player.applyDamage(30, null, { type: 'bullet' });
241	    }
242	  };
243	  const { samples } = play(engine, rec, { frames: sec(9.0), timeline });
244	
245	  const deathIdx = samples.findIndex((s) => s.dead);
246	  if (deathIdx >= 0) healthAtDeath = samples[deathIdx].health;
247	  // The window between the kill and the automatic redeploy. Everything about
248	  // "the round ended" has to hold across ALL of it.
249	  const downed = deathIdx >= 0 ? samples.slice(deathIdx + 2, deathIdx + sec(4.5)) : [];
250	  const stayedDead = downed.length > 0 && downed.every((s) => s.dead);
251	  const controlOff = downed.length > 0 && downed.every((s) => !s.control);
252	  const noRegen = downed.every((s) => s.health <= 0.01);
253	  // Both the reported speed AND the actual displacement: a stale speed reading
254	  // and a body that is still sliding forward are different bugs.
255	  const settle = downed.slice(20);
256	  const drift = settle.length
257	    ? Math.hypot(
258	      settle[settle.length - 1].x - settle[0].x,
259	      settle[settle.length - 1].z - settle[0].z,
260	    )
261	    : Infinity;
262	  const stopped = downed.length > 20 && settle.every((s) => s.speed < 0.35) && drift < 0.1;
263	  // …and then the player is put back in the fight, whole.
264	  const revivedIdx = deathIdx >= 0 ? samples.findIndex((s, i) => i > deathIdx && !s.dead) : -1;
265	  const revivedAfter = revivedIdx > 0 ? +((revivedIdx - deathIdx) / FPS).toFixed(2) : null;
266	  const revivedClean = revivedIdx > 0 &&
267	    samples.slice(revivedIdx + 4).every((s) => s.control && s.health > 99);
268	
269	  const pass =
270	    deathIdx > 0 && deaths.length === 1 && healthAtDeath === 0 &&
271	    stayedDead && controlOff && noRegen && stopped && revivedClean;
272	
273	  engine.dispose();
274	  return {
275	    name: 'death', pass,
276	    deathFrame: deathIdx, deathEvents: deaths.length, healthAtDeath,
277	    stayedDead, controlDisabled: controlOff, regenBlocked: noRegen, movementStopped: stopped,
278	    redeployedAfterS: revivedAfter, redeployRestoredControlAndHealth: revivedClean,
279	  };
280	}
