333	/* ====================================================================== */
334	/* 6. enemies                                                             */
335	/* ====================================================================== */
336	
337	export async function scenarioAi(frames = sec(20)) {
338	  const { engine, rec } = await bootPlay({ populate: true });
339	  const ai = engine.ctx.peek('ai');
340	  const spawned = ai?.agents.length ?? 0;
341	
342	  const { aiSamples } = play(engine, rec, { frames, trackAi: true });
343	  const ids = spawned ? ai.agents.map((a) => a.id) : [];
344	  const dist = ids.map((id) => travelled(aiSamples, id));
345	  const moved = dist.filter((d) => d > 2.0).length;
346	  const last = aiSamples[aiSamples.length - 1] ?? [];
347	  const states = {};
348	  for (const a of last) states[a.state] = (states[a.state] ?? 0) + 1;
349	  const anyRun = aiSamples.some((f) => f.some((a) => a.speed > 1.0));
350	
351	  const pass = spawned >= 4 && moved >= Math.ceil(spawned * 0.6) && anyRun;
352	
353	  engine.dispose();
354	  return {
355	    name: 'ai-movement', pass,
356	    spawned, agentsThatMoved: moved,
357	    travelledM: dist,
358	    reachedWalkSpeed: anyRun,
359	    finalStates: states,
360	  };
361	}
362	
363	/* ====================================================================== */
364	/* 7. enemy death                                                         */
365	/* ====================================================================== */
366	
367	export async function scenarioAiDeath() {
368	  const { engine, rec } = await bootPlay({ populate: true });
369	  const ai = engine.ctx.peek('ai');
370	  if (!ai?.agents.length) {
371	    engine.dispose();
372	    return { name: 'ai-death', pass: false, reason: 'no enemies spawned' };
373	  }
374	  const victim = ai.agents[0];
375	  const startY = victim.position.y;
376	  const deaths = [];
377	  engine.events.on('actor:death', (e) => deaths.push(engine.time.frame));
378	
379	  const timeline = (drv, eng, i) => {
380	    if (i === sec(1.0)) {
381	      const p = victim.position;
382	      victim.applyDamage(500, 'torso', { x: p.x, y: p.y + 1.3, z: p.z }, { x: 0, y: 0, z: 1 });
383	    }
384	  };
385	  const { aiSamples } = play(engine, rec, { frames: sec(14), timeline, trackAi: true });
386	
387	  const rec0 = aiSamples.map((f) => f.find((a) => a.id === victim.id)).filter(Boolean);
388	  const diedAt = rec0.findIndex((a) => !a.alive);
389	  const fadeSeen = rec0.some((a) => a.opacity !== undefined && a.opacity < 0.99 && a.opacity > 0);
390	  const removed = rec0[rec0.length - 1] === undefined || !ai.agents.includes(victim);
391	  const ragdoll = !!victim.ragdoll;
392	  const fellY = ragdoll && victim.ragdoll.aabb
393	    ? +(startY + 1.7 - victim.ragdoll.aabb.maxy).toFixed(2)
394	    : null;
395	
396	  const pass = diedAt > 0 && deaths.length === 1 && ragdoll && fadeSeen && removed;
397	
398	  engine.dispose();
399	  return {
400	    name: 'ai-death', pass,
401	    diedAtSample: diedAt, deathEvents: deaths.length,
402	    ragdollCreated: ragdoll, bodyDroppedM: fellY,
403	    fadeOutObserved: fadeSeen, corpseCleanedUp: removed,
404	    remainingAgents: ai.agents.length,
405	  };
406	}
407	
408	/* ====================================================================== */
409	/* 8. squad reaction to a casualty                                        */
410	/* ====================================================================== */
411	
412	/**
413	 * What a squad does when one of its own is killed. Before this existed the
414	 * answer was "nothing at all": MEASURED on this same garrison, agent 1 was shot
415	 * dead 1.1 m from agent 3, and agents 2 and 3 kept walking their patrol route
416	 * with `lastKnownAge` still at infinity four seconds later.
417	 *
418	 * Four claims, one kill each:
419	 *   1. the men beside him react at all — alert, and suppressed by it
420	 *   2. the shot gives them a bearing to search, never the player's position
421	 *   3. they flinch: small, and not shooting, for a beat
422	 *   4. nobody keeps holding the cover his mate was just killed behind
423	 * plus 5. the last man of a gutted squad breaks contact instead of trading
424	 * shots alone with whoever just killed the other two, 6. the flinch reaches a
425	 * man who is not in a firefight — the patrol that loses its point man stops
426	 * walking — and 7. the bearing reaches his BODY: he turns to face it instead
427	 * of searching with his back to the shot.
428	 */
429	export async function scenarioSquad() {
430	  const { engine, rec } = await bootPlay({ populate: true });
431	  const ai = engine.ctx.peek('ai');
432	  const squads = (ai?.squads ?? []).filter((s) => s.members.length >= 3);
433	  if (squads.length < 2) {
434	    engine.dispose();
435	    return { name: 'ai-squad', pass: false, reason: 'need two three-man squads' };
436	  }
437	
438	  /** A killing hit from a known direction, so the back-trace has something to work with. */
439	  const kill = (a) => {
440	    const p = a.position;
441	    a.applyDamage(500, 'torso', { x: p.x, y: p.y + 1.3, z: p.z }, { x: 0, y: 0, z: 1 });
442	  };
443	  const snap = () =>
444	    ai.agents.map((a) => ({
445	      id: a.id, squad: a.squad, alive: a.alive, state: a.state,
446	      sup: a.suppression, flinch: a.manDownTimer, fire: a.wantFire,
447	      lka: a.lastKnownAge, cover: a.cover,
448	      cx: a.coverPos.x, cz: a.coverPos.z, x: a.position.x, z: a.position.z,
449	      yaw: a.yaw, speed: a.speed, lkx: a.lastKnown.x, lkz: a.lastKnown.z,
450	    }));
451	
452	  const KILL1 = sec(4.0);  // a man on patrol, his squad walking beside him
453	  const KILL2 = sec(6.0);  // a man of the squad that is already in cover
454	  const KILL3 = sec(8.0);  // the second of squad one: one man left of three
455	  const bodies = {};
456	  const victims = {};
457	
458	  const timeline = (drv, eng, i) => {
459	    if (i === KILL1) {
460	      const v = squads[0].members[0];
461	      victims[KILL1] = v; bodies[KILL1] = { x: v.position.x, z: v.position.z, squad: squads[0] };
462	      kill(v);
463	    }
464	    if (i === KILL2) {
465	      const v = squads[1].members[1];
466	      victims[KILL2] = v; bodies[KILL2] = { x: v.position.x, z: v.position.z, squad: squads[1] };
467	      kill(v);
468	    }
469	    if (i === KILL3) {
470	      const v = squads[0].members.find((m) => m.alive);
471	      if (v) { victims[KILL3] = v; bodies[KILL3] = { x: v.position.x, z: v.position.z, squad: squads[0] }; kill(v); }
472	    }
473	  };
474	
475	  const frames = [];
476	  play(engine, rec, { frames: sec(16), timeline, onFrame: () => frames.push(snap()) });
477	
478	  const dist = (a, bx, bz) => Math.hypot(a.x - bx, a.z - bz);
479	  const at = (f) => frames[f] ?? [];
480	  /**
481	   * The men of the dead man's squad who were close enough to know about it.
482	   * The victim is excluded explicitly: one frame before the kill he is alive,
483	   * 0 m from his own body and holding the very cover point in question.
484	   */
485	  const mates = (f, k) =>
486	    at(f).filter(
