502	  const bearingDelays = after1.map((a) => +a.lka.toFixed(2)).filter((v) => v > 0);
503	
504	  /* 3. the flinch, and no shooting during it — across every casualty */
505	  let flinchFrames = 0;
506	  let firedWhileFlinching = 0;
507	  for (const f of frames) {
508	    for (const a of f) {
509	      if (!a.alive || a.flinch <= 0) continue;
510	      flinchFrames++;
511	      if (a.fire) firedWhileFlinching++;
512	    }
513	  }
514	
515	  /* 4. cover held next to the body is given up for a point further from it */
516	  const holders = mates(KILL2 - 1, KILL2).filter((a) => a.cover && dist({ x: a.cx, z: a.cz }, bodies[KILL2].x, bodies[KILL2].z) < 5);
