523	  });
524	  const coverAbandoned = moved.filter((d) => d !== null).length;
525	
526	  /* 5. one man left of three: break contact */
527	  const lastMan = frames[frames.length - 1].find((a) => a.alive && a.squad === squads[0]);
528	  const brokeContact = lastMan
