582	    bearings === after1.length && bearingDelays.length === after1.length &&
583	    flinchFrames > 0 && firedWhileFlinching === 0 &&
584	    holders.length > 0 && coverAbandoned === holders.length &&
585	    brokeContact &&
586	    flinchStopped === after1.length &&
587	    turned === after1.length;
