589	  engine.dispose();
590	  return {
591	    name: 'ai-squad', pass,
592	    matesInEarshot: after1.length,
593	    obliviousBeforeKill: `${obliviousBefore}/${before1.length} patrolling, ${noBearingBefore} with no bearing`,
594	    alertedOnTheKill: `${alerted}/${after1.length}`,
595	    suppression: `${supBefore.toFixed(2)} -> ${supAfter.toFixed(2)}`,
596	    bearingsGiven: bearings,
597	    callOutDelaysS: bearingDelays,
598	    flinchFrames, shotsWantedWhileFlinching: firedWhileFlinching,
599	    coverNextToBody: `${coverAbandoned}/${holders.length} abandoned`,
