609	/* ====================================================================== */
610	/* 9. flanking                                                            */
611	/* ====================================================================== */
612	
613	/**
614	 * Do the enemies ever actually manoeuvre? "They just sit behind a wall" is the
615	 * single loudest complaint a shooter's AI can earn, and this garrison had two
616	 * independent reasons to earn it — both invisible from every other gate,
617	 * because a flank that never happens looks exactly like a firefight.
618	 *
619	 *   1. The destination was a raw geometric offset, "fifteen metres to my left",
620	 *      handed to A* without ever asking whether a man can stand there.
621	 *      MEASURED over 60 s: 11 of 14 manoeuvres died as a solve that returned no
622	 *      route, the dice already spent. `Agent._flankPoint` now snaps the point
623	 *      onto walkable ground in the agent's own nav component first.
624	 *   2. The gate refused to move anyone holding a grenade, on the theory that he
625	 *      would throw it instead — but the squad rations throws, so he mostly did
626	 *      not. MEASURED on that same run: 6637 of 11354 flank-eligible frames
627	 *      blocked, against 2139 of 2143 throw windows refused by the ration.
628	 *
629	 * The claims: the squad tries to flank, every try that gets past the dice finds
630	 * a route, the try becomes a real flank, and no man is barred from manoeuvring
631	 * for long by a grenade he is not going to get to throw.
632	 */
633	export async function scenarioFlank() {
634	  const { engine, rec } = await bootPlay({ populate: true });
635	  const ai = engine.ctx.peek('ai');
636	  if (!ai?.agents.length) {
637	    engine.dispose();
638	    return { name: 'ai-flank', pass: false, reason: 'no enemies spawned' };
639	  }
640	
641	  const RUN = sec(40);
642	  const BIN = sec(10);
643	  const bins = new Array(Math.ceil(RUN / BIN)).fill(0);
644	  let attempts = 0, deadEnds = 0, deferred = 0, entries = 0;
645	  let throws = 0;
646	  const barred = new Map();      // agent id -> frames blocked back to back
647	  let longestBarred = 0;
648	
649	  // A manoeuvre is one _flankPoint search followed by the _goTo it feeds. The
650	  // flag is per agent and cleared every frame, so a search that finds no ground
651	  // at all cannot be charged to somebody else's path request.
652	  for (const a of ai.agents) {
653	    const point = a._flankPoint.bind(a);
654	    a._flankPoint = (...args) => {
655	      a.__flanking = true;
656	      return point(...args);
657	    };
658	    const goTo = a._goTo.bind(a);
659	    a._goTo = (dest) => {
660	      const mine = a.__flanking;
661	      a.__flanking = false;
662	      const ok = goTo(dest);
663	      if (mine) {
664	        attempts++;
665	        // a deferred solve is the frame budget talking, not a bad destination
666	        if (!ok) a.pathPending ? deferred++ : deadEnds++;
667	      }
668	      return ok;
669	    };
670	  }
671	  const realThrow = ai.throwGrenade.bind(ai);
672	  ai.throwGrenade = (...args) => {
673	    throws++;
674	    return realThrow(...args);
675	  };
676	
677	  const prev = new Map();
678	  const onFrame = (i) => {
679	    const bin = Math.floor(i / BIN);
680	    for (const a of ai.agents) {
681	      a.__flanking = false;
682	      if (!a.alive) continue;
683	      if (a.state === 'flank' && prev.get(a.id) !== 'flank') {
684	        entries++;
685	        bins[bin]++;
686	      }
687	      prev.set(a.id, a.state);
688	
689	      // the exact term the flank gate tests, rebuilt from the outside
690	      const sq = a.squad;
691	      const target = a.hasTarget || a.lastKnownAge < 5 ? a.lastKnown : null;
692	      const d = target ? a.position.distanceTo(target) : 0;
693	      const blocked = !!sq && sq.grenadeCooldown <= 0 && a.hasGrenade && a.grenadeCooldown <= 0 &&
694	        !!target && d > 8 && d < 26 && a.lastKnownAge < 1.5;
695	      const streak = blocked ? (barred.get(a.id) ?? 0) + 1 : 0;
696	      barred.set(a.id, streak);
697	      if (streak > longestBarred) longestBarred = streak;
698	    }
699	  };
700	
701	  play(engine, rec, { frames: RUN, onFrame });
702	
703	  const barredS = +(longestBarred / FPS).toFixed(2);
704	  const pass = attempts >= 3 && deadEnds === 0 && entries >= 3 && barredS < 8;
705	
706	  engine.dispose();
707	  return {
708	    name: 'ai-flank', pass,
709	    flankAttempts: attempts,
710	    attemptsWithNoRoute: deadEnds,
711	    attemptsDeferredByBudget: deferred,
712	    flanksEntered: entries,
713	    entriesPer10s: bins,
714	    longestBarredByGrenadeS: barredS,
715	    grenadesThrown: throws,
716	  };
717	}
