720	/* 10. browser key conflicts                                              */
721	/* ====================================================================== */
722	
723	/**
724	 * For every browser shortcut we can collide with, press it the way a player
725	 * would and record two things: did the game get the key, and did anything stop
726	 * the browser acting on it. A key that is bound to gameplay and leaves
727	 * `defaultPrevented === false` is a page that bookmarks itself mid-firefight.
728	 */
729	export async function scenarioKeys() {
730	  const { engine, rec } = await bootPlay();
731	  const bound = new Set(Object.values(ACTIONS).flat());
732	  const drv = makeDriver(engine);
733	  engine.input.pointerLocked = true;
734	
735	  const rows = [];
736	  for (const [mod, code, what, reserved] of BROWSER_SHORTCUTS) {
737	    if (mod === 'ctrl') drv.down('ControlLeft');
738	    if (mod === 'shift') drv.down('ShiftLeft');
739	    const extra = mod === 'alt' ? { alt: true } : {};
740	    const r = drv.down(code, extra);
741	    drv.up(code, extra);
742	    if (mod === 'ctrl') drv.up('ControlLeft');
743	    if (mod === 'shift') drv.up('ShiftLeft');
744	
745	    const isBound = bound.has(code);
746	    rows.push({
747	      combo: mod === 'none' ? code : `${mod}+${code}`,
748	      browserAction: what,
749	      boundInGame: isBound,
750	      gameReceived: r.registered,
751	      browserDefaultPrevented: r.prevented,
752	      reservedByBrowser: reserved,
753	      // A reserved shortcut (Ctrl+W) cannot be cancelled by preventDefault at
754	      // all; only the Keyboard Lock API in fullscreen stops it reaching Chrome.
755	      ok: reserved ? true : (!isBound || r.prevented),
756	      needsKeyboardLock: reserved && isBound,
757	    });
758	  }
759	
760	  // Keys the game claims must actually arrive while playing.
761	  const lost = rows.filter((r) => r.boundInGame && !r.gameReceived);
762	  const leaks = rows.filter((r) => !r.ok);
763	  const locks = rows.filter((r) => r.needsKeyboardLock);
764	
765	  engine.dispose();
766	  return {
767	    name: 'browser-keys',
768	    pass: leaks.length === 0 && lost.length === 0,
769	    leakingCombos: leaks.map((r) => `${r.combo} (${r.browserAction})`),
770	    swallowedGameKeys: lost.map((r) => r.combo),
771	    needKeyboardLock: locks.map((r) => r.combo),
772	    rows,
773	  };
774	}
