/**
 * THROWAWAY: what the partial paths actually buy.
 *
 * A partial path that ends half a metre from where the man already stands is
 * not a walk, it is a re-solve treadmill: `_goTo` reports success, `_move`
 * arrives inside `arriveEps` on the next frame, `_combat` reads "has cover, not
 * standing in it" and hands the point back. This measures the distribution.
 * Delete once the behaviour is gated.
 */
import { boot } from './harness.mjs';
import { play, engagePlay } from './play.mjs';

const FPS = 60;
const RUN = 60 * FPS;

const { engine, rec } = await boot({ quality: 'low', deterministic: true, width: 960, height: 600, dpr: 1 });
engagePlay(engine, { populate: true });
const ai = engine.ctx.peek('ai');
const g = ai.grid;

let solves = 0, partial = 0, failed = 0;
const gains = [];
const fp = g.findPath.bind(g);
g.findPath = (from, to, out, opts) => {
  const n = fp(from, to, out, opts);
  solves++;
  if (n === 0) { failed++; return n; }
  const end = out[n - 1];
  // reached the goal, or stopped short of it?
  if (end.distanceTo(to) > g.cell) {
    partial++;
    gains.push(+(from.distanceTo(to) - end.distanceTo(to)).toFixed(2));
  }
  return n;
};

play(engine, rec, { frames: RUN, onFrame: () => {} });
gains.sort((a, b) => a - b);
const q = (p) => (gains.length ? gains[Math.min(gains.length - 1, Math.floor(gains.length * p))] : 0);
console.info(`solves ${solves} · reachedGoal ${solves - partial - failed} · partial ${partial} · noRoute ${failed}`);
console.info(`partial gain toward the goal (m): min ${gains[0] ?? '-'} p25 ${q(0.25)} median ${q(0.5)} p75 ${q(0.75)} max ${gains[gains.length - 1] ?? '-'}`);
console.info(`partials under 1 m of gain: ${gains.filter((x) => x < 1).length} · under 2 m: ${gains.filter((x) => x < 2).length}`);
engine.dispose();

/**
 * THROWAWAY: WHY a man stands still, not just how long.
 *
 * `_probe-idle.mjs` says agent 6 held one spot for 43 s. This one records, for
 * every still-streak, what the agent's cover machinery was doing while it ran:
 * did it ask the CoverMap at all, what did the map answer, was it peeking, was
 * the path budget or a failed path holding it. Delete when the answer is in a
 * gate.
 */
import { boot } from './harness.mjs';
import { play, engagePlay } from './play.mjs';

const FPS = 60;
const sec = (s) => Math.round(s * FPS);
const RUN = sec(60);

const { engine, rec } = await boot({ quality: 'low', deterministic: true, width: 960, height: 600, dpr: 1 });
engagePlay(engine, { populate: true });
const ai = engine.ctx.peek('ai');

/** picks made this frame, by agent id: 'null' | 'same' | 'new' */
const picks = new Map();
const cover = ai.cover;
const realPick = cover.pick.bind(cover);
cover.pick = (pos, threat, opts = {}) => {
  const r = realPick(pos, threat, opts);
  const a = ai.agents.find((x) => x.id === opts.id);
  picks.set(opts.id, !r ? 'null' : r === a?.cover ? 'same' : 'new');
  return r;
};

const blank = () => ({
  frames: 0, atCover: 0, noCover: 0, peeking: 0, shuffling: 0, wantMove: 0,
  pickNull: 0, pickSame: 0, pickNew: 0, pathFail: 0, pending: 0,
  coverKeys: new Set(), states: {}, holdMax: 0, first: null,
});
const stats = new Map();
const get = (a) => {
  let s = stats.get(a.id);
  if (!s) stats.set(a.id, (s = { still: 0, frames: 0, cur: blank(), best: blank(), streak: 0, longest: 0 }));
  return s;
};

play(engine, rec, {
  frames: RUN,
  onFrame: (i) => {
    for (const a of ai.agents) {
      if (!a.alive) continue;
      const s = get(a);
      s.frames++;
      if (a.speed >= 0.2) {
        if (s.streak > s.longest) { s.longest = s.streak; s.best = s.cur; }
        s.streak = 0;
        s.cur = blank();
        picks.delete(a.id);
        continue;
      }
