/**
 * THROWAWAY: does the escalating A* budget ever actually fire?
 *
 * `Agent._goTo` asks for `6000 * min(4, 1 + pathFails)` nodes, on the theory
 * that a man who was just told "no route" deserves a bigger search. But partial
 * paths landed in the same shift, and a partial converts a starved solve into a
 * short walk rather than a refusal — so `pathFails` may never leave zero and the
 * escalation may be code that cannot run. Delete once the answer is written down.
 */
import { boot } from './harness.mjs';
import { play, engagePlay } from './play.mjs';

const FPS = 60;
const RUN = 60 * FPS;

const { engine, rec } = await boot({ quality: 'low', deterministic: true, width: 960, height: 600, dpr: 1 });
engagePlay(engine, { populate: true });
const ai = engine.ctx.peek('ai');

const byBudget = new Map();     // maxNodes asked for -> how often
let solves = 0, exhausted = 0, partials = 0, noRoute = 0;
let maxExpandedSeen = 0;

const grid = ai.grid;
const fp = grid.findPath.bind(grid);
grid.findPath = (from, to, out, opts) => {
  const want = opts?.maxNodes ?? 6000;
  byBudget.set(want, (byBudget.get(want) ?? 0) + 1);
  solves++;
  const n = fp(from, to, out, opts);
  if (n === 0) noRoute++;
  else if (out[n - 1].distanceTo(to) > grid.cell) partials++;
  return n;
};

// how close a solve came to its ceiling: `_expandedLast` does not exist, so
// count the frontier work ourselves by watching the heap through one solve.
const heap = grid.open;
const push = heap.push.bind(heap);
let pushes = 0;
heap.push = (i, f) => { pushes++; return push(i, f); };

const failsSeen = new Map();
play(engine, rec, {
  frames: RUN,
  onFrame: () => {
    for (const a of ai.agents) {
      if (!a.alive) continue;
      failsSeen.set(a.pathFails, (failsSeen.get(a.pathFails) ?? 0) + 1);
    }
  },
});

console.info(`solves ${solves} · reachedGoal ${solves - partials - noRoute} · partial ${partials} · noRoute ${noRoute}`);
console.info('budget asked for:', [...byBudget.entries()].sort((a, b) => a[0] - b[0]).map(([k, v]) => `${k}:${v}`).join(' '));
console.info('agent-frames by pathFails value:', [...failsSeen.entries()].sort((a, b) => a[0] - b[0]).map(([k, v]) => `${k}:${v}`).join(' '));
console.info(`heap pushes total ${pushes} · mean per solve ${(pushes / (solves || 1)).toFixed(0)}`);
engine.dispose();

