/**
 * THROWAWAY: is `populate()`'s `regionAt` the same trap `_combat`'s was?
 *
 * `AiSystem.populate` asks `regionAt` twice — once for "which walkable network
 * is the player on", once per spawn point for "is this one on it" — and both
 * answers gate the whole garrison. If the player happens to stand on a kerb or
 * a doorstep, that is a two-cell island, and the filter then rejects every real
 * spawn point and falls back to the unfiltered list. The switch to
 * `operatingRegion` moves spawn placement, so it is only worth making if this
 * actually happens. Measure before touching it. Delete once the answer is
 * written down.
 */
import { boot } from './harness.mjs';
import { engagePlay } from './play.mjs';

const { engine } = await boot({ quality: 'low', deterministic: true, width: 960, height: 600, dpr: 1 });
const ai = engine.ctx.peek('ai');
const world = engine.ctx.peek('world');
const grid = ai.grid;
const spawns = world?.spawnPoints ?? [];

const sizeOf = (r) => (r >= 0 ? grid.regionSize[r] ?? 0 : 0);
const p = ai.playerPosition(ai._v3).clone();

const rPlayer = grid.regionAt(p.x, p.z, p.y - 1.35, 6);
const oPlayer = grid.operatingRegion(p.x, p.z, p.y - 1.35, 3);
console.info(
  `player at ${p.x.toFixed(1)},${p.y.toFixed(1)},${p.z.toFixed(1)}`,
  `| regionAt ${rPlayer} (${sizeOf(rPlayer)} cells)`,
  `| operatingRegion ${oPlayer} (${sizeOf(oPlayer)} cells)`,
  rPlayer === oPlayer ? '| SAME' : '| DIFFERENT',
);

// the biggest component in the level, for scale
let biggest = -1;
for (let i = 0; i < grid.regionSize.length; i++) {
  if (biggest < 0 || grid.regionSize[i] > grid.regionSize[biggest]) biggest = i;
}
const tiny = grid.regionSize.filter((c) => c < 10).length;
console.info(
  `level: ${grid.regionSize.length} components`,
  `| biggest ${biggest} = ${grid.regionSize[biggest]} cells`,
  `| under 10 cells: ${tiny}`,
);

let diff = 0;
const rows = [];
for (const s of spawns) {
  const r = grid.regionAt(s.position.x, s.position.z, s.position.y, 4);
  const o = grid.operatingRegion(s.position.x, s.position.z, s.position.y, 3);
  if (r !== o) diff++;
  rows.push({ d: +s.position.distanceTo(p).toFixed(1), r, rs: sizeOf(r), o, os: sizeOf(o) });
}
const accepts = (region, key) => rows.filter((e) => region < 0 || e[key] === region).length;
console.info(
  `spawn points: ${rows.length}`,
  `| regionAt != operatingRegion on ${diff}`,
  `| on a component under 10 cells: ${rows.filter((e) => e.rs > 0 && e.rs < 10).length}`,
);
console.info(
  `accepted by the filter: regionAt ${accepts(rPlayer, 'r')}/${rows.length}`,
  `· operatingRegion ${accepts(oPlayer, 'o')}/${rows.length}`,
);
const far = rows.filter((e) => e.d > 18);
console.info(
  `beyond the 18 m floor: ${far.length}`,
  `| accepted: regionAt ${far.filter((e) => rPlayer < 0 || e.r === rPlayer).length}`,
  `· operatingRegion ${far.filter((e) => oPlayer < 0 || e.o === oPlayer).length}`,
);
for (const e of rows) {
  if (e.r !== e.o || (e.rs > 0 && e.rs < 10)) {
    console.info(`  spawn ${e.d} m away: regionAt ${e.r} (${e.rs} cells) -> operatingRegion ${e.o} (${e.os} cells)`);
  }
}

// and where the men actually end up
engagePlay(engine, { populate: true });
for (const a of ai.agents) {
  const r = grid.regionAt(a.position.x, a.position.z, a.position.y, 4);
  const o = grid.operatingRegion(a.position.x, a.position.z, a.position.y, 3);
  console.info(
    `  agent ${a.id} spawned on region ${r} (${sizeOf(r)} cells)`,
