/**
 * THROWAWAY: does anyone actually stand and stare?
 *
 * The search sweep is gated on `state === ALERT && lastKnownAge < 8`. The worry
 * is a man who is standing still in some OTHER state with nothing fresh to look
 * at: his `faceYaw` is only rewritten when he is engaged with a bearing under
 * 8 s old or when he is walking, so a stale man who is not moving keeps whatever
 * yaw he last had, for ever, with no sweep on top. Measure whether that state
 * is reachable before writing code for it. Delete once the answer is written
 * down.
 */
import { boot } from './harness.mjs';
import { play, engagePlay } from './play.mjs';

const FPS = 60;
const RUN = 60 * FPS;

const { engine, rec } = await boot({ quality: 'low', deterministic: true, width: 960, height: 600, dpr: 1 });
engagePlay(engine, { populate: true });
const ai = engine.ctx.peek('ai');

const stats = new Map();
const get = (id) => {
  let s = stats.get(id);
  if (!s) stats.set(id, (s = { frames: 0, stare: 0, run: 0, longest: 0, worstYaw: 0, byState: {}, lkaMax: {} }));
  return s;
};
const lastYaw = new Map();
const runYaw = new Map();

play(engine, rec, {
  frames: RUN,
  onFrame: () => {
    for (const a of ai.agents) {
      if (!a.alive) continue;
      const s = get(a.id);
      s.frames++;
      const st = a.state;
      s.lkaMax[st] = Math.max(s.lkaMax[st] ?? 0, Math.min(a.lastKnownAge, 1e6));
      // standing still, nothing fresh to face, and not in the one state that sweeps
      const stale = !(a.lastKnownAge < 8);
      const sweeps = st === 'alert' && a.lastKnownAge < 8;
      const staring = a.speed < 0.25 && stale && !sweeps && !a.hasTarget;
      if (staring) {
        s.stare++;
        s.byState[st] = (s.byState[st] ?? 0) + 1;
        if (s.run === 0) runYaw.set(a.id, a.yaw);
        s.run++;
        if (s.run > s.longest) {
          s.longest = s.run;
          let d = a.yaw - runYaw.get(a.id);
          while (d > Math.PI) d -= Math.PI * 2;
          while (d < -Math.PI) d += Math.PI * 2;
          s.worstYaw = Math.abs(d) * 180 / Math.PI;
        }
      } else s.run = 0;
      lastYaw.set(a.id, a.yaw);
    }
  },
});

console.info('--- standing still, stale bearing, no sweep ---');
for (const [id, s] of stats) {
  const mix = Object.entries(s.byState).sort((x, y) => y[1] - x[1]).map(([k, v]) => `${k} ${v}f`).join(' ');
  const lka = Object.entries(s.lkaMax).map(([k, v]) => `${k} ${v > 1e5 ? 'inf' : v.toFixed(1)}`).join(' ');
  console.info(
    `agent ${id}`.padEnd(9),
    `staring ${String(Math.round((s.stare / s.frames) * 100)).padStart(3)}%`,
    `longest ${(s.longest / FPS).toFixed(1).padStart(5)} s`,
    `| yaw moved over it ${s.worstYaw.toFixed(0).padStart(3)} deg`,
    `| ${mix || '-'}`,
    `| max lastKnownAge per state: ${lka}`,
  );
}
const all = [...stats.values()];
console.info(
  'worst stare:', (Math.max(...all.map((s) => s.longest)) / FPS).toFixed(1), 's',
  '| mean staring:', Math.round((all.reduce((n, s) => n + s.stare / s.frames, 0) / all.length) * 100) + '%',
);
engine.dispose();

