1	/**
2	 * playtests — the gameplay scenarios `cod play` runs.
3	 *
4	 * Each scenario boots the real engine, plays a scripted input timeline through
5	 * the real Input handlers and returns `{ name, pass, ... }` with the evidence
6	 * that decided it. A scenario never prints; the command formats.
7	 *
8	 * These are assertions about FEEL, not about pixels: a crouch that reports the
9	 * stance but stops the player moving is a failure here even though every frame
10	 * still renders. That is exactly the class of bug this file exists to catch.
11	 */
12	
13	import { boot } from './harness.mjs';
14	import { play, engagePlay, BROWSER_SHORTCUTS, makeDriver, travelled } from './play.mjs';
15	import { ACTIONS } from '../../src/core/input.js';
16	
17	const FPS = 60;
18	const sec = (s) => Math.round(s * FPS);
19	
20	/** Hold `codes` from frame `from` to frame `to`. */
21	function hold(codes, from, to) {
22	  const t = {};
23	  for (const c of [].concat(codes)) {
24	    t[from] = t[from] ?? [];
25	    t[to] = t[to] ?? [];
26	  }
27	  return { codes: [].concat(codes), from, to };
28	}
29	
30	/** Build a timeline function from a list of hold() specs. */
31	function timelineOf(holds) {
32	  return (drv, engine, i) => {
33	    for (const h of holds) {
34	      if (i === h.from) for (const c of h.codes) drv.down(c);
35	      if (i === h.to) for (const c of h.codes) drv.up(c);
36	    }
37	  };
38	}
39	
40	async function bootPlay(opts = {}) {
41	  const { engine, rec } = await boot({ quality: 'low', deterministic: true, width: 960, height: 600, dpr: 1 });
42	  engagePlay(engine, opts);
43	  return { engine, rec };
44	}
45	
46	/* ====================================================================== */
47	/* 1. crouch                                                              */
48	/* ====================================================================== */
49	
50	/**
51	 * Ducking has to work while you are moving, on both bound keys, and it has to
52	 * let go again. The interesting half is Ctrl: it is a browser modifier, so a
53	 * crouch-and-strafe sends `ctrlKey: true` on the D keydown.
54	 */
55	export async function scenarioCrouch() {
56	  const { engine, rec } = await bootPlay();
57	  const holds = [
58	    hold('KeyW', sec(0.2), sec(6.0)),        // walk the whole time
59	    hold('ControlLeft', sec(1.0), sec(2.5)), // hold-crouch
60	    hold('KeyD', sec(1.4), sec(2.2)),        // strafe WHILE crouched (Ctrl+D = bookmark)

337	export async function scenarioAi(frames = sec(20)) {
338	  const { engine, rec } = await bootPlay({ populate: true });
339	  const ai = engine.ctx.peek('ai');
340	  const spawned = ai?.agents.length ?? 0;
341	
342	  const { aiSamples } = play(engine, rec, { frames, trackAi: true });
343	  const ids = spawned ? ai.agents.map((a) => a.id) : [];
344	  const dist = ids.map((id) => travelled(aiSamples, id));
345	  const moved = dist.filter((d) => d > 2.0).length;
346	  const last = aiSamples[aiSamples.length - 1] ?? [];
347	  const states = {};
348	  for (const a of last) states[a.state] = (states[a.state] ?? 0) + 1;
349	  const anyRun = aiSamples.some((f) => f.some((a) => a.speed > 1.0));
350	
351	  const pass = spawned >= 4 && moved >= Math.ceil(spawned * 0.6) && anyRun;
352	
353	  engine.dispose();
354	  return {
355	    name: 'ai-movement', pass,
356	    spawned, agentsThatMoved: moved,
357	    travelledM: dist,
358	    reachedWalkSpeed: anyRun,
359	    finalStates: states,
360	  };
361	}
362	
363	/* ====================================================================== */
364	/* 7. enemy death                                                         */
365	/* ====================================================================== */
366	
367	export async function scenarioAiDeath() {
368	  const { engine, rec } = await bootPlay({ populate: true });
369	  const ai = engine.ctx.peek('ai');
370	  if (!ai?.agents.length) {
371	    engine.dispose();
372	    return { name: 'ai-death', pass: false, reason: 'no enemies spawned' };
373	  }
374	  const victim = ai.agents[0];
375	  const startY = victim.position.y;
376	  const deaths = [];
377	  engine.events.on('actor:death', (e) => deaths.push(engine.time.frame));
378	
379	  const timeline = (drv, eng, i) => {
380	    if (i === sec(1.0)) {
381	      const p = victim.position;
382	      victim.applyDamage(500, 'torso', { x: p.x, y: p.y + 1.3, z: p.z }, { x: 0, y: 0, z: 1 });
383	    }
384	  };
385	  const { aiSamples } = play(engine, rec, { frames: sec(14), timeline, trackAi: true });
386	
387	  const rec0 = aiSamples.map((f) => f.find((a) => a.id === victim.id)).filter(Boolean);
388	  const diedAt = rec0.findIndex((a) => !a.alive);
389	  const fadeSeen = rec0.some((a) => a.opacity !== undefined && a.opacity < 0.99 && a.opacity > 0);
390	  const removed = rec0[rec0.length - 1] === undefined || !ai.agents.includes(victim);
391	  const ragdoll = !!victim.ragdoll;
392	  const fellY = ragdoll && victim.ragdoll.aabb
393	    ? +(startY + 1.7 - victim.ragdoll.aabb.maxy).toFixed(2)
394	    : null;
395	
396	  const pass = diedAt > 0 && deaths.length === 1 && ragdoll && fadeSeen && removed;
397	
398	  engine.dispose();
399	  return {
400	    name: 'ai-death', pass,
401	    diedAtSample: diedAt, deathEvents: deaths.length,
402	    ragdollCreated: ragdoll, bodyDroppedM: fellY,
403	    fadeOutObserved: fadeSeen, corpseCleanedUp: removed,
404	    remainingAgents: ai.agents.length,
405	  };
406	}
407	
408	/* ====================================================================== */
409	/* 8. squad reaction to a casualty                                        */
410	/* ====================================================================== */
411	
412	/**
413	 * What a squad does when one of its own is killed. Before this existed the
414	 * answer was "nothing at all": MEASURED on this same garrison, agent 1 was shot
415	 * dead 1.1 m from agent 3, and agents 2 and 3 kept walking their patrol route
416	 * with `lastKnownAge` still at infinity four seconds later.
417	 *
418	 * Four claims, one kill each:
419	 *   1. the men beside him react at all — alert, and suppressed by it
420	 *   2. the shot gives them a bearing to search, never the player's position
421	 *   3. they flinch: small, and not shooting, for a beat
422	 *   4. nobody keeps holding the cover his mate was just killed behind
423	 * plus 5. the last man of a gutted squad breaks contact instead of trading
424	 * shots alone with whoever just killed the other two, 6. the flinch reaches a
425	 * man who is not in a firefight — the patrol that loses its point man stops
426	 * walking — and 7. the bearing reaches his BODY: he turns to face it instead
427	 * of searching with his back to the shot.
428	 */
429	export async function scenarioSquad() {
430	  const { engine, rec } = await bootPlay({ populate: true });
431	  const ai = engine.ctx.peek('ai');

651	export async function scenarioFlank() {
652	  const { engine, rec } = await bootPlay({ populate: true });
653	  const ai = engine.ctx.peek('ai');
654	  if (!ai?.agents.length) {
655	    engine.dispose();
656	    return { name: 'ai-flank', pass: false, reason: 'no enemies spawned' };
657	  }
658	
659	  const RUN = sec(40);
660	  const BIN = sec(10);
661	  const bins = new Array(Math.ceil(RUN / BIN)).fill(0);
662	  let attempts = 0, deadEnds = 0, deferred = 0, entries = 0;
663	  let throws = 0;
664	  const barred = new Map();      // agent id -> frames blocked back to back
665	  let longestBarred = 0;
666	
667	  // EVERY destination anyone asks for, not just the flank ones. Reported
668	  // rather than asserted: see the note on the pass condition below.
669	  let goToCalls = 0, noRoutes = 0;
670	  const noRouteRun = new Map();  // agent id -> no-route answers back to back
671	  let longestNoRouteRun = 0;
672	  // claims 5 + 6: how long a man was a statue, and how long he was a statue
673	  // with nothing to get behind and nowhere to be.
674	  const stillRun = new Map();
675	  const adriftRun = new Map();
676	  let longestStill = 0, longestAdrift = 0, adriftFrames = 0;
677	  // claim 7: how hard the CoverMap is being worked, and how long one man went
678	  // on asking it a question it kept answering `null`.
679	  let coverQueries = 0, nullPicks = 0;
680	  const nullRun = new Map();
681	  let longestNullRun = 0;
682	
683	  // A manoeuvre is one _flankPoint search followed by the _goTo it feeds. The
684	  // flag is per agent and cleared every frame, so a search that finds no ground
685	  // at all cannot be charged to somebody else's path request.
686	  for (const a of ai.agents) {
687	    const point = a._flankPoint.bind(a);
688	    a._flankPoint = (...args) => {
689	      a.__flanking = true;
690	      return point(...args);
691	    };
692	    const goTo = a._goTo.bind(a);
693	    a._goTo = (dest) => {
694	      const mine = a.__flanking;
695	      a.__flanking = false;
696	      const ok = goTo(dest);
697	      goToCalls++;
698	      // `!ok` with a pending path is the frame's A* budget talking and the
699	      // request is queued; `!ok` without one is A* saying there is no route at
700	      // all, which is what leaves a man standing.
701	      const dead = !ok && !a.pathPending;
702	      const run = dead ? (noRouteRun.get(a.id) ?? 0) + 1 : 0;
703	      noRouteRun.set(a.id, run);
704	      if (run > longestNoRouteRun) longestNoRouteRun = run;
705	      if (dead) noRoutes++;
706	      if (mine) {
707	        attempts++;
708	        if (!ok) a.pathPending ? deferred++ : deadEnds++;
709	      }
710	      return ok;
711	    };
712	  }
713	  const realThrow = ai.throwGrenade.bind(ai);
714	  ai.throwGrenade = (...args) => {
715	    throws++;
716	    return realThrow(...args);
717	  };
718	
719	  // Every question put to the CoverMap, and who asked it. `pick` carries the
720	  // caller's id in its options, which is what makes the run per-man rather than
721	  // a squad-wide average that would hide one agent spinning.
722	  const cover = ai.cover;
723	  if (cover) {
724	    const pick = cover.pick.bind(cover);
725	    cover.pick = (pos, threat, opts = {}) => {
726	      const got = pick(pos, threat, opts);
727	      coverQueries++;
728	      if (!got) nullPicks++;
729	      const id = opts.id;
730	      if (id !== undefined) {
731	        const run = got ? 0 : (nullRun.get(id) ?? 0) + 1;
732	        nullRun.set(id, run);
733	        if (run > longestNullRun) longestNullRun = run;
734	      }
735	      return got;
736	    };
737	  }
738	
739	  const prev = new Map();
740	  const onFrame = (i) => {
741	    const bin = Math.floor(i / BIN);
742	    for (const a of ai.agents) {
743	      a.__flanking = false;
744	      if (!a.alive) {
745	        stillRun.set(a.id, 0);
746	        adriftRun.set(a.id, 0);
747	        continue;
748	      }
749	      if (a.state === 'flank' && prev.get(a.id) !== 'flank') {
750	        entries++;
751	        bins[bin]++;
752	      }
753	      prev.set(a.id, a.state);
754	
755	      /* 5. the statue check. 0.2 m/s is the same floor the movement code uses
756	         to decide a man wants to go somewhere; peeking out of cover and pulling
757	         back in crosses it, so a legitimate hold in cover still breaks the run. */
758	      const still = a.speed < 0.2 ? (stillRun.get(a.id) ?? 0) + 1 : 0;
759	      stillRun.set(a.id, still);
760	      if (still > longestStill) longestStill = still;
761	
762	      /* 6. …and the specific way he gets stuck: in the fight, nothing to get
763	         behind, no path anywhere. `onFrame` runs after `_move`, so a path that
764	         starts and ends inside one frame shows up here as a single adrift
765	         frame — which is why the claim is on the RUN, not the total. */
766	      const adrift = a.state === 'combat' && !a.cover && !a.hasMoveTarget && !a.pathPending;
767	      if (adrift) adriftFrames++;
768	      const arun = adrift ? (adriftRun.get(a.id) ?? 0) + 1 : 0;
769	      adriftRun.set(a.id, arun);
770	      if (arun > longestAdrift) longestAdrift = arun;
771	
772	      // the exact term the flank gate tests, rebuilt from the outside
773	      const sq = a.squad;
