438	  /** A killing hit from a known direction, so the back-trace has something to work with. */
439	  const kill = (a) => {
440	    const p = a.position;
441	    a.applyDamage(500, 'torso', { x: p.x, y: p.y + 1.3, z: p.z }, { x: 0, y: 0, z: 1 });
442	  };
443	  const snap = () =>
444	    ai.agents.map((a) => ({
445	      id: a.id, squad: a.squad, alive: a.alive, state: a.state,
446	      sup: a.suppression, flinch: a.manDownTimer, fire: a.wantFire,
447	      lka: a.lastKnownAge, cover: a.cover,
448	      cx: a.coverPos.x, cz: a.coverPos.z, x: a.position.x, z: a.position.z,
449	      yaw: a.yaw, speed: a.speed, lkx: a.lastKnown.x, lkz: a.lastKnown.z,
450	    }));
451	
452	  const KILL1 = sec(4.0);  // a man on patrol, his squad walking beside him
453	  const KILL2 = sec(6.0);  // a man of the squad that is already in cover
454	  const KILL3 = sec(8.0);  // the second of squad one: one man left of three
455	  const bodies = {};
456	  const victims = {};
457	
458	  const timeline = (drv, eng, i) => {
459	    if (i === KILL1) {
460	      const v = squads[0].members[0];
461	      victims[KILL1] = v; bodies[KILL1] = { x: v.position.x, z: v.position.z, squad: squads[0] };
462	      kill(v);
463	    }
464	    if (i === KILL2) {
465	      const v = squads[1].members[1];
466	      victims[KILL2] = v; bodies[KILL2] = { x: v.position.x, z: v.position.z, squad: squads[1] };
467	      kill(v);
468	    }
469	    if (i === KILL3) {
470	      const v = squads[0].members.find((m) => m.alive);
471	      if (v) { victims[KILL3] = v; bodies[KILL3] = { x: v.position.x, z: v.position.z, squad: squads[0] }; kill(v); }
472	    }
473	  };
474	
475	  const frames = [];
476	  play(engine, rec, { frames: sec(16), timeline, onFrame: () => frames.push(snap()) });
477	
478	  const dist = (a, bx, bz) => Math.hypot(a.x - bx, a.z - bz);
479	  const at = (f) => frames[f] ?? [];
480	  /**
481	   * The men of the dead man's squad who were close enough to know about it.
482	   * The victim is excluded explicitly: one frame before the kill he is alive,
483	   * 0 m from his own body and holding the very cover point in question.
484	   */
485	  const mates = (f, k) =>
486	    at(f).filter(
487	      (a) => a.alive && a.id !== victims[k]?.id && a.squad === bodies[k]?.squad &&
488	        dist(a, bodies[k].x, bodies[k].z) < 30
489	    );
490	
491	  /* 1. did the survivors react, and were they oblivious before? */
492	  const before1 = mates(KILL1 - 1, KILL1);
493	  const obliviousBefore = before1.filter((a) => a.state === 'patrol' || a.state === 'idle').length;
494	  const noBearingBefore = before1.filter((a) => !(a.lka < 1e6)).length;
495	  const after1 = mates(KILL1, KILL1);
496	  const alerted = after1.filter((a) => a.state !== 'patrol' && a.state !== 'idle').length;
497	  const supBefore = Math.max(0, ...before1.map((a) => a.sup));
498	  const supAfter = Math.max(0, ...after1.map((a) => a.sup));
499	
500	  /* 2. a bearing, arriving with a call-out delay rather than instantly */
501	  const bearings = after1.filter((a) => a.lka < 1e6).length;
502	  const bearingDelays = after1.map((a) => +a.lka.toFixed(2)).filter((v) => v > 0);
503	
504	  /* 3. the flinch, and no shooting during it — across every casualty */
505	  let flinchFrames = 0;
506	  let firedWhileFlinching = 0;
507	  for (const f of frames) {
508	    for (const a of f) {
509	      if (!a.alive || a.flinch <= 0) continue;
510	      flinchFrames++;
511	      if (a.fire) firedWhileFlinching++;
512	    }
513	  }
514	
515	  /* 4. cover held next to the body is given up for a point further from it */
516	  const holders = mates(KILL2 - 1, KILL2).filter((a) => a.cover && dist({ x: a.cx, z: a.cz }, bodies[KILL2].x, bodies[KILL2].z) < 5);
517	  const moved = holders.map((h) => {
518	    const now = at(KILL2 + sec(1.0)).find((a) => a.id === h.id);
519	    if (!now?.cover || now.cover === h.cover) return null;
520	    const was = dist({ x: h.cx, z: h.cz }, bodies[KILL2].x, bodies[KILL2].z);
521	    const is = dist({ x: now.cx, z: now.cz }, bodies[KILL2].x, bodies[KILL2].z);
522	    return +(is - was).toFixed(2);
523	  });
524	  const coverAbandoned = moved.filter((d) => d !== null).length;
525	
526	  /* 5. one man left of three: break contact */
527	  const lastMan = frames[frames.length - 1].find((a) => a.alive && a.squad === squads[0]);
528	  const brokeContact = lastMan
529	    ? frames.slice(KILL3).some((f) => f.find((a) => a.id === lastMan.id)?.state === 'retreat')
530	    : false;
531	
532	  /**
533	   * 6. the flinch is visible on a man who is NOT in a firefight. The flinch
534	   * used to be applied inside the combat branch, so the case it was written for
535	   * — a patrol losing its point man — walked straight past the body at 1.35 m/s
536	   * with the shock timer ticking down unread.
537	   */
538	  const patrolFlinch = after1.map((m) => {
539	    const window = frames.slice(KILL1, KILL1 + sec(1.2)).map((f) => f.find((a) => a.id === m.id));
540	    const during = window.filter((a) => a?.flinch > 0);
541	    return {
542	      id: m.id,
543	      wasWalking: +(at(KILL1 - 1).find((a) => a.id === m.id)?.speed ?? 0).toFixed(2),
544	      stoppedTo: during.length ? +Math.min(...during.map((a) => a.speed)).toFixed(2) : null,
545	      inCombat: during.some((a) => a.state === 'combat'),
546	    };
547	  });
548	  // 0.5 m/s is a man who has stopped; patrol speed is 1.35 and the ease-out is
549	  // ~0.14 s, so the two cases are nowhere near each other.
550	  const flinchStopped = patrolFlinch.filter((p) => p.stoppedTo !== null && p.stoppedTo < 0.5).length;
551	
552	  /**
553	   * 7. and he turns to look at the bearing. Knowing where the shot came from
554	   * and standing there facing the other way is the tell that the squad's
555	   * information never reached the model — facing only followed `lastKnown`
556	   * while the man was in combat, and a man reacting to a casualty is not.
557	   */
558	  const bearingErrDeg = (a) => {
559	    if (!a) return null;
560	    const want = Math.atan2(a.lkx - a.x, a.lkz - a.z);
561	    let d = want - a.yaw;
562	    while (d > Math.PI) d -= Math.PI * 2;
563	    while (d < -Math.PI) d += Math.PI * 2;
564	    return Math.abs(d) * 180 / Math.PI;
565	  };
566	  const turns = after1.map((m) => {
567	    const window = frames.slice(KILL1, KILL1 + sec(2.5)).map((f) => f.find((a) => a.id === m.id));
568	    const errs = window.map(bearingErrDeg).filter((e) => e !== null);
569	    return {
570	      id: m.id,
571	      offByAtTheShot: +(bearingErrDeg(at(KILL1).find((a) => a.id === m.id)) ?? -1).toFixed(1),
572	      closestWithin2p5s: errs.length ? +Math.min(...errs).toFixed(1) : null,
573	    };
574	  });
575	  const turned = turns.filter((t) => t.closestWithin2p5s !== null && t.closestWithin2p5s < 45).length;
576	
577	  const pass =
578	    obliviousBefore === before1.length && before1.length >= 2 &&
579	    noBearingBefore === before1.length &&
580	    alerted === after1.length &&
581	    supAfter > supBefore + 0.4 &&
582	    bearings === after1.length && bearingDelays.length === after1.length &&
583	    flinchFrames > 0 && firedWhileFlinching === 0 &&
584	    holders.length > 0 && coverAbandoned === holders.length &&
585	    brokeContact &&
586	    flinchStopped === after1.length &&
587	    turned === after1.length;
588	
589	  engine.dispose();
590	  return {
591	    name: 'ai-squad', pass,
592	    matesInEarshot: after1.length,
593	    obliviousBeforeKill: `${obliviousBefore}/${before1.length} patrolling, ${noBearingBefore} with no bearing`,
594	    alertedOnTheKill: `${alerted}/${after1.length}`,
595	    suppression: `${supBefore.toFixed(2)} -> ${supAfter.toFixed(2)}`,
596	    bearingsGiven: bearings,
597	    callOutDelaysS: bearingDelays,
598	    flinchFrames, shotsWantedWhileFlinching: firedWhileFlinching,
599	    coverNextToBody: `${coverAbandoned}/${holders.length} abandoned`,
600	    newCoverFurtherByM: moved.filter((d) => d !== null),
601	    lastManBrokeContact: brokeContact,
602	    patrolStoppedForIt: `${flinchStopped}/${after1.length}`,
603	    walkingAtMsThenDownTo: patrolFlinch.map((p) => `${p.wasWalking}->${p.stoppedTo}`),
604	    turnedToBearing: `${turned}/${after1.length}`,
605	    bearingErrorDeg: turns.map((t) => `${t.offByAtTheShot}->${t.closestWithin2p5s}`),
606	  };
607	}
608	
609	/* ====================================================================== */
610	/* 9. flanking                                                            */
611	/* ====================================================================== */
612	
613	/**
614	 * Do the enemies ever actually manoeuvre? "They just sit behind a wall" is the
615	 * single loudest complaint a shooter's AI can earn, and this garrison had two
616	 * independent reasons to earn it — both invisible from every other gate,
617	 * because a flank that never happens looks exactly like a firefight.
618	 *
619	 *   1. The destination was a raw geometric offset, "fifteen metres to my left",
620	 *      handed to A* without ever asking whether a man can stand there.
621	 *      MEASURED over 60 s: 11 of 14 manoeuvres died as a solve that returned no
622	 *      route, the dice already spent. `Agent._flankPoint` now snaps the point
623	 *      onto walkable ground in the agent's own nav component first.
624	 *   2. The gate refused to move anyone holding a grenade, on the theory that he
625	 *      would throw it instead — but the squad rations throws, so he mostly did
626	 *      not. MEASURED on that same run: 6637 of 11354 flank-eligible frames
627	 *      blocked, against 2139 of 2143 throw windows refused by the ration.
628	 *
629	 * The claims: the squad tries to flank, every try that gets past the dice finds
630	 * a route, the try becomes a real flank, and no man is barred from manoeuvring
631	 * for long by a grenade he is not going to get to throw.
632	 *
633	 * …and then three more, which are about the same complaint seen from the other
634	 * end. A flank that happens is worth nothing if the man who is NOT flanking is
635	 * a statue, and every one of these was a real, measured freeze:
636	 *
637	 *   5. Nobody holds one square metre for most of a firefight. MEASURED before
638	 *      the nav fix: one man stood on the same spot for 43 s, because he had
639	 *      walked onto a crate lid — an 8-cell nav island with no cover point on it
640	 *      — and every region-filtered query answered "nothing".
641	 *   6. Nobody stands in combat with no cover AND nowhere to go. That is the
642	 *      exact signature of the freeze above (2581 consecutive frames of it), and
643	 *      it is invisible to claim 5 alone: a man shuffling 0.3 m between peek
644	 *      poses reads as "moving" while being just as stuck.
645	 *   7. Nobody interrogates the CoverMap in a loop. The freeze above came with a
646	 *      full 1349-point scan every single frame, 2581 frames running, every one
647	 *      of them answered `null` — because "I have no cover" used to be its own
648	 *      right to re-ask, on top of the repath clock. A man the map has nothing
649	 *      for asked it sixty times a second for as long as that lasted.
650	 */

1	/**
2	 * play — browserless GAMEPLAY probe.
3	 *
4	 * The rest of the CLI measures the renderer. This measures the *game*: does the
5	 * crouch key actually crouch, does a slide start, does the player die at 0 HP,
6	 * does health come back, do the enemies move. All of it against the real engine
7	 * booted in Node (see harness.mjs) — no browser, headless or otherwise.
8	 *
9	 * Input is not poked into the movement state machine directly. Every key goes
10	 * through `Input._onKeyDown` / `_onKeyUp` with a synthetic event object carrying
11	 * the same modifier flags a browser would send, so the probe sees exactly what a
12	 * player sees: if the handler drops Ctrl+D, the probe records a key that never
13	 * arrived AND a browser default that was never prevented. That second half is
14	 * the only way to catch "the game bookmarked the page" without a browser.
15	 */
16	
17	/** Chrome/Edge/Firefox shortcuts a game key can collide with. */
18	export const BROWSER_SHORTCUTS = [
19	  ['ctrl', 'KeyD', 'bookmark this page', false],
20	  ['ctrl', 'KeyW', 'close tab', true],
21	  ['ctrl', 'KeyT', 'new tab', true],
22	  ['ctrl', 'KeyN', 'new window', true],
23	  ['ctrl', 'KeyS', 'save page', false],
24	  ['ctrl', 'KeyR', 'reload', false],
25	  ['ctrl', 'KeyF', 'find', false],
26	  ['ctrl', 'KeyP', 'print', false],
27	  ['ctrl', 'KeyA', 'select all', false],
28	  ['ctrl', 'KeyE', 'search from address bar', false],
29	  ['ctrl', 'KeyG', 'find next', false],
30	  ['ctrl', 'KeyQ', 'quit browser', true],
31	  ['ctrl', 'KeyH', 'history', false],
32	  ['ctrl', 'KeyJ', 'downloads', false],
33	  ['ctrl', 'KeyU', 'view source', false],
34	  ['ctrl', 'Digit1', 'switch to tab 1', true],
35	  ['ctrl', 'Digit2', 'switch to tab 2', true],
36	  ['ctrl', 'Tab', 'next tab', true],
37	  ['none', 'Space', 'scroll page', false],
38	  ['none', 'Tab', 'move focus', false],
39	  ['none', 'ArrowUp', 'scroll page', false],
40	  ['none', 'ArrowDown', 'scroll page', false],
41	  ['none', 'Backspace', 'history back', false],
42	  // Alt+Left IS cancelable from a page (unlike Ctrl+W), so preventDefault is
43	  // enough and this does not need the Keyboard Lock API.
44	  ['alt', 'ArrowLeft', 'history back', false],
45	  ['shift', 'Space', 'scroll page up', false],
46	];
47	
48	/**
49	 * Drives keys and mouse through the real Input handlers.
50	 *
51	 * `held` mirrors physically-held keys so a later event carries `ctrlKey: true`
52	 * while Ctrl is down, which is the whole reason crouch-and-strafe used to break.
53	 */
54	export function makeDriver(engine) {
55	  const input = engine.input;
56	  const held = new Set();
57	  /** Every keydown we sent: did the game take it, did it stop the browser. */
58	  const keyLog = [];
59	
60	  const mods = (extra = {}) => ({
61	    ctrlKey: !!extra.ctrl || held.has('ControlLeft') || held.has('ControlRight'),
62	    shiftKey: !!extra.shift || held.has('ShiftLeft') || held.has('ShiftRight'),
63	    altKey: !!extra.alt || held.has('AltLeft'),
64	    metaKey: !!extra.meta || held.has('MetaLeft'),
65	  });
66	
67	  function down(code, extra = {}) {
68	    let prevented = false;
69	    const before = input._pendingDown.has(code) || input.down.has(code);
70	    const ev = {
71	      code, key: code, repeat: false, ...mods(extra),
72	      target: engine.canvas,
73	      preventDefault() { prevented = true; },
74	      stopPropagation() {},
75	    };
76	    input._onKeyDown(ev);
77	    held.add(code);
78	    const registered = before || input._pendingDown.has(code) || input.down.has(code);
79	    keyLog.push({ code, ctrl: ev.ctrlKey, alt: ev.altKey, prevented, registered });
80	    return { prevented, registered };
81	  }
82	
83	  function up(code, extra = {}) {
84	    held.delete(code);
85	    const ev = {
86	      code, key: code, repeat: false, ...mods(extra),
87	      target: engine.canvas,
88	      preventDefault() {}, stopPropagation() {},
89	    };
90	    input._onKeyUp(ev);
91	  }
92	
93	  function mouse(button, kind) {
94	    const ev = { button, target: engine.canvas, preventDefault() {} };
95	    if (kind === 'down') input._onMouseDown(ev);
96	    else input._onMouseUp(ev);
97	  }
98	
99	  function look(dx, dy = 0) {
100	    input._rawLook.x += dx;
101	    input._rawLook.y += dy;
102	  }
103	
104	  function releaseAll() {
105	    for (const c of [...held]) up(c);
106	  }
107	
108	  return { down, up, mouse, look, releaseAll, keyLog, held };
109	}
110	
111	/** Put the engine into a playable state: input live, pointer locked, control on. */
112	export function engagePlay(engine, { populate = false } = {}) {
113	  engine.input.enabled = true;
114	  engine.input.frozen = false;
115	  engine.input.pointerLocked = true;
116	  engine.ctx.peek('player')?.setControlEnabled?.(true);
117	  const ai = engine.ctx.peek('ai');
118	  if (populate && ai && ai.agents.length === 0) {
119	    ai.forcePopulate = true;
120	    try { ai.populate(); } catch (err) { console.warn('[play] populate failed', err?.message ?? err); }
121	  }
122	  return ai;
123	}
124	
125	/** One frame's worth of everything the gameplay tests care about. */
126	export function sample(engine) {
127	  const p = engine.ctx.peek('player');
128	  const m = p?.movement;
129	  const h = p?.health;
130	  return {
131	    frame: engine.time.frame,
132	    t: +engine.time.elapsed.toFixed(3),
133	    state: m?.state ?? null,
134	    stance: m?.stance ?? null,
135	    stanceWant: m?.stanceWant ?? null,
136	    sliding: !!m?.sliding,
137	    sprinting: !!m?.sprinting,
138	    grounded: !!m?.grounded,
139	    speed: +(m?.horizontalSpeed ?? 0).toFixed(3),
140	    eye: +(m ? m.eyeHeight : 0).toFixed(3),
141	    x: +(m?.position.x ?? 0).toFixed(3),
142	    y: +(m?.position.y ?? 0).toFixed(3),
143	    z: +(m?.position.z ?? 0).toFixed(3),
144	    health: h ? +h.value.toFixed(2) : null,
145	    dead: !!h?.dead,
146	    regen: !!h?.regenerating,
147	    control: !!p?.controlEnabled,
148	  };
149	}
150	
151	export function aiSample(engine) {
152	  const ai = engine.ctx.peek('ai');
153	  if (!ai) return [];
154	  return ai.agents.map((a) => ({
155	    id: a.id,
156	    alive: a.alive,
157	    state: a.state,
158	    clip: a.clip,
159	    speed: +(a.speed ?? 0).toFixed(3),
160	    x: +a.position.x.toFixed(3),
161	    z: +a.position.z.toFixed(3),
162	    hasTarget: !!a.hasTarget,
163	    deadTime: a.deadTime,
164	    opacity: a.fadeOpacity,
165	  }));
166	}
167	
168	/**
169	 * Pump `frames` frames, applying a timeline and sampling every frame.
170	 *
171	 * timeline: `{ [frame]: (drv, engine) => void }` or an array of
172	 * `[frame, 'down'|'up', code]` triples.
173	 */
174	export function play(engine, rec, {
175	  frames = 240, stepMs = 1000 / 60, timeline = {}, onFrame = null, trackAi = false,
176	} = {}) {
177	  const dom = globalThis.__COD_DOM__;
178	  const drv = makeDriver(engine);
179	  const events = typeof timeline === 'function' ? {} : timeline;
180	  const samples = [];
181	  const aiSamples = [];
182	  let now = 1000;
183	
184	  for (let i = 0; i < frames; i++) {
185	    rec?.beginFrame();
186	    now += stepMs;
187	    const step = Array.isArray(events) ? null : events[i];
188	    if (step) step(drv, engine, i);
189	    if (Array.isArray(events)) {
190	      for (const [f, kind, code] of events) {
191	        if (f !== i) continue;
192	        if (kind === 'down') drv.down(code);
193	        else if (kind === 'up') drv.up(code);
194	      }
195	    }
196	    if (typeof timeline === 'function') timeline(drv, engine, i);
197	    engine.step(now);
198	    dom?.pumpRaf(now);
199	    const s = sample(engine);
200	    samples.push(s);
201	    if (trackAi) aiSamples.push(aiSample(engine));
202	    onFrame?.(i, s, drv);
203	  }
204	  drv.releaseAll();
205	  return { samples, aiSamples, keyLog: drv.keyLog, drv };
206	}
207	
208	/* ------------------------------------------------------------------ utils -- */
209	
210	export const any = (samples, fn) => samples.some(fn);
211	export const count = (samples, fn) => samples.reduce((n, s) => n + (fn(s) ? 1 : 0), 0);
212	export const maxOf = (samples, key) => samples.reduce((m, s) => Math.max(m, s[key] ?? 0), -Infinity);
213	export const firstIndex = (samples, fn) => samples.findIndex(fn);
214	
215	/** Total ground distance an agent covered across an AI sample series. */
216	export function travelled(aiSamples, id) {
217	  let d = 0;
218	  let prev = null;
219	  for (const frame of aiSamples) {
220	    const a = frame.find((x) => x.id === id);
221	    if (!a) continue;
222	    if (prev) d += Math.hypot(a.x - prev.x, a.z - prev.z);
223	    prev = a;
224	  }
225	  return +d.toFixed(2);
226	}
