/**
 * THROWAWAY probe — delete before the shift ends.
 *
 * Two open questions from the handover, measured before anything is changed:
 *   A. does a man ever throw a SECOND grenade in a real fight, or is the
 *      resupply fix only true in the lab scenario that forces the throw?
 *   B. what does RETREAT actually do? `ai-squad` only checks that the last man
 *      of a gutted squad enters the state, never that he arrives anywhere,
 *      gets away from the threat, or comes back out.
 */
import { boot } from './harness.mjs';
import { play, engagePlay } from './play.mjs';

const FPS = 60;
const sec = (s) => Math.round(s * FPS);

async function bootPlay(opts = {}) {
  const { engine, rec } = await boot({ quality: 'low', deterministic: true, width: 960, height: 600, dpr: 1 });
  engagePlay(engine, opts);
  return { engine, rec };
}

/* ------------------------------------------------------------------ A -- */

async function grenades(RUN) {
  const { engine, rec } = await bootPlay({ populate: true });
  const ai = engine.ctx.peek('ai');
  const per = new Map();          // id -> { throws, firstAtS, secondAtS, readyFrames, rationRefusals }
  for (const a of ai.agents) per.set(a.id, { throws: 0, at: [], readyFrames: 0, carryingAgainAtS: null, rationBlocked: 0 });

  for (const a of ai.agents) {
    const t = a._throwGrenade.bind(a);
    a._throwGrenade = (target) => {
      const r = per.get(a.id);
      r.throws++;
      r.at.push(+(engine.time.frame / FPS).toFixed(2));
      return t(target);
    };
  }

  const hadThrown = new Set();
  const onFrame = (i) => {
    const sq = new Set();
    for (const a of ai.agents) {
      if (!a.alive) continue;
      const r = per.get(a.id);
      // the exact term `_combat` computes, rebuilt from outside
      const target = a.hasTarget || a.lastKnownAge < 5 ? a.lastKnown : null;
      const d = target ? a.position.distanceTo(target) : 0;
      const ready = a.hasGrenade && a.grenadeCooldown <= 0 && !!target && d > 8 && d < 26 && a.lastKnownAge < 1.5;
      if (ready) {
        r.readyFrames++;
        if (a.squad && a.squad.grenadeCooldown > 0) r.rationBlocked++;
      }
      if (r.throws > 0) hadThrown.add(a.id);
      if (hadThrown.has(a.id) && a.hasGrenade && r.carryingAgainAtS === null && r.throws > 0)
        r.carryingAgainAtS = +(i / FPS).toFixed(2);
    }
    void sq;
  };

  play(engine, rec, { frames: RUN, onFrame });

  const rows = [...per.entries()].map(([id, r]) => ({
    id, throws: r.throws, atS: r.at,
    readyFrames: r.readyFrames, rationBlockedFrames: r.rationBlocked,
    carryingAgainAtS: r.carryingAgainAtS,
  }));
  const total = rows.reduce((n, r) => n + r.throws, 0);
  const out = {
    runS: RUN / FPS,
    totalThrows: total,
    menWhoThrewTwice: rows.filter((r) => r.throws >= 2).length,
    squadGrenadeCooldowns: (ai.squads ?? []).map((s) => +s.grenadeCooldown.toFixed(2)),
    rows,
  };
  engine.dispose();
  return out;
}

/* ------------------------------------------------------------------ B -- */

async function retreat(RUN) {
  const { engine, rec } = await bootPlay({ populate: true });
  const ai = engine.ctx.peek('ai');
  const squads = (ai.squads ?? []).filter((s) => s.members.length >= 3);

  const kill = (a) => {
    if (!a?.alive) return;
    const p = a.position;
    a.applyDamage(500, 'torso', { x: p.x, y: p.y + 1.3, z: p.z }, { x: 0, y: 0, z: 1 });
  };

  // every _breakContact call: did it take, and where was it aiming
  const calls = [];
  for (const a of ai.agents) {
    const bc = a._breakContact.bind(a);
    a._breakContact = (from) => {
      const before = { x: a.position.x, z: a.position.z };
      const fromXZ = { x: from.x, z: from.z };
      const ok = bc(from);
      calls.push({
        id: a.id, t: +(engine.time.frame / FPS).toFixed(2), ok,
        fromDistM: +Math.hypot(before.x - fromXZ.x, before.z - fromXZ.z).toFixed(2),
        destDistM: ok ? +a.position.distanceTo(a.moveTarget).toFixed(2) : null,
        pathLen: ok ? a.pathLen : null,
      });
      return ok;
    };
  }

  // kill two of each three-man squad so both survivors are "broken"
  const K = [sec(3), sec(5), sec(7), sec(9)];
  const timeline = (drv, eng, i) => {
    if (i === K[0]) kill(squads[0].members[0]);
    if (i === K[1]) kill(squads[1].members[0]);
    if (i === K[2]) kill(squads[0].members.find((m) => m.alive));
    if (i === K[3]) kill(squads[1].members.find((m) => m.alive));
  };

  // one episode per continuous stretch in RETREAT
  const open = new Map();
  const episodes = [];
  const onFrame = (i) => {
    for (const a of ai.agents) {
      const inR = a.alive && a.state === 'retreat';
      const ep = open.get(a.id);
      if (inR && !ep) {
        open.set(a.id, {
          id: a.id, startS: +(i / FPS).toFixed(2), frames: 0, dist: 0,
          x: a.position.x, z: a.position.z,
          startX: a.position.x, startZ: a.position.z,
          threatX: a.moveTarget.x, threatZ: a.moveTarget.z,
          arrivedM: null, minSpeed: Infinity, maxSpeed: 0, lostTarget: 0,
        });
      } else if (inR && ep) {
        ep.frames++;
        ep.dist += Math.hypot(a.position.x - ep.x, a.position.z - ep.z);
        ep.x = a.position.x; ep.z = a.position.z;
        ep.minSpeed = Math.min(ep.minSpeed, a.speed);
        ep.maxSpeed = Math.max(ep.maxSpeed, a.speed);
        if (!a.hasMoveTarget) ep.lostTarget++;
      } else if (!inR && ep) {
        ep.endS = +(i / FPS).toFixed(2);
        ep.durS = +((ep.frames + 1) / FPS).toFixed(2);
        ep.travelledM = +ep.dist.toFixed(2);
        ep.netM = +Math.hypot(a.position.x - ep.startX, a.position.z - ep.startZ).toFixed(2);
        ep.gotToDestM = +Math.hypot(a.position.x - ep.threatX, a.position.z - ep.threatZ).toFixed(2);
        ep.exitState = a.state;
        ep.speed = [+ep.minSpeed.toFixed(2), +ep.maxSpeed.toFixed(2)];
        delete ep.x; delete ep.z; delete ep.dist; delete ep.minSpeed; delete ep.maxSpeed;
        delete ep.startX; delete ep.startZ; delete ep.threatX; delete ep.threatZ; delete ep.arrivedM;
        episodes.push(ep);
        open.delete(a.id);
      }
    }
  };

  play(engine, rec, { frames: RUN, timeline, onFrame });

  const stillOpen = [...open.values()].map((e) => ({ id: e.id, startS: e.startS, frames: e.frames, note: 'still retreating at end' }));
  const survivors = ai.agents.filter((a) => a.alive).map((a) => ({ id: a.id, state: a.state, hp: +a.health.toFixed(0) }));
  const out = {
    runS: RUN / FPS,
    breakContactCalls: calls.length,
    refused: calls.filter((c) => !c.ok).length,
    episodes: episodes.length,
    episodeDetail: episodes,
    stillOpen,
    survivors,
    callDetail: calls.slice(0, 20),
  };
  engine.dispose();
  return out;
}

/* ------------------------------------------------------------------------ */

const quiet = () => {
  const w = console.warn, l = console.log;
  console.warn = () => {}; console.log = () => {};
  return () => { console.warn = w; console.log = l; };
};

const which = process.argv[2] ?? 'both';
const secs = Number(process.argv[3] ?? 90);
let r1 = null, r2 = null;
let restore = quiet();
try {
  if (which === 'grenade' || which === 'both') r1 = await grenades(sec(secs));
  if (which === 'retreat' || which === 'both') r2 = await retreat(sec(Math.min(secs, 45)));
} finally { restore(); }
if (r1) console.log('GRENADE ' + JSON.stringify(r1, null, 2));
if (r2) console.log('RETREAT ' + JSON.stringify(r2, null, 2));
process.exit(0);

