/**
 * THROWAWAY probe — delete before the shift ends.
 *
 * "Running on the spot": `this.speed` at full sprint while `position` does not
 * change. Found in a retreat episode (4 s at speed 4.6, net 0.01 m), but the
 * question is whether it is a retreat problem or a movement problem. Measure it
 * across every state, in a plain firefight with nobody dead, and in the gutted-
 * squad setup where it was first seen.
 */
import { boot } from './harness.mjs';
import { play, engagePlay } from './play.mjs';

const FPS = 60;
const sec = (s) => Math.round(s * FPS);
const DT = 1 / 60;

const quiet = () => {
  const w = console.warn, l = console.log;
  console.warn = () => {}; console.log = () => {};
  return () => { console.warn = w; console.log = l; };
};

async function measure(label, { kills, RUN }) {
  const { engine, rec } = await boot({ quality: 'low', deterministic: true, width: 960, height: 600, dpr: 1 });
  engagePlay(engine, { populate: true });
  const ai = engine.ctx.peek('ai');
  const squads = (ai.squads ?? []).filter((s) => s.members.length >= 3);

  const kill = (a) => {
    if (!a?.alive) return;
    const p = a.position;
    a.applyDamage(500, 'torso', { x: p.x, y: p.y + 1.3, z: p.z }, { x: 0, y: 0, z: 1 });
  };
  const timeline = kills ? (drv, eng, i) => {
    if (i === sec(3)) kill(squads[0].members[0]);
    if (i === sec(5)) kill(squads[1].members[0]);
    if (i === sec(7)) kill(squads[0].members.find((m) => m.alive));
    if (i === sec(9)) kill(squads[1].members.find((m) => m.alive));
  } : undefined;

  const prev = new Map();
  const run = new Map();        // id -> current on-the-spot streak
  const worst = new Map();      // id -> { frames, state, speed, at }
  const perState = {};
  const ratios = [];            // actual / intended, while sprinting
  let spotFrames = 0, movingFrames = 0;

  const onFrame = (i) => {
    for (const a of ai.agents) {
      if (!a.alive) { run.set(a.id, 0); prev.delete(a.id); continue; }
      const p = prev.get(a.id);
      prev.set(a.id, { x: a.position.x, z: a.position.z });
      if (!p) continue;
      // What he asked for this frame against what the controller gave him.
      const want = a.speed;
      if (want <= 0.5) { run.set(a.id, 0); continue; }
      movingFrames++;
      const got = Math.hypot(a.position.x - p.x, a.position.z - p.z) / DT;
      ratios.push(got / want);
      const stuck = got < want * 0.25;
      const r = stuck ? (run.get(a.id) ?? 0) + 1 : 0;
      run.set(a.id, r);
      if (stuck) {
        spotFrames++;
        perState[a.state] = (perState[a.state] ?? 0) + 1;
      }
      const w = worst.get(a.id);
      if (!w || r > w.frames) worst.set(a.id, { frames: r, state: a.state, speed: +want.toFixed(2), atS: +(i / FPS).toFixed(2), got: +got.toFixed(3) });
    }
  };

  play(engine, rec, { frames: RUN, timeline, onFrame });

  ratios.sort((x, y) => x - y);
  const pct = (q) => (ratios.length ? +ratios[Math.floor(ratios.length * q)].toFixed(3) : null);
  const out = {
    label, runS: RUN / FPS,
    framesAskingToMove: movingFrames,
    framesGoingNowhere: spotFrames,
    percentOfMovingFrames: movingFrames ? +(100 * spotFrames / movingFrames).toFixed(2) : 0,
    byState: perState,
    longestStreakS: +(Math.max(0, ...[...worst.values()].map((w) => w.frames)) / FPS).toFixed(2),
    worstPerAgent: [...worst.entries()].map(([id, w]) => ({ id, streakS: +(w.frames / FPS).toFixed(2), state: w.state, askedFor: w.speed, gotMs: w.got, atS: w.atS })).sort((a, b) => b.streakS - a.streakS),
    actualOverIntended: { p05: pct(0.05), p25: pct(0.25), p50: pct(0.5), p95: pct(0.95) },
  };
  engine.dispose();
  return out;
}

const restore = quiet();
const plain = await measure('plain firefight, nobody dies', { kills: false, RUN: sec(40) });
const gutted = await measure('both squads gutted', { kills: true, RUN: sec(60) });
restore();
console.log(JSON.stringify({ plain, gutted }, null, 1));
process.exit(0);

