/**
 * THROWAWAY probe — delete before the shift ends.
 *
 * Agents spend a quarter of their moving frames going nowhere. Two rescues
 * already exist in `_move`: a stall timer on `this.speed < 0.25` and a stuck
 * timer on `controller.lastMoveBlocked`. Which of them, if either, is awake
 * while a man sprints on the spot for six seconds?
 */
import { boot } from './harness.mjs';
import { play, engagePlay } from './play.mjs';

const FPS = 60;
const sec = (s) => Math.round(s * FPS);
const DT = 1 / 60;

const quiet = () => {
  const w = console.warn, l = console.log;
  console.warn = () => {}; console.log = () => {};
  return () => { console.warn = w; console.log = l; };
};

const restore = quiet();
const { engine, rec } = await boot({ quality: 'low', deterministic: true, width: 960, height: 600, dpr: 1 });
engagePlay(engine, { populate: true });
const ai = engine.ctx.peek('ai');

const prev = new Map();
const run = new Map();
const rows = [];
// count how often each rescue actually fires, for everyone, all run
const fired = { stall: 0, stuck: 0, vault: 0 };
for (const a of ai.agents) {
  const goTo = a._goTo.bind(a);
  a._goTo = (d) => goTo(d);
}

const onFrame = (i) => {
  for (const a of ai.agents) {
    if (!a.alive) continue;
    const p = prev.get(a.id);
    prev.set(a.id, { x: a.position.x, z: a.position.z });
    if (!p) continue;
    const want = a.speed;
    if (want <= 0.5) { run.set(a.id, 0); continue; }
    const got = Math.hypot(a.position.x - p.x, a.position.z - p.z) / DT;
    const stuck = got < want * 0.25;
    const r = stuck ? (run.get(a.id) ?? 0) + 1 : 0;
    run.set(a.id, r);
    if (stuck) {
      rows.push({
        t: +(i / FPS).toFixed(2), id: a.id, state: a.state, run: r,
        want: +want.toFixed(2), got: +got.toFixed(3),
        blocked: !!a.controller?.lastMoveBlocked,
        stuckT: +(a.stuckTimer ?? 0).toFixed(2),
        stallT: +(a.stallTimer ?? 0).toFixed(2),
        vaulting: a.vaultT !== undefined && a.vaultT !== null && a.vaultT < 1,
        idx: a.pathIndex, len: a.pathLen, pending: a.pathPending,
        dWp: a.pathIndex < a.pathLen ? +a.position.distanceTo(a.path[a.pathIndex]).toFixed(2) : null,
        repathT: +a.repathTimer.toFixed(2),
      });
    }
  }
};

play(engine, rec, { frames: sec(40), onFrame });
restore();

// the longest streak per agent, and the whole of the worst one
const byAgent = new Map();
for (const r of rows) {
  const b = byAgent.get(r.id) ?? { best: 0, rows: [] };
  if (r.run > b.best) b.best = r.run;
  byAgent.set(r.id, b);
}
console.log('longest on-the-spot streak per agent (frames):',
  JSON.stringify([...byAgent.entries()].map(([id, b]) => ({ id, frames: b.best, s: +(b.best / FPS).toFixed(2) }))));

// how often was the controller admitting to being blocked, during those frames?
const stuckRows = rows.filter((r) => r.run > 30);   // streaks over half a second
console.log(`\nframes inside a >0.5 s on-the-spot streak: ${stuckRows.length}`);
console.log(`  controller.lastMoveBlocked TRUE on: ${stuckRows.filter((r) => r.blocked).length}`);
console.log(`  vaulting on:                       ${stuckRows.filter((r) => r.vaulting).length}`);
console.log(`  path pending on:                   ${stuckRows.filter((r) => r.pending).length}`);
console.log(`  stallTimer > 0 on:                 ${stuckRows.filter((r) => r.stallT > 0).length}`);
