657	  }
658	
659	  const RUN = sec(40);
660	  const BIN = sec(10);
661	  const bins = new Array(Math.ceil(RUN / BIN)).fill(0);
662	  let attempts = 0, deadEnds = 0, deferred = 0, entries = 0;
663	  let throws = 0;
664	  const barred = new Map();      // agent id -> frames blocked back to back
665	  let longestBarred = 0;
666	
667	  // EVERY destination anyone asks for, not just the flank ones. Reported
668	  // rather than asserted: see the note on the pass condition below.
669	  let goToCalls = 0, noRoutes = 0;
670	  const noRouteRun = new Map();  // agent id -> no-route answers back to back
671	  let longestNoRouteRun = 0;
672	  // claims 5 + 6: how long a man was a statue, and how long he was a statue
673	  // with nothing to get behind and nowhere to be.
674	  const stillRun = new Map();
675	  const adriftRun = new Map();
676	  let longestStill = 0, longestAdrift = 0, adriftFrames = 0;
677	  // claim 7: how hard the CoverMap is being worked, and how long one man went
678	  // on asking it a question it kept answering `null`.
679	  let coverQueries = 0, nullPicks = 0;
680	  const nullRun = new Map();
681	  let longestNullRun = 0;
