683	  // A manoeuvre is one _flankPoint search followed by the _goTo it feeds. The
684	  // flag is per agent and cleared every frame, so a search that finds no ground
685	  // at all cannot be charged to somebody else's path request.
686	  for (const a of ai.agents) {
687	    const point = a._flankPoint.bind(a);
688	    a._flankPoint = (...args) => {
689	      a.__flanking = true;
690	      return point(...args);
691	    };
692	    const goTo = a._goTo.bind(a);
693	    a._goTo = (dest) => {
694	      const mine = a.__flanking;
695	      a.__flanking = false;
696	      const ok = goTo(dest);
697	      goToCalls++;
698	      // `!ok` with a pending path is the frame's A* budget talking and the
699	      // request is queued; `!ok` without one is A* saying there is no route at
700	      // all, which is what leaves a man standing.
701	      const dead = !ok && !a.pathPending;
702	      const run = dead ? (noRouteRun.get(a.id) ?? 0) + 1 : 0;
