/**
 * THROWAWAY probe — delete before the shift ends.
 *
 * Of the frames that go nowhere, how many are the peek shuffle? The branch at
 * agent.js ~763 orders a 0.6 m walk to `stancePos` and re-orders it every frame
 * for as long as the man fails to get there. `_setPath1(dest, 0.1)` with eps
 * 0.1 is that call and only that call (the other caller, `_goTo`, passes 0.45),
 * so tagging it identifies the branch from outside without guessing at state.
 */
import { boot } from './harness.mjs';
import { play, engagePlay } from './play.mjs';

const FPS = 60;
const sec = (s) => Math.round(s * FPS);
const DT = 1 / 60;

const quiet = () => {
  const w = console.warn, l = console.log;
  console.warn = () => {}; console.log = () => {};
  return () => { console.warn = w; console.log = l; };
};

const restore = quiet();
const { engine, rec } = await boot({ quality: 'low', deterministic: true, width: 960, height: 600, dpr: 1 });
engagePlay(engine, { populate: true });
const ai = engine.ctx.peek('ai');

for (const a of ai.agents) {
  const sp = a._setPath1.bind(a);
  a._setPath1 = (dest, eps) => {
    if (eps === 0.1) a.__shuffle = true;
    return sp(dest, eps);
  };
}

const prev = new Map();
const run = new Map();
const shuffleRun = new Map();
let moving = 0, nowhere = 0, nowhereShuffle = 0;
let longestShuffleStall = 0, longestAny = 0;
const detail = [];

const onFrame = (i) => {
  for (const a of ai.agents) {
    const wasShuffle = a.__shuffle;
    a.__shuffle = false;
    if (!a.alive) { run.set(a.id, 0); shuffleRun.set(a.id, 0); prev.delete(a.id); continue; }
    const p = prev.get(a.id);
    prev.set(a.id, { x: a.position.x, z: a.position.z });
    if (!p) continue;
    const want = a.speed;
    if (want <= 0.5) { run.set(a.id, 0); shuffleRun.set(a.id, 0); continue; }
    moving++;
    const got = Math.hypot(a.position.x - p.x, a.position.z - p.z) / DT;
    const stuck = got < want * 0.25;
    const r = stuck ? (run.get(a.id) ?? 0) + 1 : 0;
    run.set(a.id, r);
    if (r > longestAny) longestAny = r;
    const sr = stuck && wasShuffle ? (shuffleRun.get(a.id) ?? 0) + 1 : 0;
    shuffleRun.set(a.id, sr);
    if (sr > longestShuffleStall) longestShuffleStall = sr;
    if (stuck) {
      nowhere++;
      if (wasShuffle) {
        nowhereShuffle++;
        if (sr > 30 && sr % 30 === 0) {
          detail.push({
            t: +(i / FPS).toFixed(2), id: a.id, run: sr,
            dStance: +a.position.distanceTo(a.stancePos).toFixed(3),
            dCover: +a.position.distanceTo(a.coverPos).toFixed(3),
            peeking: !!a.peeking, peekT: +a.peekTimer.toFixed(2),
            stallT: +(a.stallTimer ?? 0).toFixed(2),
            got: +got.toFixed(3),
          });
        }
      }
    }
  }
};

play(engine, rec, { frames: sec(40), onFrame });
restore();

console.log(JSON.stringify({
  framesAskingToMove: moving,
  framesGoingNowhere: nowhere,
  ofWhichPeekShuffle: nowhereShuffle,
  shufflePctOfNowhere: nowhere ? +(100 * nowhereShuffle / nowhere).toFixed(1) : 0,
  longestAnyStallS: +(longestAny / FPS).toFixed(2),
  longestShuffleStallS: +(longestShuffleStall / FPS).toFixed(2),
  detail: detail.slice(0, 24),
}, null, 1));
process.exit(0);

