/**
 * THROWAWAY probe — delete before the shift ends.
 *
 * Classify EVERY going-nowhere frame by who asked for the movement. The first
 * cut of this metric was `speed > 0.5 && covered < 25 %`, and `speed` has three
 * sources that are not "he is trying to walk somewhere":
 *   - the separation floor in `_move` (`if (want < 0.9) want = 0.9`), which
 *     pushes a man off a squadmate whether or not he has anywhere to be;
 *   - the ease-out — `desiredSpeed` drops to 0 and `speed` takes ~0.5 s to
 *     follow, so every stop is half a second of "asking to move";
 *   - the shuffle onto a peek pose, which is a real walk but a 0.6 m one.
 * Only the fourth kind — a path he is following and not advancing along — is
 * the bug. Split them so the gate that follows fences the right number.
 */
import { boot } from './harness.mjs';
import { play, engagePlay } from './play.mjs';

const FPS = 60;
const sec = (s) => Math.round(s * FPS);
const DT = 1 / 60;

const quiet = () => {
  const w = console.warn, l = console.log;
  console.warn = () => {}; console.log = () => {};
  return () => { console.warn = w; console.log = l; };
};

async function measure(label, { kills, RUN }) {
  const { engine, rec } = await boot({ quality: 'low', deterministic: true, width: 960, height: 600, dpr: 1 });
  engagePlay(engine, { populate: true });
  const ai = engine.ctx.peek('ai');
  const squads = (ai.squads ?? []).filter((s) => s.members.length >= 3);

  for (const a of ai.agents) {
    const sp = a._setPath1.bind(a);
    a._setPath1 = (dest, eps) => {
      if (eps === 0.1) a.__shuffle = true;
      return sp(dest, eps);
    };
  }

  const kill = (a) => {
    if (!a?.alive) return;
    const p = a.position;
    a.applyDamage(500, 'torso', { x: p.x, y: p.y + 1.3, z: p.z }, { x: 0, y: 0, z: 1 });
  };
  const timeline = kills ? (drv, eng, i) => {
    if (i === sec(3)) kill(squads[0].members[0]);
    if (i === sec(5)) kill(squads[1].members[0]);
    if (i === sec(7)) kill(squads[0].members.find((m) => m.alive));
    if (i === sec(9)) kill(squads[1].members.find((m) => m.alive));
  } : undefined;

  const prev = new Map();
  const run = new Map();           // travel-stall streak, per agent
  const worst = new Map();
  const kinds = { shuffle: 0, easeOut: 0, separation: 0, travel: 0 };
  let moving = 0, nowhere = 0, travelFrames = 0, travelStalls = 0;
  const rows = [];

  const onFrame = (i) => {
    for (const a of ai.agents) {
      const wasShuffle = a.__shuffle;
      a.__shuffle = false;
      if (!a.alive) { run.set(a.id, 0); prev.delete(a.id); continue; }
      const p = prev.get(a.id);
      prev.set(a.id, { x: a.position.x, z: a.position.z });
      if (!p) continue;
      const got = Math.hypot(a.position.x - p.x, a.position.z - p.z) / DT;

      // What he is actually being ordered to do, read at the source rather than
      // off `speed`. `desiredSpeed` is set fresh every frame by the state that
      // owns him; a travel order is one with a path under it.
      const ordered = a.desiredSpeed > 0.2;
      const travelling = ordered && a.hasMoveTarget && !a.pathPending && !wasShuffle;
      if (travelling) {
        travelFrames++;
        const stalled = got < Math.max(0.25, a.desiredSpeed * 0.25);
        const r = stalled ? (run.get(a.id) ?? 0) + 1 : 0;
        run.set(a.id, r);
        if (stalled) travelStalls++;
        const w = worst.get(a.id);
        if (!w || r > w.frames) worst.set(a.id, { frames: r, state: a.state, atS: +(i / FPS).toFixed(2) });
        if (r > 30 && r % 30 === 0) {
          rows.push({
            t: +(i / FPS).toFixed(2), id: a.id, state: a.state, run: r,
            want: +a.desiredSpeed.toFixed(2), got: +got.toFixed(3),
            wp: `${a.pathIndex}/${a.pathLen}`,
            dWp: a.pathIndex < a.pathLen ? +a.position.distanceTo(a.path[a.pathIndex]).toFixed(2) : null,
            blocked: !!a.controller?.lastMoveBlocked, stallT: +(a.stallTimer ?? 0).toFixed(2),
            cover: !!a.cover, grounded: a.grounded,
          });
        }
      } else run.set(a.id, 0);

      // the old, blunter criterion, kept so the two can be compared directly
      if (a.speed > 0.5) {
        moving++;
        if (got < a.speed * 0.25) {
          nowhere++;
          if (wasShuffle) kinds.shuffle++;
          else if (!ordered) kinds.easeOut++;
          else if (!a.hasMoveTarget && !a.pathPending) kinds.separation++;
          else kinds.travel++;
        }
      }
    }
  };

  play(engine, rec, { frames: RUN, timeline, onFrame });
  const out = {
    label, runS: RUN / FPS,
    blunt: { moving, nowhere, pct: moving ? +(100 * nowhere / moving).toFixed(2) : 0, byCause: kinds },
    travel: {
      frames: travelFrames, stalls: travelStalls,
      pct: travelFrames ? +(100 * travelStalls / travelFrames).toFixed(2) : 0,
      longestS: +(Math.max(0, ...[...worst.values()].map((w) => w.frames)) / FPS).toFixed(2),
      perAgent: [...worst.entries()].map(([id, w]) => ({ id, s: +(w.frames / FPS).toFixed(2), state: w.state, atS: w.atS })).sort((x, y) => y.s - x.s),
    },
    sample: rows.slice(0, 14),
  };
  engine.dispose();
  return out;
}

const restore = quiet();
const plain = await measure('plain firefight, nobody dies', { kills: false, RUN: sec(40) });
const gutted = await measure('both squads gutted', { kills: true, RUN: sec(60) });
restore();
console.log(JSON.stringify({ plain, gutted }, null, 1));
process.exit(0);

