/**
 * THROWAWAY probe — delete before the shift ends.
 *
 * The watchdog in `_move` ends a stall and does not prevent one: the ai-move
 * gate reads 20 % of travel frames stalled on the shipping build and 20.9 % on
 * the build with the watchdog blinded, while the longest streak moves 1.4 s to
 * 6.2 s. One long stall has become four short ones. Why does the man get stuck
 * on the same metre again the moment he is given a fresh route?
 *
 * Two candidates, and they want opposite fixes:
 *   - GEOMETRY: the controller refuses the move, the nav grid thinks the cell
 *     is open, and A* keeps routing through it.
 *   - DEADLOCK: the separation push in `_move` cancels the path direction, so
 *     `_steer` does not point at the waypoint at all and the controller is
 *     happily moving him sideways.
 * Measure the angle between the steer and the waypoint, and count the mates
 * inside the separation radius, on every stalled frame.
 */
import { boot } from './harness.mjs';
import { play, engagePlay } from './play.mjs';

const FPS = 60;
const sec = (s) => Math.round(s * FPS);

const quiet = () => {
  const w = console.warn, l = console.log;
  console.warn = () => {}; console.log = () => {};
  return () => { console.warn = w; console.log = l; };
};

const restore = quiet();
const { engine, rec } = await boot({ quality: 'low', deterministic: true, width: 960, height: 600, dpr: 1 });
engagePlay(engine, { populate: true });
const ai = engine.ctx.peek('ai');

// every destination anyone asks A* for, so a re-request of the same point is
// visible as a repeat rather than inferred
const dests = [];
for (const a of ai.agents) {
  const goTo = a._goTo.bind(a);
  a._goTo = (d) => {
    const ok = goTo(d);
    dests.push({ f: engine.time.frame, id: a.id, x: +d.x.toFixed(2), z: +d.z.toFixed(2), ok, len: a.pathLen });
    return ok;
  };
}

const run = new Map();
const rows = [];
const hist = { steerWithPath: 0, steerAway: 0, blocked: 0, crowded: 0, total: 0 };

const onFrame = (i) => {
  for (const a of ai.agents) {
    if (!a.alive) { run.set(a.id, 0); continue; }
    const trying = a.desiredSpeed > 0.2 && a.hasMoveTarget && !a.pathPending;
    if (!trying) { run.set(a.id, 0); continue; }
    const stalled = (a.progress ?? 0) < Math.max(0.25, a.desiredSpeed * 0.25);
    const r = stalled ? (run.get(a.id) ?? 0) + 1 : 0;
    run.set(a.id, r);
    if (!stalled) continue;

    const wp = a.pathIndex < a.pathLen ? a.path[a.pathIndex] : null;
    if (!wp) continue;
    const wx = wp.x - a.position.x, wz = wp.z - a.position.z;
    const wl = Math.hypot(wx, wz) || 1e-6;
    // `_steer` is the normalised sum of the path direction and every separation
    // push, and it is what the controller was actually handed this frame.
    const sx = a._steer?.x ?? 0, sz = a._steer?.z ?? 0;
    const sl = Math.hypot(sx, sz) || 1e-6;
    const cos = (wx / wl) * (sx / sl) + (wz / wl) * (sz / sl);

    let mates = 0;
    for (const o of ai.agents) {
      if (o === a || !o.alive) continue;
      const rr = (a.radius + o.radius + 0.42) ** 2;
      const dx = a.position.x - o.position.x, dz = a.position.z - o.position.z;
      if (dx * dx + dz * dz <= rr) mates++;
    }

    hist.total++;
    if (cos > 0.7) hist.steerWithPath++;
    if (cos < 0.2) hist.steerAway++;
    if (a.controller?.lastMoveBlocked) hist.blocked++;
    if (mates > 0) hist.crowded++;

    if (r > 45 && r % 45 === 0) {
      rows.push({
        t: +(i / FPS).toFixed(2), id: a.id, state: a.state, run: r,
        dWp: +wl.toFixed(2), cos: +cos.toFixed(2), mates,
        blocked: !!a.controller?.lastMoveBlocked,
        want: +a.desiredSpeed.toFixed(1), got: +(a.progress ?? 0).toFixed(3),
        wp: `${a.pathIndex}/${a.pathLen}`, grounded: a.grounded,
        crouch: a.crouch, vaultCd: +(a.vaultCooldown ?? 0).toFixed(2),
      });
    }
  }
};

play(engine, rec, { frames: sec(40), onFrame });
restore();

// how often the SAME destination came back after a stall dropped it
const repeats = new Map();
for (const d of dests) {
  const k = `${d.id}@${Math.round(d.x)},${Math.round(d.z)}`;
  repeats.set(k, (repeats.get(k) ?? 0) + 1);
}
const worstRepeats = [...repeats.entries()].filter(([, n]) => n > 2).sort((a, b) => b[1] - a[1]).slice(0, 8);

console.log(JSON.stringify({
  stalledFrames: hist.total,
  steerPointingAtWaypoint: hist.steerWithPath,
  steerPointingElsewhere: hist.steerAway,
  controllerSaysBlocked: hist.blocked,
  aMateInsideSeparationRadius: hist.crowded,
  pathRequests: dests.length,
  sameDestinationAskedAgain: worstRepeats.map(([k, n]) => ({ dest: k, times: n })),
  longStalls: rows.slice(0, 20),
}, null, 1));
process.exit(0);

