/**
 * THROWAWAY probe — delete before the shift ends.
 *
 * Two candidate fixes for the residual 20 % stall rate were built and measured
 * and NEITHER moved it: skipping the unreachable waypoint made it worse (1.4 s
 * streak to 7.35 s, 20.0 % to 24.6 %), and releasing the cover claim on a stall
 * left it flat at 20.7 %. So the number is probably not measuring wedging at
 * all.
 *
 * The suspect is the speed ease-out in `_move`:
 *   this.speed += (targetSpeed - this.speed) * min(1, dt * 7)
 * `desiredSpeed` snaps to 4.4 the instant a man is told to run; `speed` takes
 * about a seventh of a second to get most of the way there and `progress`
 * trails it by a frame. Every START of a walk therefore spends a handful of
 * frames below the 25 % floor while nothing whatsoever is wrong. Split the
 * stalled frames by how long the man has been under this travel order.
 */
import { boot } from './harness.mjs';
import { play, engagePlay } from './play.mjs';

const FPS = 60;
const sec = (s) => Math.round(s * FPS);

const quiet = () => {
  const w = console.warn, l = console.log;
  console.warn = () => {}; console.log = () => {};
  return () => { console.warn = w; console.log = l; };
};

const restore = quiet();
const { engine, rec } = await boot({ quality: 'low', deterministic: true, width: 960, height: 600, dpr: 1 });
engagePlay(engine, { populate: true });
const ai = engine.ctx.peek('ai');

const age = new Map();      // id -> frames under the current travel order
let travel = 0, stalled = 0;
const bucket = { fresh: 0, young: 0, settled: 0 };   // <8f, 8-30f, >30f
let settledStall = 0, settledFrames = 0;
const perAgentSettled = new Map();

const onFrame = () => {
  for (const a of ai.agents) {
    const trying = a.alive && a.desiredSpeed > 0.2 && a.hasMoveTarget && !a.pathPending;
    if (!trying) { age.set(a.id, 0); continue; }
    const t = (age.get(a.id) ?? 0) + 1;
    age.set(a.id, t);
    travel++;
    const short = (a.progress ?? 0) < Math.max(0.25, a.desiredSpeed * 0.25);
    if (t > 30) {
      settledFrames++;
      if (short) settledStall++;
      const p = perAgentSettled.get(a.id) ?? { f: 0, s: 0 };
      p.f++; if (short) p.s++;
      perAgentSettled.set(a.id, p);
    }
    if (!short) continue;
    stalled++;
    if (t < 8) bucket.fresh++;
    else if (t <= 30) bucket.young++;
    else bucket.settled++;
  }
};

play(engine, rec, { frames: sec(40), onFrame });
restore();

console.log(JSON.stringify({
  travelFrames: travel,
  stalledFrames: stalled,
  stallPct: +(100 * stalled / travel).toFixed(1),
  byOrderAge: {
    'under 8 frames (0.13 s) — the ease-out': bucket.fresh,
    '8-30 frames (0.13-0.5 s) — still accelerating': bucket.young,
    'over 30 frames (0.5 s+) — genuinely not moving': bucket.settled,
  },
  settledOnly: {
    frames: settledFrames,
    stalls: settledStall,
    pct: settledFrames ? +(100 * settledStall / settledFrames).toFixed(1) : 0,
    perAgent: [...perAgentSettled.entries()].map(([id, p]) => ({ id, pct: +(100 * p.s / p.f).toFixed(1), frames: p.f })),
  },
}, null, 1));
process.exit(0);

