/**
 * _probe-age — throwaway. Splits the travel-stall frames by the AGE of the march
 * order, to test the hypothesis from the handover: most of the remaining 20 %
 * stall rate is the speed ramp (`speed += (target-speed)*min(1,dt*7)`), not a
 * wedge. A man who has just been told to walk is BELOW the 25 % floor for the
 * first handful of frames and nothing is wrong with him.
 *
 * Age = consecutive frames the travel condition has held. That is exactly the
 * window in which `speed` is still spinning up from 0.
 */
import { boot } from './harness.mjs';
import { play, engagePlay } from './play.mjs';

const FPS = 60;
const sec = (s) => Math.round(s * FPS);

const { engine, rec } = await boot({ quality: 'low', deterministic: true, width: 960, height: 600, dpr: 1 });
const ai = engagePlay(engine, { populate: true });

for (const a of ai.agents) {
  const sp = a._setPath1.bind(a);
  a._setPath1 = (dest, eps) => {
    if (eps === 0.1) a.__shuffle = true;
    return sp(dest, eps);
  };
}

const BUCKETS = [
  { name: 'fresh<8', lo: 0, hi: 8 },
  { name: '8-30', lo: 8, hi: 30 },
  { name: 'settled>30', lo: 30, hi: Infinity },
];
const tally = BUCKETS.map(() => ({ frames: 0, stalls: 0 }));
const age = new Map();          // id -> consecutive travel frames
const runSettled = new Map();   // id -> settled-stall streak
let longestSettled = 0;
let travelFrames = 0, travelStalls = 0;
// speed at the moment of a stall, split by bucket — a ramp stall has a LOW
// speed and a rising one; a wedge has a high speed that goes nowhere.
const speedSum = BUCKETS.map(() => 0);
const speedStallSum = BUCKETS.map(() => 0);

const onFrame = () => {
  for (const a of ai.agents) {
    const wasShuffle = a.__shuffle;
    a.__shuffle = false;
    if (!a.alive) { age.set(a.id, 0); runSettled.set(a.id, 0); continue; }
    if (wasShuffle) { age.set(a.id, 0); runSettled.set(a.id, 0); continue; }
    if (!(a.desiredSpeed > 0.2 && a.hasMoveTarget && !a.pathPending)) {
      age.set(a.id, 0); runSettled.set(a.id, 0); continue;
    }
    const n = (age.get(a.id) ?? 0);
    age.set(a.id, n + 1);

    const got = a.progress ?? 0;
    const short = got < Math.max(0.25, a.desiredSpeed * 0.25);
    travelFrames++;
    if (short) travelStalls++;

    const bi = BUCKETS.findIndex((b) => n >= b.lo && n < b.hi);
    tally[bi].frames++;
    speedSum[bi] += a.speed;
    if (short) { tally[bi].stalls++; speedStallSum[bi] += a.speed; }

    if (bi === 2) {
      const r = short ? (runSettled.get(a.id) ?? 0) + 1 : 0;
