/**
 * _probe-wall — throwaway. What is a settled travel-stall frame actually made
 * of? The previous shift established the man presses frontally into geometry the
 * nav grid calls open. This asks the questions a FIX needs answered:
 *
 *   1. does the controller report a wall on those frames, and how frontal is it
 *      (angle between the steer and the reversed wall normal)?
 *   2. would a tangential nudge have anywhere to go — i.e. is the wall normal
 *      usable as an axis, or is he in a corner with two of them?
 *   3. does the PATH pick a side for us? For each stall frame, the dot of both
 *      tangent candidates with the direction to the next waypoint beyond the one
 *      he is stuck on. If the path bends around the obstacle this is free.
 */
import { boot } from './harness.mjs';
import { play, engagePlay } from './play.mjs';

const FPS = 60;
const sec = (s) => Math.round(s * FPS);

const { engine, rec } = await boot({ quality: 'low', deterministic: true, width: 960, height: 600, dpr: 1 });
const ai = engagePlay(engine, { populate: true });

for (const a of ai.agents) {
  const sp = a._setPath1.bind(a);
  a._setPath1 = (dest, eps) => { if (eps === 0.1) a.__shuffle = true; return sp(dest, eps); };
}

const age = new Map();
let travel = 0, stalls = 0, settled = 0, settledStalls = 0;
let wallSeen = 0, blocked = 0, grounded = 0;
const angBins = [0, 0, 0, 0, 0, 0];   // 0-30,30-60,60-90,90-120,120-150,150-180
let hintUsable = 0, hintTie = 0, noNext = 0;
let sumWallY = 0;
const speedHist = [0, 0, 0, 0];       // <0.5, 0.5-2, 2-3.5, >3.5
let progSum = 0;

const onFrame = () => {
  for (const a of ai.agents) {
    const wasShuffle = a.__shuffle;
    a.__shuffle = false;
    if (!a.alive || wasShuffle || !(a.desiredSpeed > 0.2 && a.hasMoveTarget && !a.pathPending)) {
      age.set(a.id, 0); continue;
    }
    const n = age.get(a.id) ?? 0;
    age.set(a.id, n + 1);
    travel++;
    const short = (a.progress ?? 0) < Math.max(0.25, a.desiredSpeed * 0.25);
    if (short) stalls++;
    if (n < 30) continue;
    settled++;
    if (!short) continue;
    settledStalls++;

    const c = a.controller;
    progSum += a.progress ?? 0;
    const sp = a.speed;
    speedHist[sp < 0.5 ? 0 : sp < 2 ? 1 : sp < 3.5 ? 2 : 3]++;
    if (c?.lastMoveBlocked) blocked++;
    if (c?.grounded) grounded++;
    if (!c?.touchingWall) continue;
    wallSeen++;
    sumWallY += Math.abs(c.wallNormal.y);

    // angle between where he wants to go and the wall he is pushing into
    const sx = a._steer.x, sz = a._steer.z;
    const nx = -c.wallNormal.x, nz = -c.wallNormal.z;
    const nl = Math.hypot(nx, nz) || 1e-6;
    const cos = Math.max(-1, Math.min(1, (sx * nx + sz * nz) / nl));
    const deg = Math.acos(cos) * 180 / Math.PI;
    angBins[Math.min(5, Math.floor(deg / 30))]++;

    // does the path hand us a side? tangent = wall normal rotated 90 deg
    const tx = -c.wallNormal.z / nl, tz = c.wallNormal.x / nl;
    const next = a.path[Math.min(a.pathIndex + 1, a.pathLen - 1)];
    if (!next || a.pathIndex + 1 > a.pathLen - 1) { noNext++; continue; }
    const dx = next.x - a.position.x, dz = next.z - a.position.z;
    const dl = Math.hypot(dx, dz) || 1e-6;
    const proj = (dx * tx + dz * tz) / dl;
    if (Math.abs(proj) > 0.25) hintUsable++; else hintTie++;
  }
};

play(engine, rec, { frames: sec(40), onFrame });

const pct = (n, d) => (d ? +(100 * n / d).toFixed(1) : 0);
const out = {
  travelFrames: travel, travelStallPct: pct(stalls, travel),
  settledFrames: settled, settledStallFrames: settledStalls,
  ofSettledStalls: {
    touchingWallPct: pct(wallSeen, settledStalls),
    lastMoveBlockedPct: pct(blocked, settledStalls),
    groundedPct: pct(grounded, settledStalls),
    meanProgress: +(progSum / Math.max(1, settledStalls)).toFixed(3),
    speedHist: { under0_5: speedHist[0], to2: speedHist[1], to3_5: speedHist[2], over3_5: speedHist[3] },
  },
  steerVsWallDeg: { d0_30: angBins[0], d30_60: angBins[1], d60_90: angBins[2], d90_120: angBins[3], d120_150: angBins[4], d150_180: angBins[5] },
  meanAbsWallNormalY: +(sumWallY / Math.max(1, wallSeen)).toFixed(3),
  pathHint: { usable: hintUsable, tie: hintTie, lastWaypoint: noNext },
};
engine.dispose();
console.log('@@' + JSON.stringify(out, null, 2));

