/**
 * _probe-wall — throwaway. What is a settled travel-stall frame actually made of?
 *
 * Round 1 killed the inherited diagnosis: `touchingWall` was 0 % of 1223 settled
 * stall frames while `lastMoveBlocked` was 95.7 % — and `lastMoveBlocked` is set
 * by ANY sweep contact, including the floor a grounded man is standing on every
 * frame he applies gravity. So "he presses frontally into a wall" was never
 * measured; the flag that said so says nothing.
 *
 * Round 2 asks what actually holds him: is there a steering vector at all, is
 * there a waypoint, how far is it, and how much ground does he really cover.
 */
import { boot } from './harness.mjs';
import { play, engagePlay } from './play.mjs';

const FPS = 60;
const sec = (s) => Math.round(s * FPS);

const { engine, rec } = await boot({ quality: 'low', deterministic: true, width: 960, height: 600, dpr: 1 });
const ai = engagePlay(engine, { populate: true });

for (const a of ai.agents) {
  const sp = a._setPath1.bind(a);
  a._setPath1 = (dest, eps) => { if (eps === 0.1) a.__shuffle = true; return sp(dest, eps); };
}

const age = new Map();
let travel = 0, settled = 0, hits = 0;
let noSteer = 0, noWp = 0, crouching = 0, vaulting = 0, sepActive = 0, lodIrr = 0;
const progHist = [0, 0, 0, 0];        // 0, <0.05, 0.05-0.5, >0.5
const wpDist = [0, 0, 0, 0];          // <0.8, 0.8-2, 2-6, >6
const byState = {};
let sumSteer = 0, sumSpeed = 0, sumProg = 0, sumWp = 0;
let planeSum = 0, steppedUp = 0;
const samples = [];

const onFrame = () => {
  for (const a of ai.agents) {
    const wasShuffle = a.__shuffle;
    a.__shuffle = false;
    if (!a.alive || wasShuffle || !(a.desiredSpeed > 0.2 && a.hasMoveTarget && !a.pathPending)) {
      age.set(a.id, 0); continue;
    }
    const n = age.get(a.id) ?? 0;
    age.set(a.id, n + 1);
    travel++;
    if (n < 30) continue;
    settled++;
    const got = a.progress ?? 0;
    if (!(got < Math.max(0.25, a.desiredSpeed * 0.25))) continue;
    hits++;

    const sl = Math.hypot(a._steer.x, a._steer.z);
    sumSteer += sl; sumSpeed += a.speed; sumProg += got;
    if (sl < 0.01) noSteer++;
    const hasWp = a.pathIndex < a.pathLen;
    if (!hasWp) noWp++;
    if (a.crouch) crouching++;
    if (a.animator?.vaulting) vaulting++;
    if (a.lodIrrelevant) lodIrr++;
    if (a.controller) { planeSum += a.controller._planeCount ?? 0; if (a.controller.steppedUp > 0) steppedUp++; }

    // is a squadmate inside the separation radius this frame?
    for (const o of ai.agents) {
      if (o === a || !o.alive) continue;
      const dx = a.position.x - o.position.x, dz = a.position.z - o.position.z;
      if (dx * dx + dz * dz <= (a.radius + o.radius + 0.42) ** 2) { sepActive++; break; }
    }

    progHist[got === 0 ? 0 : got < 0.05 ? 1 : got < 0.5 ? 2 : 3]++;
    byState[a.state] = (byState[a.state] ?? 0) + 1;

    if (hasWp) {
      const wp = a.path[a.pathIndex];
      const d = Math.hypot(wp.x - a.position.x, wp.z - a.position.z);
      sumWp += d;
      wpDist[d < 0.8 ? 0 : d < 2 ? 1 : d < 6 ? 2 : 3]++;
      if (samples.length < 12 && d > 2) {
        samples.push({
          id: a.id, state: a.state, sp: +a.speed.toFixed(2), prog: +got.toFixed(3),
          steer: +sl.toFixed(3), wpD: +d.toFixed(2), idx: a.pathIndex, len: a.pathLen,
          y: +a.position.y.toFixed(2), wpY: +wp.y.toFixed(2),
          grounded: a.grounded, planes: a.controller?._planeCount ?? -1,
        });
      }
    }
  }
};

play(engine, rec, { frames: sec(40), onFrame });

const pct = (n) => (hits ? +(100 * n / hits).toFixed(1) : 0);
const out = {
  travelFrames: travel, settledFrames: settled, settledStallFrames: hits,
  sharePct: {
    zeroSteer: pct(noSteer), noWaypoint: pct(noWp), crouching: pct(crouching),
    vaulting: pct(vaulting), squadmateInRadius: pct(sepActive), lodIrrelevant: pct(lodIrr),
    steppedUp: pct(steppedUp),
  },
  mean: {
    steerLen: +(sumSteer / Math.max(1, hits)).toFixed(3),
    speed: +(sumSpeed / Math.max(1, hits)).toFixed(2),
    progress: +(sumProg / Math.max(1, hits)).toFixed(3),
    waypointDist: +(sumWp / Math.max(1, hits - noWp)).toFixed(2),
    planes: +(planeSum / Math.max(1, hits)).toFixed(2),
  },
  progressHist: { zero: progHist[0], under0_05: progHist[1], to0_5: progHist[2], over0_5: progHist[3] },
  waypointDistHist: { under0_8: wpDist[0], to2: wpDist[1], to6: wpDist[2], over6: wpDist[3] },
  byState,
  samples,
};
engine.dispose();
console.log('@@' + JSON.stringify(out, null, 2));

