/**
 * _probe-wall — throwaway, round 3. Read the actual contact planes.
 *
 * Round 1 killed the inherited diagnosis ("presses frontally into a wall"):
 * `touchingWall` was 0 % of 1223 settled stall frames, and the flag that was
 * read instead, `lastMoveBlocked`, is set by ANY sweep contact.
 * Round 2: he has a steer (len 1), a waypoint (mean 4.0 m away), is not
 * crouched, not vaulting, no squadmate on 81 % of them — and covers 0.22 m/s
 * while asking for 3.57.
 *
 * Round 3 reads `_planes` straight out of the controller after the step, which
 * is the horizontal slide's contact set, and asks what those normals are.
 */
import { boot } from './harness.mjs';
import { play, engagePlay } from './play.mjs';

const FPS = 60;
const sec = (s) => Math.round(s * FPS);

const { engine, rec } = await boot({ quality: 'low', deterministic: true, width: 960, height: 600, dpr: 1 });
const ai = engagePlay(engine, { populate: true });

for (const a of ai.agents) {
  const sp = a._setPath1.bind(a);
  a._setPath1 = (dest, eps) => { if (eps === 0.1) a.__shuffle = true; return sp(dest, eps); };
  // What the horizontal slide was ASKED for and what it gave back.
  const c = a.controller;
  if (c) {
    const slide = c._slide.bind(c);
    c._slide = (dx, dy, dz) => {
      const bx = c.position.x, bz = c.position.z;
      const r = slide(dx, dy, dz);
      if (Math.abs(dy) < 1e-9) {
        a.__asked = Math.hypot(dx, dz);
        a.__got = Math.hypot(c.position.x - bx, c.position.z - bz);
      }
      return r;
    };
  }
}

const age = new Map();
let travel = 0, settled = 0, hits = 0;
// plane normal ny: up(>0.9), slope(0.643..0.9), wall(-0.5..0.643), ceil(<-0.5)
const nyBins = [0, 0, 0, 0];
const planeCountHist = [0, 0, 0, 0, 0, 0];
let allPlanesUp = 0, anyWallPlane = 0;
let askSum = 0, gotSum = 0, eatenFrames = 0;
// how much of the horizontal request survives, bucketed
const keepHist = [0, 0, 0, 0, 0];  // <1%,1-10%,10-40%,40-80%,>80%
const samples = [];

const onFrame = () => {
  for (const a of ai.agents) {
    const wasShuffle = a.__shuffle;
    a.__shuffle = false;
    if (!a.alive || wasShuffle || !(a.desiredSpeed > 0.2 && a.hasMoveTarget && !a.pathPending)) {
      age.set(a.id, 0); continue;
    }
    const n = age.get(a.id) ?? 0;
    age.set(a.id, n + 1);
    travel++;
    if (n < 30) continue;
    settled++;
    if (!((a.progress ?? 0) < Math.max(0.25, a.desiredSpeed * 0.25))) continue;
    hits++;

    const c = a.controller;
    const pc = c?._planeCount ?? 0;
    planeCountHist[Math.min(5, pc)]++;

    let up = 0, wall = 0;
    const nys = [];
    for (let i = 0; i < pc; i++) {
      const ny = c._planes[i * 3 + 1];
      nys.push(+ny.toFixed(3));
      const b = ny > 0.9 ? 0 : ny >= 0.643 ? 1 : ny > -0.5 ? 2 : 3;
      nyBins[b]++;
      if (b <= 1) up++; else wall++;
    }
    if (pc > 0 && wall === 0) allPlanesUp++;
    if (wall > 0) anyWallPlane++;

    const asked = a.__asked ?? 0, got = a.__got ?? 0;
    askSum += asked; gotSum += got;
    const keep = asked > 1e-9 ? got / asked : 1;
    if (asked > 1e-9) {
      eatenFrames++;
      keepHist[keep < 0.01 ? 0 : keep < 0.1 ? 1 : keep < 0.4 ? 2 : keep < 0.8 ? 3 : 4]++;
    }
    if (samples.length < 10 && pc > 0 && keep < 0.1) {
      samples.push({
        id: a.id, state: a.state, sp: +a.speed.toFixed(2),
        askedMm: +(asked * 1000).toFixed(2), gotMm: +(got * 1000).toFixed(2),
        planes: pc, ny: nys, y: +a.position.y.toFixed(3),
        steer: [+a._steer.x.toFixed(2), +a._steer.z.toFixed(2)],
        steppedUp: +(c.steppedUp ?? 0).toFixed(3),
      });
    }
  }
};

play(engine, rec, { frames: sec(40), onFrame });

const pct = (n, d = hits) => (d ? +(100 * n / d).toFixed(1) : 0);
const out = {
  travelFrames: travel, settledStallFrames: hits,
  planeCountHist: { p0: planeCountHist[0], p1: planeCountHist[1], p2: planeCountHist[2], p3: planeCountHist[3], p4: planeCountHist[4], p5plus: planeCountHist[5] },
  planeNormalNy: { flatUp_over0_9: nyBins[0], walkableSlope_0_643to0_9: nyBins[1], wall_under0_643: nyBins[2], ceiling: nyBins[3] },
  framesWhereEveryPlaneFacesUpPct: pct(allPlanesUp),
  framesWithAnyWallPlanePct: pct(anyWallPlane),
  horizontalSlide: {
    askedMmPerFrame: +(1000 * askSum / Math.max(1, eatenFrames)).toFixed(2),
    gotMmPerFrame: +(1000 * gotSum / Math.max(1, eatenFrames)).toFixed(2),
    keptPct: +(100 * gotSum / Math.max(1e-9, askSum)).toFixed(1),
    keepHist: { under1: keepHist[0], to10: keepHist[1], to40: keepHist[2], to80: keepHist[3], over80: keepHist[4] },
  },
  samples,
};
engine.dispose();
console.log('@@' + JSON.stringify(out, null, 2));

