/**
 * _probe-ground — throwaway. What does `slopeLimit` actually change for an agent?
 *
 * `src/ai/agent.js` passed 48 (degrees) where the controller wants radians, so
 * `cosSlope` was `Math.cos(48) = -0.640` — every contact walkable down to 130
 * degrees. Correcting it reads WORSE on this level (travelStallPct 20.0 -> 25.4,
 * total ground 339.8 m -> 323.6 m), so before choosing, find out through which
 * consumer of `cosSlope` the difference arrives:
 *
 *   probeGround thin trace   `found = thin && hit.ny >= cos`   -> grounded
 *   move() step-offset       `wasGrounded` gates the whole lift/slide/drop
 *   move() cliff-cling guard `dropped > want && _hit2.ny < cos`
 *   _classifyContact         ground vs wall vs ceiling
 */
import { boot } from './harness.mjs';
import { play, engagePlay } from './play.mjs';

const FPS = 60;
const sec = (s) => Math.round(s * FPS);

const { engine, rec } = await boot({ quality: 'low', deterministic: true, width: 960, height: 600, dpr: 1 });
const ai = engagePlay(engine, { populate: true });

let stepOffsetUsed = 0, moves = 0, cliffGuard = 0, thinFound = 0, wideFound = 0, notFound = 0;
for (const a of ai.agents) {
  const c = a.controller;
  if (!c) continue;
  const mv = c.move.bind(c);
  c.move = (dx, dy, dz) => {
    moves++;
    if (c.grounded && !(dy > 1e-6) && c.stepHeight > 1e-4 && (dx * dx + dz * dz) > 1e-10) stepOffsetUsed++;
    return mv(dx, dy, dz);
  };
  const pg = c.probeGround.bind(c);
  c.probeGround = () => {
    const r = pg();
    // which trace answered: re-run the thin one's test cheaply via groundNormal
    if (c.grounded) { if (c.groundNormal.y >= c.cosSlope) thinFound++; else wideFound++; }
    else notFound++;
    return r;
  };
}

const age = new Map();
let travel = 0, stalls = 0, airborne = 0, alive = 0, steppedUp = 0, stepSum = 0;
let onSteep = 0, wallFlag = 0;
const ground = new Map();

const onFrame = () => {
  for (const a of ai.agents) {
    if (!a.alive) { age.set(a.id, 0); continue; }
    alive++;
    const c = a.controller;
    if (c) {
      if (!c.grounded) airborne++;
      if (c.onSteepSlope) onSteep++;
      if (c.touchingWall) wallFlag++;
      if (c.steppedUp > 0) { steppedUp++; stepSum += c.steppedUp; }
    }
    ground.set(a.id, (ground.get(a.id) ?? 0) + (a.progress ?? 0) / FPS);
    if (!(a.desiredSpeed > 0.2 && a.hasMoveTarget && !a.pathPending)) { age.set(a.id, 0); continue; }
    age.set(a.id, (age.get(a.id) ?? 0) + 1);
    travel++;
    if ((a.progress ?? 0) < Math.max(0.25, a.desiredSpeed * 0.25)) stalls++;
  }
};

play(engine, rec, { frames: sec(40), onFrame });

const pct = (n, d) => (d ? +(100 * n / d).toFixed(1) : 0);
const covered = [...ground.values()].reduce((s, m) => s + m, 0);
const out = {
  cosSlope: +ai.agents[0].controller.cosSlope.toFixed(4),
  travelFrames: travel, travelStallPct: pct(stalls, travel),
  totalGroundM: +covered.toFixed(1),
  controllerMoves: moves,
  stepOffsetUsedPct: pct(stepOffsetUsed, moves),
  probeGround: { thinAnswered: thinFound, wideFallbackAnswered: wideFound, airborne: notFound },
  perAliveFramePct: {
    airborne: pct(airborne, alive), onSteepSlope: pct(onSteep, alive),
    touchingWall: pct(wallFlag, alive), steppedUp: pct(steppedUp, alive),
  },
  meanStepUpMm: +(1000 * stepSum / Math.max(1, steppedUp)).toFixed(1),
};
engine.dispose();
console.log('@@' + JSON.stringify(out));

