/**
 * _probe-nowall — throwaway. The sidestep in `_move` only fires when the
 * controller reported a wall LAST frame. Open question from the previous shift:
 * how many of the remaining stall frames have no wall under them at all, and
 * how long do those streaks run?
 *
 * Samples exactly what the sidestep branch sees, by wrapping `_move`: the
 * `touchingWall` flag is read BEFORE the original runs, because `c.move()` at
 * the bottom of `_move` overwrites it, and `stallTimer`/`sidestepping` after,
 * because both are written inside.
 */
import { boot } from './harness.mjs';
import { play, engagePlay } from './play.mjs';

const FPS = 60;
const RUN = Math.round(40 * FPS);

const { engine, rec } = await boot({ quality: 'low', deterministic: true, width: 960, height: 600, dpr: 1 });
engagePlay(engine, { populate: true });
const ai = engine.ctx.peek('ai');

let eligible = 0;          // stallTimer > 0.25 after this frame's _move
let withWall = 0;          // ...and the branch saw a wall
let fired = 0;             // ...and it actually steered along it
let noWp = 0;              // ...eligible but no waypoint at all
let noWallWithWp = 0;      // THE NUMBER: eligible, has a waypoint, no wall
let aliveFrames = 0;
let steep = 0, blocked = 0, crowded = 0, airborne = 0;

const run = new Map();     // id -> current no-wall stall streak
const worst = new Map();   // id -> longest, with context
let longest = 0;
const byState = {};
const samplesNoWall = [];

for (const a of ai.agents) {
  const orig = a._move.bind(a);
  a._move = (dt) => {
    const con = a.controller;
    const wallBefore = !!con?.touchingWall;
    const steepBefore = !!con?.onSteepSlope;
    const blockedBefore = !!con?.lastMoveBlocked;
    const groundedBefore = !!con?.grounded;
    // Same expression the branch's `wp` comes from, evaluated at entry.
    const hadWp = !!(a.hasMoveTarget && a.pathIndex < a.pathLen);
    const wpX = hadWp ? a.path[a.pathIndex].x : 0;
    const wpZ = hadWp ? a.path[a.pathIndex].z : 0;
    const dWp = hadWp ? Math.hypot(wpX - a.position.x, wpZ - a.position.z) : -1;

    // nearest living squadmate, and whether he is inside the separation radius
    let near = Infinity, inSep = false;
    for (const o of ai.agents) {
      if (o === a || !o.alive) continue;
      const d = Math.hypot(a.position.x - o.position.x, a.position.z - o.position.z);
      if (d < near) near = d;
      if (d < a.radius + o.radius + 0.42) inSep = true;
    }

    orig(dt);
    if (!a.alive) { run.set(a.id, 0); return; }
    aliveFrames++;

    if (!(a.stallTimer > 0.25)) { run.set(a.id, 0); return; }
    eligible++;
    if (wallBefore) withWall++;
    if (a.sidestepping) fired++;
    if (!hadWp) noWp++;

    if (wallBefore || !hadWp) { run.set(a.id, 0); return; }

    noWallWithWp++;
    byState[a.state] = (byState[a.state] ?? 0) + 1;
    if (steepBefore) steep++;
    if (blockedBefore) blocked++;
    if (inSep) crowded++;
    if (!groundedBefore) airborne++;

    const r = (run.get(a.id) ?? 0) + 1;
    run.set(a.id, r);
    if (r > longest) longest = r;
    const w = worst.get(a.id);
    if (!w || r > w.frames) worst.set(a.id, { frames: r, state: a.state, dWp: +dWp.toFixed(2), near: +near.toFixed(2) });

    if (samplesNoWall.length < 12000) {
      samplesNoWall.push({
        progress: a.progress, speed: a.speed, want: a.desiredSpeed,
        dWp: +dWp.toFixed(2), near: +near.toFixed(2), inSep, steep: steepBefore, grounded: groundedBefore,
      });
    }
  };
}

play(engine, rec, { frames: RUN });

const med = (arr) => {
  if (!arr.length) return 0;
  const s = [...arr].sort((a, b) => a - b);
  return +s[s.length >> 1].toFixed(3);
};

const out = {
  aliveFrames,
  eligibleFrames: eligible,
  eligiblePctOfAlive: +(100 * eligible / aliveFrames).toFixed(1),
  withWall,
  sidestepFired: fired,
  noWaypoint: noWp,
  NOWALL: noWallWithWp,
  noWallPctOfEligible: eligible ? +(100 * noWallWithWp / eligible).toFixed(1) : 0,
  longestNoWallStallS: +(longest / FPS).toFixed(2),
  perAgentWorst: [...worst.entries()].map(([id, w]) => ({ id, s: +(w.frames / FPS).toFixed(2), ...w })).sort((a, b) => b.s - a.s),
  noWallByState: byState,
  // what is under him on those frames
  ofNoWall: {
    onSteepSlope: steep,
    lastMoveBlocked: blocked,
    insideSeparationRadius: crowded,
    airborne,
    medProgress: med(samplesNoWall.map((s) => s.progress)),
    medSpeed: med(samplesNoWall.map((s) => s.speed)),
    medWant: med(samplesNoWall.map((s) => s.want)),
    medDistToWaypoint: med(samplesNoWall.map((s) => s.dWp)),
    medNearestMate: med(samplesNoWall.map((s) => s.near)),
  },
};

engine.dispose();
console.log('@@' + JSON.stringify(out, null, 1));

